const RANKING=typeof location!=='undefined'?new URLSearchParams(location.search).get('ranking'):null;let rankMode='speedrun',rankScope=['class','year','hall'].includes(RANKING)?RANKING:'class',rankGrade='',rankClass='',rankData=null,rankStarted=false,rankLoading=false;
