const key=()=>`fr-progress-v5:${profile.schoolYear}-${profile.grade}-${profile.classNo}-${profile.number}`;const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();const norm=s=>s.toLowerCase().replace(/\s+/g,'').replace(/[.,·'"「」『』()_[\]-]/g,'');const time=s=>Math.floor(s/60)+'분 '+String(s%60).padStart(2,'0')+'초';const passedCount=s=>Object.keys(s.passed||{}).filter(id=>s.passed[id]).length;const allComplete=()=>['beginner','intermediate','advanced','challenge'].every(m=>P[m].status==='completed');const speedKey=()=>`fr-speed-best-v3:${profile.schoolYear}-${profile.grade}-${profile.classNo}-${profile.number}`;const precise=ms=>{ms=Math.max(0,Math.floor(ms/10)*10);let min=Math.floor(ms/60000),sec=Math.floor(ms%60000/1000),cs=Math.floor(ms%1000/10);return String(min).padStart(2,'0')+':'+String(sec).padStart(2,'0')+'.'+String(cs).padStart(2,'0')};const bestValue=()=>{let a=[Number(PreviewStore41.getItem(speedKey()))||0,Number(profile.serverBest)||0].filter(x=>x>0);return a.length?Math.min(...a):0};const hintCount=s=>Object.values(s.retryRounds||{}).reduce((a,b)=>a+(Number(b)||0),0);const outboxKey='fr-stats-outbox-v1';
function save(){if(profile)PreviewStore41.setItem(key(),JSON.stringify(P))}function getOutbox(){try{let q=JSON.parse(PreviewStore41.getItem(outboxKey))||[];return Array.isArray(q)?q:[]}catch{return[]}}function setOutbox(q){PreviewStore41.setItem(outboxKey,JSON.stringify(q));showSync()}function report(e){let payload={...e,schoolYear:profile.schoolYear,grade:profile.grade,classNo:profile.classNo,className:profile.grade+'학년 '+profile.classNo+'반',studentNumber:profile.number,studentName:profile.name,_tries:0,_nextTry:0};let q=getOutbox();if(!q.some(x=>x.recordId===payload.recordId)){if(payload.eventType==='스피드런완료')q.unshift(payload);else q.push(payload)}setOutbox(q);flushOutbox()}
function jsonp(url,done,timeout=7000){let called=false,cb='frCb_'+Date.now()+'_'+Math.floor(Math.random()*1e6),s=document.createElement('script'),t=null,finish=x=>{if(called)return;called=true;clearTimeout(t);delete window[cb];s.remove();done(x)};window[cb]=finish;s.src=url+(url.includes('?')?'&':'?')+'callback='+cb;s.onerror=()=>finish(null);document.head.appendChild(s);t=setTimeout(()=>finish(null),timeout)}
function wireItems(items){return items.map(({_tries,_nextTry,...x})=>x)}
function flushOutbox(manual=false){if(syncing)return;let q=getOutbox();if(!q.length){syncPhase='';showSync();return}let now=Date.now(),ready=q.filter(x=>manual||!x._nextTry||x._nextTry<=now).sort((a,b)=>(b.eventType==='스피드런완료')-(a.eventType==='스피드런완료')).slice(0,15);if(!ready.length){scheduleSync(2500);return}syncing=true;syncPhase='sending';showSync();let ids=ready.map(x=>x.recordId);fetch(STATS,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({version:'2.8',batch:wireItems(ready)}),keepalive:true}).then(()=>{syncPhase='checking';showSync();setTimeout(()=>jsonp(STATS+'?action=statusBatch&recordIds='+encodeURIComponent(ids.join(',')),r=>{syncing=false;let saved=new Set(r?.savedIds||[]),current=getOutbox(),stamp=Date.now();if(saved.size){current=current.filter(x=>!saved.has(x.recordId));lastSyncAt=stamp;PreviewStore41.setItem('fr-last-sync-v1',String(stamp))}current=current.map(x=>ids.includes(x.recordId)&&!saved.has(x.recordId)?{...x,_tries:(x._tries||0)+1,_nextTry:stamp+Math.min(60000,2500*Math.pow(2,Math.min(4,x._tries||0)))+Math.floor(Math.random()*1500)}:x);setOutbox(current);syncPhase='';if(current.length)scheduleSync(1200);else showSync()},1000),900)}).catch(()=>{syncing=false;markBatchFailed(ids);scheduleSync(3000)})}
function markBatchFailed(ids){let now=Date.now();setOutbox(getOutbox().map(x=>ids.includes(x.recordId)?{...x,_tries:(x._tries||0)+1,_nextTry:now+3000+Math.floor(Math.random()*2000)}:x))}function scheduleSync(delay=5000){clearTimeout(syncTimer);syncTimer=setTimeout(flushOutbox,delay);showSync()}function manualSync(){if(!getOutbox().length){alert('모든 기록이 서버에 저장되어 있습니다.');return}flushOutbox(true)}function syncLabel(){let n=getOutbox().length;if(!n)return'✓ 서버 저장 완료';if(syncPhase==='sending')return`☁ ${n}건 전송 중…`;if(syncPhase==='checking')return`🔎 ${n}건 서버 확인 중…`;return`☁ 전송 대기 ${n}건 · 눌러서 전송`}function showSync(){let el=document.querySelector('.sync'),n=getOutbox().length;if(el){el.textContent=syncLabel();el.className='sync '+(n?(syncPhase?'busy':'wait'):'');el.onclick=manualSync;el.setAttribute('role','button');el.tabIndex=0;el.title=n?'눌러서 서버 저장을 다시 시도합니다.':'서버 저장 확인이 완료되었습니다.'}}
function unlocked(m){if(teacherUnlocked||m==='beginner'||m==='results')return true;if(m==='intermediate')return P.beginner.status==='completed';if(m==='advanced')return P.intermediate.status==='completed';if(m==='challenge')return P.advanced.status==='completed';return allComplete()}
function revealHint(label,round){let seen=0;return [...label].map(ch=>{if(!/[가-힣A-Za-z0-9]/.test(ch))return ch;seen++;return seen<=round?ch:'○'}).join('')}function teacherMenu(){return previewTeacher41()}function teacherOff(){teacherUnlocked=false;PreviewSession41.removeItem('fr-teacher-v1');view='results';render()}
function setProfile(p){let fallback={...p,schoolYear:new Date().getFullYear(),serverBest:0};app.innerHTML=`<main class="profile"><section class="shell center"><h2>기록을 불러오는 중입니다…</h2><p>잠시만 기다려 주세요.</p></section></main>`;loadProfileInfo(p,info=>{profile={...fallback,...(info?.ok?{schoolYear:Number(info.schoolYear)||fallback.schoolYear,serverBest:Number(info.bestMs)||0}:{})};PreviewStore41.setItem('fr-student-v2',JSON.stringify(profile));if(profile.serverBest){let local=Number(PreviewStore41.getItem(speedKey()))||0;if(!local||profile.serverBest<local)PreviewStore41.setItem(speedKey(),String(profile.serverBest))}try{P=JSON.parse(PreviewStore41.getItem(key()))||fresh()}catch{P=fresh()}practice={mode:null,state:null};speed=null;view='beginner';render();clock()})}
function loadProfileInfo(p,done){let called=false,timer=null,cb='frProfile_'+Date.now()+'_'+Math.floor(Math.random()*1e6),script=document.createElement('script'),finish=data=>{if(called)return;called=true;if(timer)clearTimeout(timer);delete window[cb];script.remove();done(data)};window[cb]=finish;script.src=STATS+'?action=profile&grade='+encodeURIComponent(p.grade)+'&classNo='+encodeURIComponent(p.classNo)+'&studentNumber='+encodeURIComponent(p.number)+'&callback='+encodeURIComponent(cb);script.onerror=()=>finish(null);document.head.appendChild(script);timer=setTimeout(()=>finish(null),5000)}
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v2.8</span></h1><p>학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function shell(body){let bonusOpen=allComplete()||teacherUnlocked,tabs=['beginner','intermediate','advanced','challenge','results',...(bonusOpen?['practice','speedrun']:[])];return `<header class="header"><div class="headerin"><div><p class="eyebrow">1789 — 1799</p><h1>프랑스 혁명 학습 게임 <span class="version">v2.8</span></h1></div><div class="student"><span>👤 ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</span><button class="btn alt" onclick="profileScreen()">학생 정보 변경</button></div></div></header><main class="wrap"><nav class="tabs">${tabs.map(x=>{let regular=['beginner','intermediate','advanced','challenge'].includes(x),lock=regular&&!unlocked(x),label=x==='results'?'결과':x==='practice'?'연습':x==='speedrun'?'⚡ 스피드런':names[x]+(P[x].status==='completed'?' ✓':lock?' 🔒':'');return `<button class="tab ${view===x?'active':''} ${lock?'locked':''}" ${lock?'disabled':''} onclick="go('${x}')">${label}</button>`}).join('')}</nav>${body}</main><div class="sync">${getOutbox().length?'☁ 기록 전송 대기 '+getOutbox().length+'건':'✓ 기록 전송 완료'}</div>`}
function go(v){if((v==='practice'||v==='speedrun')&&!allComplete()&&!teacherUnlocked)return;if(['beginner','intermediate','advanced','challenge'].includes(v)&&!unlocked(v))return;view=v;render();clock()}function start(m){if(m==='beginner'||m==='intermediate'){let q={...freshQ(m),status:'active',run:uid()};if(m==='intermediate')q.sequence=shuffle(q.sequence);P[m]=q}else P[m]={...freshO((m==='advanced'?Q:CH).length),status:'active',run:uid(),deck:shuffle((m==='advanced'?Q:CH).map(x=>x.id))};save();render();clock()}function shuffle(a){a=[...a];for(let i=a.length-1;i;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function completionButton(m){if(allComplete())return `<button class="btn alt" onclick="openPractice('${m}')">연습 모드에서 다시 풀기</button>`;let next={beginner:'intermediate',intermediate:'advanced',advanced:'challenge'}[m];return next?`<button class="btn" onclick="go('${next}')">다음 ${names[next]}으로</button>`:''}function openPractice(m){if(!allComplete())return;view='practice';startPractice(m)}
function startPage(m,n){let rules=m==='beginner'||m==='intermediate'?`<div class="rules"><b>풀이 규칙</b><br>첫 도전에는 힌트 없이 문제마다 2번의 기회가 있습니다. 2번 모두 틀리면 다음 문제로 넘어가며, 틀린 문제만 다시 출제됩니다. 재도전할 때마다 정답의 글자가 한 글자씩 더 공개되고 재도전 횟수에는 제한이 없습니다. 중급 문제 순서는 무작위입니다.</div>`:'';return `<section class="shell quiz center"><p class="eyebrow">${names[m]} · ${n}문제</p><h2>${names[m]} 학습을 시작할까요?</h2><p>시작 버튼을 누르면 풀이 시간이 기록됩니다.</p>${rules}<button class="btn" onclick="start('${m}')">▶ 시작</button></section>`}
function finishQuiz(m,s){s.status='completed';s.notice='';let details=quizItems(m).map((q,i)=>({questionId:i+1,questionTitle:q.title,attempts:Number(s.totalAttempts?.[q.id])||0,retryRounds:Number(s.retryRounds?.[q.id])||0,passed:!!s.passed?.[q.id],firstTryCorrect:Number(s.totalAttempts?.[q.id])===1}));report({recordId:s.run+'-complete',mode:names[m],eventType:'급수완료',elapsedSeconds:s.elapsed,attempts:Object.values(s.totalAttempts||{}).reduce((a,b)=>a+(Number(b)||0),0),hintCount:hintCount(s),correctCount:quizItems(m).length,totalQuestions:quizItems(m).length,questionResults:details})}
function advanceQuiz(m,notice=''){let s=P[m];if(s.pos<s.sequence.length-1){s.pos++;s.answer='';s.result='';s.roundAttempts=0;s.qtime=0;s.notice=notice;save();render();return}if(s.phase==='first')s.firstPassDone=true;let failed=quizItems(m).map(x=>x.id).filter(id=>!s.passed[id]);if(!failed.length){finishQuiz(m,s);save();render();return}s.phase='retry';s.sequence=m==='intermediate'?shuffle(failed):failed;s.pos=0;s.answer='';s.result='';s.roundAttempts=0;s.qtime=0;failed.forEach(id=>s.retryRounds[id]=(s.retryRounds[id]||0)+1);s.notice=notice||`1차 도전이 끝났습니다. 미합격 ${failed.length}문제에 다시 도전합니다.`;save();render()}
function quiz(m){let s=P[m];if(s.status==='not_started')return startPage(m,quizItems(m).length);if(s.status==='completed')return `<section class="shell quiz center"><p class="eyebrow">${names[m]} 최종 완료</p><h2>${quizItems(m).length}문제를 모두 합격했습니다!</h2><p>총 소요시간 <b>${time(s.elapsed)}</b> · 힌트 <b>${hintCount(s)}회</b> · 첫 입력 정답 <b>${s.first}/${quizItems(m).length}</b></p>${completionButton(m)}</section>`;let q=Q.find(x=>x.id===s.sequence[s.pos]),retry=s.phase==='retry',round=s.retryRounds[q.id]||0,hint=retry?`<div class="hintbox">💡 ${round}회차 힌트 <span class="hintword">${revealHint(ANSWER_LABEL[q.id],round)}</span></div>`:'';return `<section class="shell quiz"><div class="top"><div><p class="eyebrow">${names[m]} ${retry?'재도전':'1차 도전'} ${s.pos+1} / ${s.sequence.length}${retry?`<span class="retry-badge">재도전 ${round}회</span>`:''}</p><h2>${m==='beginner'?'설명을 읽어보세요':'그림을 살펴보세요'}</h2></div><span class="pill">⏱ ${time(s.elapsed)}</span></div><div class="progress"><i style="width:${((s.pos+1)/s.sequence.length)*100}%"></i></div>${m==='intermediate'?`<img class="qimg" src="${IMAGES[q.img-1]}">`:''}<div class="question">${q.prompt}</div>${hint}<form class="answer" onsubmit="answer(event,'${m}')"><input id="ans" value="${esc(s.answer)}" oninput="P['${m}'].answer=this.value;P['${m}'].result='';P['${m}'].notice='';save()" placeholder="정답을 입력하세요" autofocus><button class="btn">${s.result==='good'?'다음':'확인'}</button></form><div class="feedback ${s.result==='bad'?'bad':s.result==='good'?'good':s.notice?'skip':''}">${s.result==='bad'?`아직 정답이 아니에요. 이번 차례 ${s.roundAttempts}/2회 · 누적 ${s.totalAttempts[q.id]||0}회`:s.result==='good'?`✓ 정답입니다! <b>${ANSWER_LABEL[q.id]}</b> · 총 ${s.totalAttempts[q.id]}번 만에 합격<br><small>Enter를 누르면 다음 문제로 넘어갑니다.</small>`:s.notice||'띄어쓰기는 달라도 정답으로 인정됩니다.'}</div></section>`}
function answer(e,m){e.preventDefault();let s=P[m],q=Q.find(x=>x.id===s.sequence[s.pos]);if(s.result==='good'){advanceQuiz(m);return}if(!s.answer.trim())return;s.roundAttempts++;s.totalAttempts[q.id]=(s.totalAttempts[q.id]||0)+1;let total=s.totalAttempts[q.id],ok=q.a.map(norm).includes(norm(s.answer));if(ok){s.result='good';s.passed[q.id]=true;if(total===1)s.first++;save();render();return}if(s.roundAttempts>=2){advanceQuiz(m,'이전 문제는 2회 오답으로 재도전 문제에 남았습니다. 다음 재도전에서는 정답의 일부가 힌트로 표시됩니다.');return}s.result='bad';save();render()}
function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function order(m){let s=P[m],items=m==='advanced'?Q:CH,n=items.length;if(s.status==='not_started')return startPage(m,n);if(s.status==='completed')return `<section class="shell quiz center"><p class="eyebrow">${names[m]} 완료</p><h2>${n}개 사건을 모두 맞혔습니다!</h2><p>총 소요시간 <b>${time(s.elapsed)}</b> · 정답 확인 <b>${s.history.length}회</b></p>${completionButton(m)}</section>`;let correct=s.slots.filter((id,i)=>id===i+1).length;return `<section class="shell"><div class="orderhead"><div><p class="eyebrow">${names[m]} · ${n}개</p><h2>혁명의 흐름을 완성하세요</h2></div><span class="pill">⏱ ${time(s.elapsed)}</span></div>${m==='challenge'?'<div class="orderhint"><strong>💡 순서 힌트:</strong> 루이 16세의 국외 탈출 실패 → 1791년 헌법 제정·입헌군주제 시행<br>탈출 실패 직후 곧바로 왕정이 폐지된 것은 아닙니다.</div>':''}<div class="grid">${s.slots.map((id,i)=>slot(m,id,i,items)).join('')}</div><div class="checkrow"><span>${s.checked?correct+'개 정답입니다. 빨간 카드를 다시 옮겨보세요.':''}</span><button class="btn" onclick="check('${m}')" ${s.slots.some(x=>!x)?'disabled':''}>정답 확인</button></div><div class="deck"><h3>사건 카드</h3><p>카드를 클릭한 뒤 빈칸을 클릭하거나, 원하는 칸으로 드래그하세요. 아래 카드를 더블클릭하면 가장 앞의 빈칸에 놓입니다. 놓은 카드는 더블클릭하거나 ×를 누르면 돌아옵니다.</p><div class="cards ${m==='advanced'?'described':''}">${s.deck.map(id=>card(m,id,items)).join('')}</div></div></section>`}
function slot(m,id,i,items){let s=P[m],it=items.find(x=>x.id===id),cl=id?'filled':'';if(s.checked&&id)cl+=id===i+1?' ok':' bad';return `<div class="slot ${cl}" role="button" draggable="${id?'true':'false'}" onclick="slotClick('${m}',${i})" ondblclick="slotDouble(event,'${m}',${i})" ondragstart="dragStart(event,'${m}',${id||'null'})" ondragend="dragEnd()" ondragover="event.preventDefault()" ondrop="dropSlot(event,'${m}',${i})"><span class="num">${i+1}</span>${id?`<button class="remove" aria-label="카드 되돌리기" onclick="event.stopPropagation();removeSlot('${m}',${i})">×</button><img class="cardimg" src="${IMAGES[it.img-1]}"><span class="title">${it.title}</span>`:'+'}</div>`}
function card(m,id,items){let it=items.find(x=>x.id===id),desc=m==='advanced';return `<button class="card ${desc?'described':''} ${P[m].selected===id?'sel':''}" draggable="true" onclick="cardClick('${m}',${id})" ondblclick="cardDouble(event,'${m}',${id})" ondragstart="dragStart(event,'${m}',${id})" ondragend="dragEnd()"><img class="cardimg" src="${IMAGES[it.img-1]}">${desc?`<span class="cardcopy"><strong>${it.title}</strong><small>${DESC[id]}</small></span>`:`<span class="title">${it.title}</span>`}</button>`}
function slotClick(m,i){if(dragging)return;clearTimeout(slotTimer);slotTimer=setTimeout(()=>place(m,i),230)}function slotDouble(e,m,i){e.preventDefault();clearTimeout(slotTimer);removeSlot(m,i)}function cardClick(m,id){if(dragging)return;clearTimeout(cardTimer);cardTimer=setTimeout(()=>selectCard(m,id),230)}function cardDouble(e,m,id){e.preventDefault();clearTimeout(cardTimer);autoPlace(m,id)}function autoPlace(m,id){let s=P[m],i=s.slots.findIndex(x=>x===null);if(i<0)return;s.selected=id;place(m,i)}function dragStart(e,m,id){if(!id){e.preventDefault();return}dragging=true;e.dataTransfer.setData('text/plain',JSON.stringify({m,id}));e.dataTransfer.effectAllowed='move'}function dragEnd(){setTimeout(()=>dragging=false,0)}function dropSlot(e,m,i){e.preventDefault();try{let d=JSON.parse(e.dataTransfer.getData('text/plain'));if(d.m!==m)return;P[m].selected=d.id;place(m,i)}catch(_){}}function removeSlot(m,i){let s=P[m],id=s.slots[i];if(!id)return;s.slots[i]=null;if(!s.deck.includes(id))s.deck.push(id);s.selected=null;s.checked=false;save();render()}function selectCard(m,id){P[m].selected=P[m].selected===id?null:id;render()}function place(m,i){let s=P[m];if(!s.selected){if(s.slots[i]){s.selected=s.slots[i];render()}return}let id=s.selected,old=s.slots.indexOf(id),d=s.slots[i];if(old>=0)s.slots[old]=null;s.slots[i]=id;s.deck=s.deck.filter(x=>x!==id);if(d&&d!==id){if(old>=0)s.slots[old]=d;else s.deck.push(d)}s.selected=null;s.checked=false;save();render()}
function check(m){let s=P[m],n=s.slots.length,c=s.slots.filter((id,i)=>id===i+1).length;s.history.push(c);let no=s.history.length;s.checked=true;if(c===n){s.status='completed';report({recordId:s.run+'-complete',mode:names[m],eventType:'급수완료',attempts:no,hintCount:0,elapsedSeconds:s.elapsed,correctCount:n,totalQuestions:n})}save();render()}
function practicePage(){if(!practice.mode)return `<section class="shell quiz center"><p class="eyebrow">전체 완료 보너스</p><h2>연습할 급수를 선택하세요</h2><p>연습 결과는 기존 성적과 진행 기록을 바꾸지 않으며 구글 시트에도 전송되지 않습니다.</p><div class="modepick">${[['beginner','설명을 읽고 단답식으로 답하기'],['intermediate','그림을 보고 단답식으로 답하기'],['advanced','설명 있는 12개 사건 순서 맞추기'],['challenge','14개 사건 전체 순서 맞추기']].map(([m,d])=>`<button onclick="startPractice('${m}')"><strong>${names[m]}</strong><small>${d}</small></button>`).join('')}</div></section>`;return practice.mode==='beginner'||practice.mode==='intermediate'?practiceQuiz():practiceOrder()}
function startPractice(m){practice.mode=m;practice.state=m==='beginner'||m==='intermediate'?{status:'active',sequence:quizItems(m).map(x=>x.id),pos:0,answer:'',result:'',attempts:0,elapsed:0}:{...freshO((m==='advanced'?Q:CH).length),status:'active',deck:shuffle((m==='advanced'?Q:CH).map(x=>x.id))};render();clock()}
function leavePractice(){practice={mode:null,state:null};render()}
function practiceQuiz(){let m=practice.mode,s=practice.state;if(s.status==='completed')return `<section class="shell quiz center"><p class="eyebrow">${names[m]} 연습 완료</p><h2>${quizItems(m).length}문제를 모두 맞혔습니다!</h2><p>연습시간 <b>${time(s.elapsed)}</b> · 총 입력 <b>${s.attempts}회</b></p><div class="bonus-actions" style="justify-content:center"><button class="btn" onclick="startPractice('${m}')">다시 연습</button><button class="btn alt" onclick="leavePractice()">다른 급수 선택</button></div></section>`;let q=Q.find(x=>x.id===s.sequence[s.pos]);return `<section class="shell quiz"><div class="practicebar"><div><p class="eyebrow">연습 · ${names[m]} ${s.pos+1}/${quizItems(m).length}</p><h2>${m==='beginner'?'설명을 읽어보세요':'그림을 살펴보세요'}</h2></div><div><span class="pill">⏱ ${time(s.elapsed)}</span> <button class="btn alt" onclick="leavePractice()">급수 선택</button></div></div>${m==='intermediate'?`<img class="qimg" src="${IMAGES[q.img-1]}">`:''}<div class="question">${q.prompt}</div><form class="answer" onsubmit="practiceAnswer(event)"><input id="ans" value="${esc(s.answer)}" oninput="practice.state.answer=this.value;practice.state.result=''" placeholder="정답을 입력하세요" autofocus><button class="btn">${s.result==='good'?'다음':'확인'}</button></form><div class="feedback ${s.result==='bad'?'bad':s.result==='good'?'good':''}">${s.result==='bad'?'아직 정답이 아니에요. 다시 생각해 보세요.':s.result==='good'?`✓ 정답입니다! <b>${ANSWER_LABEL[q.id]}</b><br><small>Enter를 누르면 다음 문제로 넘어갑니다.</small>`:'연습 기록은 정규 성적에 반영되지 않습니다.'}</div></section>`}
function practiceAnswer(e){e.preventDefault();let s=practice.state,q=Q.find(x=>x.id===s.sequence[s.pos]);if(s.result==='good'){if(s.pos===s.sequence.length-1)s.status='completed';else{s.pos++;s.answer='';s.result=''}render();return}if(!s.answer.trim())return;s.attempts++;s.result=q.a.map(norm).includes(norm(s.answer))?'good':'bad';render()}
function practiceOrder(){let m=practice.mode,s=practice.state,items=m==='advanced'?Q:CH;if(s.status==='completed')return `<section class="shell quiz center"><p class="eyebrow">${names[m]} 연습 완료</p><h2>${items.length}개 사건을 모두 맞혔습니다!</h2><p>연습시간 <b>${time(s.elapsed)}</b> · 정답 확인 <b>${s.history.length}회</b></p><div class="bonus-actions" style="justify-content:center"><button class="btn" onclick="startPractice('${m}')">다시 연습</button><button class="btn alt" onclick="leavePractice()">다른 급수 선택</button></div></section>`;return bonusOrder('practice',s,items,m==='advanced',`연습 · ${names[m]}`)}
function speedPage(){let best=bestValue();if(!speed)return `<section class="shell quiz center"><p class="eyebrow">전체 완료 보너스</p><h2>⚡ 고급 ${Q.length}개 스피드런</h2><p>설명과 힌트 없이 그림과 사건 제목만 보고 가장 빠르게 순서를 완성하세요.</p><p class="best">나의 최고 기록: <b>${best?precise(best):'기록 없음'}</b></p><div class="rules"><b>스피드런 규칙</b><br>모든 칸이 채워지는 순간 자동 판정됩니다. <b>첫 판정에서 모두 맞힌 무오답 기록만</b> 개인 최고기록과 공식 순위에 등록됩니다. 오답이 있어도 끝까지 수정하여 완주시간을 확인할 수 있지만 공식 기록에는 등록되지 않습니다.</div><button class="btn" onclick="startSpeed()">⚡ 스피드런 시작</button></section>`;if(speed.status==='completed'){let official=speed.officialEligible&&speed.errorChecks===0,diff=speed.previousBest?speed.previousBest-speed.finishedMs:0,msg=official?(!speed.previousBest?'⚡ 첫 무오답 완주! 공식 기록으로 저장되었습니다.':speed.isBest?`⚡ 무오답 신기록입니다! 이전 기록보다 ${precise(diff)} 단축했습니다.`:'무오답 완주입니다! 공식 기록으로 등록되었습니다.'):`완주 기록은 ${precise(speed.finishedMs)}입니다. 오답 판정 ${speed.errorChecks}회가 있어 공식 순위와 개인 최고기록에는 등록되지 않습니다.`;return `<section class="shell quiz center"><p class="eyebrow">${official?'공식 스피드런 완주':'스피드런 연습 완주'}</p><h2 class="speedtime">${precise(speed.finishedMs)}</h2><div class="speedfinish ${official?'':'unofficial'}">${msg}</div><p class="best">나의 공식 최고 기록: <b>${bestValue()?precise(bestValue()):'기록 없음'}</b>${official?' · 무오답':' · 이번 기록은 미등록'}</p><div class="bonus-actions" style="justify-content:center"><button class="btn" onclick="startSpeed()">다시 도전</button><button class="btn alt" onclick="speed=null;render()">설명으로</button></div></section>`}return bonusOrder('speedrun',speed,Q,false,'⚡ 스피드런')}
function startSpeed(){clearTimeout(speedJudgeTimer);let best=bestValue();speed={...freshO(Q.length),status:'active',deck:shuffle(Q.map(x=>x.id)),startedAt:performance.now(),elapsedMs:0,previousBest:best,finishedMs:0,isBest:false,officialEligible:true,errorChecks:0,pendingFinishMs:0,run:uid()};render();clock()}function cancelSpeed(){if(confirm('스피드런을 중단할까요? 현재 기록은 저장되지 않습니다.')){clearTimeout(speedJudgeTimer);speed=null;render();clock()}}
function bonusOrder(kind,s,items,described,label){let correct=s.slots.filter((id,i)=>id===i+1).length,timer=kind==='speedrun'?`<div class="speedstats"><span class="speedstat">🏆 나의 공식 최고 기록<b>${s.previousBest?precise(s.previousBest):'—'}</b></span><span class="speedstat">⚡ 현재 시간<b id="speedtime">${precise(performance.now()-s.startedAt)}</b></span><button class="btn alt" onclick="cancelSpeed()">중단하고 돌아가기</button></div>`:`<span class="pill">⏱ ${time(s.elapsed)}</span>`,check=kind==='speedrun'?`<div class="checkrow"><span>${s.checked?`${correct}개 정답입니다. 오답이 있어 이번 도전은 공식 기록에서 제외됩니다. 빨간 카드를 고쳐 완주해 보세요.`:'모든 칸을 채우면 즉시 자동 판정됩니다.'}</span><span class="autojudge">⚡ 자동 판정</span></div>`:`<div class="checkrow"><span>${s.checked?correct+'개 정답입니다. 빨간 카드를 다시 옮겨보세요.':''}</span><button class="btn" onclick="bonusCheck('${kind}')" ${s.slots.some(x=>!x)?'disabled':''}>정답 확인</button></div>`;return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">${label} · ${items.length}개</p><h2>혁명의 흐름을 완성하세요</h2></div><div>${timer} ${kind==='practice'?'<button class="btn alt" onclick="leavePractice()">급수 선택</button>':''}</div></div><div class="grid">${s.slots.map((id,i)=>bonusSlot(kind,id,i,items)).join('')}</div>${check}<div class="deck"><h3>사건 카드</h3><p>클릭 후 빈칸 클릭, 드래그, 더블클릭 자동 배치를 모두 사용할 수 있습니다.</p><div class="cards ${described?'described':''}">${s.deck.map(id=>bonusCard(kind,id,items,described)).join('')}</div></div></section>`}
function bonusState(kind){return kind==='speedrun'?speed:practice.state}function bonusSlot(kind,id,i,items){let s=bonusState(kind),it=items.find(x=>x.id===id),cl=id?'filled':'';if(s.checked&&id)cl+=id===i+1?' ok':' bad';return `<div class="slot ${cl}" role="button" draggable="${id?'true':'false'}" onclick="bonusSlotClick('${kind}',${i})" ondblclick="bonusSlotDouble(event,'${kind}',${i})" ondragstart="bonusDragStart(event,'${kind}',${id||'null'})" ondragend="dragEnd()" ondragover="event.preventDefault()" ondrop="bonusDrop(event,'${kind}',${i})"><span class="num">${i+1}</span>${id?`<button class="remove" aria-label="카드 되돌리기" onclick="event.stopPropagation();bonusRemove('${kind}',${i})">×</button><img class="cardimg" src="${IMAGES[it.img-1]}"><span class="title">${it.title}</span>`:'+'}</div>`}
function bonusCard(kind,id,items,described){let s=bonusState(kind),it=items.find(x=>x.id===id);return `<button class="card ${described?'described':''} ${s.selected===id?'sel':''}" draggable="true" onclick="bonusCardClick('${kind}',${id})" ondblclick="bonusCardDouble(event,'${kind}',${id})" ondragstart="bonusDragStart(event,'${kind}',${id})" ondragend="dragEnd()"><img class="cardimg" src="${IMAGES[it.img-1]}">${described?`<span class="cardcopy"><strong>${it.title}</strong><small>${DESC[id]}</small></span>`:`<span class="title">${it.title}</span>`}</button>`}
function bonusSlotClick(k,i){if(dragging)return;clearTimeout(slotTimer);slotTimer=setTimeout(()=>bonusPlace(k,i),230)}function bonusSlotDouble(e,k,i){e.preventDefault();clearTimeout(slotTimer);bonusRemove(k,i)}function bonusCardClick(k,id){if(dragging)return;clearTimeout(cardTimer);cardTimer=setTimeout(()=>{let s=bonusState(k);s.selected=s.selected===id?null:id;render()},230)}function bonusCardDouble(e,k,id){e.preventDefault();clearTimeout(cardTimer);let s=bonusState(k),i=s.slots.findIndex(x=>x===null);if(i<0)return;s.selected=id;bonusPlace(k,i)}function bonusDragStart(e,k,id){if(!id){e.preventDefault();return}dragging=true;e.dataTransfer.setData('text/plain',JSON.stringify({k,id}));e.dataTransfer.effectAllowed='move'}function bonusDrop(e,k,i){e.preventDefault();try{let d=JSON.parse(e.dataTransfer.getData('text/plain'));if(d.k!==k)return;bonusState(k).selected=d.id;bonusPlace(k,i)}catch(_){}}function bonusRemove(k,i){let s=bonusState(k),id=s.slots[i];if(!id)return;s.slots[i]=null;if(!s.deck.includes(id))s.deck.push(id);s.selected=null;s.checked=false;render()}
function bonusPlace(k,i){let s=bonusState(k);if(!s.selected){if(s.slots[i]){s.selected=s.slots[i];render()}return}let id=s.selected,old=s.slots.indexOf(id),d=s.slots[i];if(old>=0)s.slots[old]=null;s.slots[i]=id;s.deck=s.deck.filter(x=>x!==id);if(d&&d!==id){if(old>=0)s.slots[old]=d;else s.deck.push(d)}s.selected=null;s.checked=false;if(k==='speedrun'&&!s.slots.some(x=>!x)){s.pendingFinishMs=performance.now()-s.startedAt;queueSpeedJudge()}render()}
function queueSpeedJudge(){clearTimeout(speedJudgeTimer);speedJudgeTimer=setTimeout(judgeSpeed,100)}
function judgeSpeed(){let s=speed;if(!s||s.status!=='active'||s.slots.some(x=>!x))return;let n=s.slots.length,c=s.slots.filter((id,i)=>id===i+1).length;s.history.push(c);s.checked=true;if(c!==n){s.officialEligible=false;s.errorChecks=(s.errorChecks||0)+1;render();return}s.status='completed';s.finishedMs=s.pendingFinishMs||performance.now()-s.startedAt;s.elapsedMs=s.finishedMs;let official=s.officialEligible&&s.errorChecks===0;s.isBest=official&&(!s.previousBest||s.finishedMs<s.previousBest);if(official){if(s.isBest){PreviewStore41.setItem(speedKey(),String(s.finishedMs));profile.serverBest=s.finishedMs}report({recordId:s.run+'-complete',mode:'스피드런',eventType:'스피드런완료',attempts:1,elapsedSeconds:Number((s.finishedMs/1000).toFixed(2)),correctCount:Q.length,totalQuestions:Q.length})}render()}
function bonusCheck(k){if(k==='speedrun'){if(speed&&!speed.slots.some(x=>!x)){speed.pendingFinishMs=performance.now()-speed.startedAt;queueSpeedJudge()}return}let s=bonusState(k),n=s.slots.length,c=s.slots.filter((id,i)=>id===i+1).length;s.history.push(c);s.checked=true;if(c===n)s.status='completed';render()}
