function quizState(s){if(s.status==='completed')return'최종 완료';if(s.status==='not_started')return'시작 전';if(s.firstPassDone)return'재도전 중';return'1차 도전 중'}function results(){let details=['beginner','intermediate'].map(m=>{let s=P[m];return `<article class="result-detail"><h3>${names[m]} 문제별 결과</h3>${quizItems(m).map((q,i)=>{let total=s.totalAttempts?.[q.id]||0,pass=s.passed?.[q.id],retry=s.retryRounds?.[q.id]||0,label=pass?`${total}번 만에 합격${retry?' · 재도전 '+retry+'회':''}`:total?`미합격 · 누적 ${total}회`:'—',title=pass?`${i+1}. ${q.title}`:`${i+1}번 문제`;return `<div><span>${title}</span><strong>${label}</strong></div>`}).join('')}</article>`}).join(''),bonus=allComplete()?`<div class="bonus"><p class="eyebrow">전체 완료 보너스</p><h3>연습과 스피드런이 열렸습니다!</h3><p>연습은 정규 성적에 반영되지 않습니다. 스피드런에서는 고급 ${Q.length}개 사건의 개인 최고 기록에 도전할 수 있습니다.</p><div class="bonus-actions"><button class="btn" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('speedrun')">⚡ 스피드런</button></div></div>`:'';return `<section class="shell"><p class="eyebrow">${profile.schoolYear}학년도 · ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</p><h2>급수별 진행 상황</h2><div class="results">${['beginner','intermediate','advanced','challenge'].map(m=>{let s=P[m],quizMode=m==='beginner'||m==='intermediate',status=quizMode?quizState(s):s.status==='completed'?'완료':s.status==='active'?'진행 중':'시작 전';return `<article class="result ${s.status==='completed'?'done':''}"><p class="eyebrow">${names[m]}</p><h3>${status}</h3><p>${s.status==='not_started'?'아직 시작하지 않았습니다.':'풀이시간 '+time(s.elapsed)}</p>${quizMode?`<p>합격 <b>${passedCount(s)}/${quizItems(m).length}</b> · 첫 입력 정답 <b>${s.first||0}</b></p>`:`<p>정답 확인 <b>${s.history.length}회</b></p>`}</article>`}).join('')}</div>${bonus}${details}</section>`}
function resultsV26(){let cards=['beginner','intermediate','advanced','challenge'].map(m=>{let s=P[m],quizMode=m==='beginner'||m==='intermediate',status=quizMode?quizState(s):s.status==='completed'?'완료':s.status==='active'?'진행 중':'시작 전';return `<article class="result ${s.status==='completed'?'done':''}"><p class="eyebrow">${names[m]}</p><h3>${status}</h3><p>${s.status==='not_started'?'아직 시작하지 않았습니다.':'풀이시간 '+time(s.elapsed)}</p>${quizMode?`<p>합격 <b>${passedCount(s)}/${quizItems(m).length}</b> · 힌트 <b>${hintCount(s)}회</b></p>`:`<p>정답 확인 <b>${s.history.length}회</b></p>`}</article>`}).join(''),bonus=(allComplete()||teacherUnlocked)?`<div class="bonus"><p class="eyebrow">${teacherUnlocked?'교사용 전체 해금':'전체 완료 보너스'}</p><h3>연습과 스피드런을 이용할 수 있습니다.</h3><div class="bonus-actions"><button class="btn" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('speedrun')">⚡ 스피드런</button></div></div>`:'',teacher=`<div class="teacher"><h3>🔒 교사용 메뉴</h3><p>전광판과 수업용 전체 해금은 마스터 코드가 필요합니다.</p><div class="bonus-actions">${teacherUnlocked?`<button class="btn" onclick="window.open(location.pathname+'?ranking=class','_blank')">🏆 전광판 열기</button><button class="btn alt" onclick="teacherOff()">교사용 기능 종료</button>`:`<button class="btn alt" onclick="teacherMenu()">마스터 코드 입력</button>`}</div></div>`;return `<section class="shell"><p class="eyebrow">${profile.schoolYear}학년도 · ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</p><h2>급수별 진행 상황</h2><div class="results">${cards}</div>${bonus}${teacher}</section>`}
function rankingScreenV26(){if(!rankStarted){rankStarted=true;setTimeout(loadRankingV26,0);setInterval(loadRankingV26,10000)}let d=rankData,rows=d?.ranking||[],g=rankGrade||d?.grade||2,c=rankClass||d?.classNo||1,title=rankScope==='class'?g+'학년 '+c+'반':rankScope==='year'?(d?.schoolYear||'—')+'학년도 전체':'역대 명예의 전당',modes=Object.keys(rankLabels).map(k=>`<button class="${rankMode===k?'on':''}" onclick="setRankMode('${k}')">${rankLabels[k]}</button>`).join(''),scopes=['class','year','hall'].map((k,i)=>`<button class="${rankScope===k?'on':''}" onclick="setRankScope('${k}')">${['우리 반','올해 전체','역대'][i]}</button>`).join(''),meta=x=>rankMode==='speedrun'?'':`<span class="hinttag">힌트 ${x.hintCount||0}회</span>`,body=rankError?`<div class="rankempty"><h2 class="rankerror">${rankError}</h2><button class="btn" onclick="loadRankingV26()">다시 불러오기</button></div>`:!d?'<div class="rankempty"><h2>순위를 불러오는 중입니다…</h2></div>':rows.length?`<div class="podium">${[rows[1],rows[0],rows[2]].map((x,i)=>x?`<div class="${['p2','p1','p3'][i]}"><span class="medal">${['🥈','🥇','🥉'][i]}</span><strong>${esc(String(x.name))}</strong><span class="rankmeta">${x.grade}학년 ${x.classNo}반 ${x.studentNumber}번</span><b>${x.display}</b>${meta(x)}</div>`:'<div></div>').join('')}</div><table class="ranktable"><tbody>${rows.map(x=>`<tr><td>${x.rank}위</td><td><div class="rankname">${esc(String(x.name))}</div><div class="rankmeta">${x.schoolYear}학년도 · ${x.grade}학년 ${x.classNo}반 ${x.studentNumber}번 · 확인 ${x.attempts||'-'}회</div>${meta(x)}</td><td>${x.display}</td></tr>`).join('')}</tbody></table>`:'<div class="rankempty"><h2>아직 완료 기록이 없습니다</h2></div>';app.innerHTML=`<main class="rankpage"><section class="rankbox"><div class="rankhero"><div><p class="eyebrow">프랑스 혁명 학습 게임 · v2.9</p><h1>🏆 ${title} 랭킹</h1><span class="ranklive">10초마다 자동 갱신</span></div><div><button class="btn alt" onclick="location.href=location.pathname">게임으로 돌아가기</button> <button class="btn alt" onclick="toggleFull()">⛶ 전체화면</button></div></div><div class="rankcontrols">${modes}</div><div class="rankcontrols">${scopes}<span class="classpick">학년 <input value="${g}" inputmode="numeric" onchange="rankGrade=this.value;loadRankingV26()"> 반 <input value="${c}" inputmode="numeric" onchange="rankClass=this.value;loadRankingV26()"></span></div>${body}<p class="ranknote">일반 급수는 힌트가 적은 순, 같은 경우 완료 시간이 빠른 순입니다. 스피드런은 기록순입니다.</p></section></main>`}
function loadRankingV26(){let token=++rankLoading,url=STATS+'?action=ranking&mode='+encodeURIComponent(rankMode)+'&scope='+encodeURIComponent(rankScope)+(rankGrade?'&grade='+encodeURIComponent(rankGrade):'')+(rankClass?'&classNo='+encodeURIComponent(rankClass):'');rankError='';jsonp(url,data=>{if(token!==rankLoading)return;if(data?.ok){rankData=data;if(!rankGrade)rankGrade=String(data.grade);if(!rankClass)rankClass=String(data.classNo)}else{rankData=null;rankError='통계 서버에 연결할 수 없습니다. 웹앱 배포 주소와 공개 권한을 확인해 주세요.'}render()},8000)}
