function render(){if(RANKING)return rankingScreenV26();if(!profile)return profileScreen();if((view==='practice'||view==='speedrun')&&!allComplete()&&!teacherUnlocked)view='results';if(['beginner','intermediate','advanced','challenge'].includes(view)&&!unlocked(view))view='beginner';let body=view==='beginner'||view==='intermediate'?quiz(view):view==='advanced'||view==='challenge'?order(view):view==='practice'?practicePage():view==='speedrun'?speedPage():resultsV26();app.innerHTML=shell(body);setTimeout(()=>document.querySelector('#ans')?.focus(),0);showSync()}function clock(){clearInterval(tick);clockMark=Date.now();tick=setInterval(()=>{if(view==='speedrun'&&speed?.status==='active'){let el=document.querySelector('#speedtime');if(el)el.textContent=precise(performance.now()-speed.startedAt);return}let now=Date.now();if(now-clockMark<1000)return;clockMark=now;if(view==='practice'&&practice.state?.status==='active'){practice.state.elapsed++;let pill=document.querySelector('.pill');if(pill)pill.textContent='⏱ '+time(practice.state.elapsed);return}if(view==='results'||!P[view]||P[view].status!=='active')return;P[view].elapsed++;if('qtime'in P[view])P[view].qtime++;save();let pill=document.querySelector('.pill');if(pill)pill.textContent='⏱ '+time(P[view].elapsed)},10)}
