function bonusClock(){clearInterval(bonusTick);bonusTick=setInterval(()=>{let el=document.querySelector('#bonusclock'),s=view==='baitrun'?bait:view==='faceoff'?face:view==='matching'?matchGame:null;if(el&&s?.status==='active')el.textContent=precise(bonusNow(s))},31)}
function saveOfficial(mode,keyName,ms,extra={}){let d=loadBonusData(),old=Number(d.best[keyName])||0,isBest=!old||ms<old;if(isBest)d.best[keyName]=ms;d.completions[keyName]=(d.completions[keyName]||0)+1;saveBonusData(d);report({recordId:uid()+'-'+keyName,mode,eventType:'보너스완료',elapsedSeconds:Number((ms/1000).toFixed(2)),attempts:extra.attempts||1,hintCount:extra.hintCount||0,correctCount:Q.length,totalQuestions:Q.length,official:true});return{old,isBest}}
function grantCard(source){let event=CH[Math.floor(Math.random()*CH.length)],roll=Math.random()*100,rar=RARITIES.find(x=>roll<x.max)||RARITIES[0],key=event.id+'-'+rar.id,c=loadCollection();c[key]=(c[key]||0)+1;saveCollection(c);reward={event,rar,count:c[key],source};setTimeout(render,0)}
function rewardModal(){if(!reward)return'';let r=reward;return `<div class="rewardmodal"><div class="rewardbox"><p class="eyebrow">게임 완료 보상</p><h2>${r.rar.name} 카드 획득!</h2>${collectCard(r.event,r.rar,r.count)}<p>${r.source} 완료 보상 · 보유 ${r.count}장</p><button class="btn" onclick="reward=null;render()">도감에 보관</button></div></div>`}
function shell(body){let open=coreComplete()||teacherUnlocked,tabs=['beginner','intermediate','advanced',...(open?['bonus','collection']:[]),'results'];return `<header class="header"><div class="headerin"><div><p class="eyebrow">1789 — 1799</p><h1>프랑스 혁명 학습 게임 <span class="version">v2.8</span></h1></div><div class="student"><span>👤 ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</span><button class="btn alt" onclick="profileScreen()">학생 정보 변경</button></div></div></header><main class="wrap"><nav class="tabs">${tabs.map(x=>{let lock=['intermediate','advanced'].includes(x)&&!unlockedV28(x);return `<button class="tab ${view===x?'active':''} ${lock?'locked':''}" ${lock?'disabled':''} onclick="go('${x}')">${names[x]||x}${P[x]?.status==='completed'?' ✓':lock?' 🔒':''}</button>`}).join('')}</nav>${body}</main><div class="sync ${getOutbox().length?'wait':''}" onclick="manualSync()">${syncLabel()}</div>${rewardModal()}`}
function unlockedV28(m){if(teacherUnlocked||m==='beginner'||m==='results')return true;if(m==='intermediate')return P.beginner.status==='completed';if(m==='advanced')return P.intermediate.status==='completed';return coreComplete()}
function go(v){let bonusViews=['bonus','collection','practice','speedrun','baitrun','faceoff','matching'];if(bonusViews.includes(v)&&!coreComplete()&&!teacherUnlocked)return;if(['beginner','intermediate','advanced'].includes(v)&&!unlockedV28(v))return;view=v;renderV28();clock();bonusClock()}
function completionButton(m){let next={beginner:'intermediate',intermediate:'advanced'}[m];if(next)return `<button class="btn" onclick="go('${next}')">다음 ${names[next]}으로</button>`;if(m==='advanced')return `<button class="btn" onclick="go('bonus')">보너스 게임 열기</button>`;return''}
function bonusHub(){let best=loadBonusData().best||{};return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>공식 규칙으로 완주하면 개인 최고기록과 종합 기록에 반영되고, 매번 사건 카드 한 장을 받습니다.</p><div class="bonusmenu">
 <button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>12개 사건을 무오답으로 빠르게 배열<br>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button>
 <button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>다른 혁명 사건을 피해서 배열<br>공식 기록: 미끼 8장</small></button>
 <button onclick="go('faceoff')"><span class="bonusicon">👁️</span><strong>페이스오프</strong><small>5초간 본 배열을 기억하고 복원<br>힌트는 3초간 다시 공개</small></button>
 <button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>완성형 사건 카드 12쌍 찾기<br>기본형만 공식 기록</small></button>
 </div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}
function finishBonusPage(label,s,keyName,official,note){let b=bestFor(keyName);return `<section class="shell quiz center"><p class="eyebrow">${official?'공식 기록':'연습 기록'}</p><h2>${label} 완료!</h2><h3 class="speedtime">${precise(s.finishedMs)}</h3><p>${note||''}</p><p class="best">나의 공식 최고 기록: <b>${b?precise(b):'기록 없음'}</b></p><div class="bonus-actions" style="justify-content:center"><button class="btn" onclick="restartCurrentBonus()">다시 도전</button><button class="btn alt" onclick="go('bonus')">게임 선택</button></div></section>`}
function restartCurrentBonus(){if(view==='baitrun')startBait(bait?.decoyCount||8);else if(view==='faceoff')startFace();else if(view==='matching')startMatching(matchGame?.variant||'basic')}
function baitPage(){if(!bait)return `<section class="shell quiz center"><p class="eyebrow">🎭 미끼런</p><h2>프랑스 혁명 사건만 찾아 배열하세요</h2><p>영국·미국 혁명 사건이 같은 수만큼 섞여 나옵니다.</p><div class="settingrow">${[4,6,8].map(n=>`<button class="${n===8?'on':''}" onclick="startBait(${n})">미끼 ${n}장 ${n===8?'<small>공식</small>':''}</button>`).join('')}</div><p class="best">나의 공식 최고 기록: <b>${bestFor('baitrun')?precise(bestFor('baitrun')):'기록 없음'}</b></p><button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;if(bait.status==='completed')return finishBonusPage('미끼런',bait,'baitrun',bait.official,bait.official?'미끼 8장·첫 확인 정답으로 공식 기록에 반영되었습니다.':'연습 설정 또는 오답 확인 기록이 있어 공식 순위에는 반영되지 않습니다.');let correct=bait.slots.filter((id,i)=>id==='f'+(i+1)).length;return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">미끼 ${bait.decoyCount}장 ${bait.decoyCount===8?'<span class="officialtag">공식</span>':'<span class="casualtag">연습</span>'}</p><h2>프랑스 혁명 12개를 순서대로 놓으세요</h2></div><div class="speedstats"><span class="speedstat">현재 시간<b id="bonusclock">${precise(bonusNow(bait))}</b></span><button class="btn alt" onclick="bait=null;go('bonus')">중단</button></div></div><div class="grid">${bait.slots.map((id,i)=>baitSlot(id,i)).join('')}</div><div class="checkrow"><span>${bait.checked?`${correct}개가 맞았습니다. 이번 판은 공식 기록에서 제외됩니다.`:''}</span><button class="btn" onclick="checkBait()" ${bait.slots.some(x=>!x)?'disabled':''}>완료 확인</button></div><div class="deck"><h3>사건 카드</h3><p>카드를 클릭한 뒤 빈칸을 누르거나, 더블클릭하면 가장 앞 빈칸으로 이동합니다.</p><div class="baitdeck">${bait.deck.map(baitCard).join('')}</div></div></section>`}
function startBait(n){let ec=n/2,ac=n/2,dec=shuffle(DECOYS.england).slice(0,ec).concat(shuffle(DECOYS.america).slice(0,ac)).map(x=>x.id);bait={status:'active',decoyCount:n,deck:shuffle(Q.map(x=>'f'+x.id).concat(dec)),slots:Array(Q.length).fill(null),selected:null,checked:false,errorChecks:0,startedAt:performance.now(),finishedMs:0,official:n===8};renderV28();bonusClock()}
function baitInfo(id){if(id[0]==='f'){let q=Q[Number(id.slice(1))-1];return{...q,french:true}}return[...DECOYS.england,...DECOYS.america].find(x=>x.id===id)}
function baitCard(id){let x=baitInfo(id);return `<button class="baitcard ${x.french?'':'decoy'} ${bait.selected===id?'sel':''}" onclick="baitSelect('${id}')" ondblclick="baitAuto(event,'${id}')" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${id}')">${x.french?`<img class="cardimg" src="${IMAGES[x.img-1]}">`:`<span class="decoyart">${x.icon}</span>`}<span class="title">${x.title}</span></button>`}
function baitSlot(id,i){let x=id?baitInfo(id):null,cl=id?'filled':'';if(bait.checked&&id)cl+=id==='f'+(i+1)?' ok':' bad';return `<div class="slot ${cl}" onclick="baitPlace(${i})" ondblclick="baitRemove(event,${i})" ondragover="event.preventDefault()" ondrop="baitDrop(event,${i})"><span class="num">${i+1}</span>${id?`${x.french?`<img class="cardimg" src="${IMAGES[x.img-1]}">`:`<span class="decoyart">${x.icon}</span>`}<span class="title">${x.title}</span>`:'+'}</div>`}
function baitSelect(id){bait.selected=bait.selected===id?null:id;renderV28()}function baitAuto(e,id){e.preventDefault();bait.selected=id;let i=bait.slots.findIndex(x=>!x);if(i>=0)baitPlace(i)}function baitDrop(e,i){e.preventDefault();bait.selected=e.dataTransfer.getData('text/plain');baitPlace(i)}function baitRemove(e,i){e.preventDefault();let id=bait.slots[i];if(id){bait.deck.push(id);bait.slots[i]=null;bait.checked=false;renderV28()}}
function baitPlace(i){let id=bait.selected;if(!id){if(bait.slots[i])bait.selected=bait.slots[i];renderV28();return}let old=bait.slots.indexOf(id),dest=bait.slots[i];if(old>=0)bait.slots[old]=null;bait.slots[i]=id;bait.deck=bait.deck.filter(x=>x!==id);if(dest&&dest!==id){if(old>=0)bait.slots[old]=dest;else bait.deck.push(dest)}bait.selected=null;bait.checked=false;renderV28()}
function checkBait(){let ok=bait.slots.every((id,i)=>id==='f'+(i+1));if(!ok){bait.checked=true;bait.errorChecks++;bait.official=false;renderV28();return}bait.status='completed';bait.finishedMs=performance.now()-bait.startedAt;let official=bait.decoyCount===8&&bait.errorChecks===0;bait.official=official;if(official)saveOfficial('미끼런','baitrun',bait.finishedMs);grantCard('미끼런');renderV28()}
function facePage(){if(!face)return `<section class="shell quiz center"><p class="eyebrow">👁️ 페이스오프</p><h2>12장의 원래 위치를 기억하세요</h2><p>5초 공개 후 카드가 섞입니다. 두 장씩 선택하여 서로 자리를 바꾸세요.</p><div class="rules"><b>공식 규칙</b><br>최초 공개 5초 · 힌트 3초 · 첫 완료 확인에서 정답이어야 공식 기록으로 인정됩니다.</div><p class="best">나의 최고 기록: <b>${bestFor('faceoff')?precise(bestFor('faceoff')):'기록 없음'}</b></p><button class="btn" onclick="startFace()">페이스오프 시작</button> <button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;if(face.status==='completed')return finishBonusPage('페이스오프',face,'faceoff',face.official,`힌트 ${face.hints}회 · ${face.official?'공식 기록에 반영되었습니다.':'오답 확인 후 완주하여 연습 기록입니다.'}`);if(face.phase==='preview')return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">원래 배열 공개</p><h2>위치를 기억하세요</h2></div><span class="pill"><b id="previewcount">5</b>초 후 섞입니다</span></div>${faceGrid(face.target,false)}</section>`;return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">페이스오프 · 공식</p><h2>두 카드를 눌러 위치를 교환하세요</h2></div><div class="speedstats"><span class="speedstat">힌트<b>${face.hints}회</b></span><span class="speedstat">현재 시간<b id="bonusclock">${precise(bonusNow(face))}</b></span><button class="btn alt" onclick="face=null;go('bonus')">중단</button></div></div>${faceGrid(face.board,true)}<div class="checkrow"><button class="btn alt" onclick="showFaceHint()" ${face.hinting?'disabled':''}>👁 원래 배열 3초 보기</button><button class="btn" onclick="checkFace()">완료 확인</button></div>${face.checked?'<p class="feedback bad">아직 원래 배열과 다릅니다. 이번 판은 공식 기록에서 제외되지만 끝까지 완성할 수 있습니다.</p>':''}${face.hinting?`<div class="targetoverlay"><div class="targetpanel"><h2>원래 배열 · 3초 힌트</h2>${faceGrid(face.target,false)}</div></div>`:''}</section>`}
function faceGrid(ids,interactive){return `<div class="memorygrid">${ids.map((id,i)=>{let q=Q.find(x=>x.id===id);return `<button class="memorycard ${interactive&&face.selected===i?'selected':''}" ${interactive?`onclick="facePick(${i})"`:''}><span class="num">${i+1}</span><img src="${IMAGES[q.img-1]}"><span class="title">${q.title}</span></button>`}).join('')}</div>`}
function startFace(){let target=shuffle(Q.map(x=>x.id));face={status:'active',phase:'preview',target,board:[],selected:null,hints:0,errorChecks:0,checked:false,startedAt:0,finishedMs:0,official:true};renderV28();let left=5,t=setInterval(()=>{left--;let el=document.querySelector('#previewcount');if(el)el.textContent=left;if(left<=0){clearInterval(t);face.board=shuffleDifferent(target);face.phase='play';face.startedAt=performance.now();renderV28();bonusClock()}},1000)}
function shuffleDifferent(a){let b=shuffle([...a]);if(b.every((x,i)=>x===a[i]))[b[0],b[1]]=[b[1],b[0]];return b}
function facePick(i){if(face.hinting)return;if(face.selected===null){face.selected=i}else if(face.selected===i){face.selected=null}else{[face.board[face.selected],face.board[i]]=[face.board[i],face.board[face.selected]];face.selected=null;face.checked=false}renderV28()}
function showFaceHint(){if(face.hinting)return;face.hints++;face.hinting=true;renderV28();setTimeout(()=>{if(face){face.hinting=false;renderV28()}},3000)}
function checkFace(){let ok=face.board.every((id,i)=>id===face.target[i]);if(!ok){face.errorChecks++;face.official=false;face.checked=true;renderV28();return}face.status='completed';face.finishedMs=performance.now()-face.startedAt;face.official=face.errorChecks===0;if(face.official)saveOfficial('페이스오프','faceoff',face.finishedMs,{hintCount:face.hints});grantCard('페이스오프');renderV28()}
function matchingPage(){if(!matchGame)return `<section class="shell quiz center"><p class="eyebrow">🃏 짝맞추기</p><h2>원하는 카드 방식을 고르세요</h2><div class="modepick"><button onclick="startMatching('basic')"><strong>기본 카드 맞추기</strong><small>그림·제목·설명이 있는 동일 카드끼리 맞추기 · 공식 기록</small></button><button onclick="startMatching('imageTitle')"><strong>그림 ↔ 제목</strong><small>같은 사건의 그림과 제목 연결 · 연습</small></button><button onclick="startMatching('descTitle')"><strong>설명 ↔ 제목</strong><small>설명을 읽고 사건 제목 연결 · 연습</small></button></div><p class="best">기본형 최고 기록: <b>${bestFor('matching')?precise(bestFor('matching')):'기록 없음'}</b></p><button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;if(matchGame.status==='completed')return finishBonusPage('짝맞추기',matchGame,'matching',matchGame.official,`${matchGame.moves}번 뒤집기 · ${matchGame.official?'기본형 공식 기록입니다.':'연습 모드 기록입니다.'}`);return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">짝맞추기 · ${matchGame.variant==='basic'?'<span class="officialtag">공식 기본형</span>':'<span class="casualtag">연습형</span>'}</p><h2>같은 사건의 두 카드를 찾으세요</h2></div><div class="speedstats"><span class="speedstat">뒤집기<b>${matchGame.moves}회</b></span><span class="speedstat">현재 시간<b id="bonusclock">${precise(bonusNow(matchGame))}</b></span><button class="btn alt" onclick="matchGame=null;go('bonus')">중단</button></div></div><div class="matchgrid">${matchGame.cards.map((c,i)=>matchCard(c,i)).join('')}</div></section>`}
function startMatching(variant){let cards=[];Q.forEach(q=>{cards.push({pair:q.id,side:0,q});cards.push({pair:q.id,side:1,q})});matchGame={status:'active',variant,cards:shuffle(cards),open:[],done:[],moves:0,lock:false,startedAt:performance.now(),finishedMs:0,official:variant==='basic'};renderV28();bonusClock()}
function matchCard(c,i){let open=matchGame.open.includes(i)||matchGame.done.includes(i),done=matchGame.done.includes(i),content='';if(open){if(matchGame.variant==='basic'||(matchGame.variant==='imageTitle'&&c.side===0))content=`<img src="${IMAGES[c.q.img-1]}"><span class="title">${c.q.title}</span>`;else if(matchGame.variant==='imageTitle')content=`<span class="title" style="display:grid;place-items:center;height:100%;font-size:16px">${c.q.title}</span>`;else content=`<span class="title" style="display:grid;place-items:center;height:100%;font-size:12px;line-height:1.4">${c.side===0?(DESC[c.q.id]||c.q.prompt):c.q.title}</span>`}else content='<span class="matchback">?</span>';return `<button class="matchcard ${open?'open':''} ${done?'done':''}" onclick="flipMatch(${i})">${content}</button>`}
function flipMatch(i){if(matchGame.lock||matchGame.done.includes(i)||matchGame.open.includes(i))return;matchGame.open.push(i);if(matchGame.open.length===2){matchGame.moves++;let[a,b]=matchGame.open;if(matchGame.cards[a].pair===matchGame.cards[b].pair){matchGame.done.push(a,b);matchGame.open=[];if(matchGame.done.length===matchGame.cards.length)finishMatching()}else{matchGame.lock=true;setTimeout(()=>{matchGame.open=[];matchGame.lock=false;renderV28()},650)}}renderV28()}
function finishMatching(){matchGame.status='completed';matchGame.finishedMs=performance.now()-matchGame.startedAt;if(matchGame.official)saveOfficial('짝맞추기','matching',matchGame.finishedMs,{attempts:matchGame.moves});grantCard('짝맞추기')}
function collectCard(event,rar,count){let q=CH.find(x=>x.id===event.id)||event;return `<article class="collectcard ${rar.id}"><span class="rarity">${rar.name}</span><img src="${IMAGES[q.img-1]}"><h3>${q.title}</h3><p>보유 ${count||0}장</p></article>`}
function collectionPage(){let c=loadCollection(),owned=Object.keys(c).filter(k=>c[k]>0).length;return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">프랑스 혁명 사건 카드</p><h2>📚 카드 도감 ${owned}/70</h2></div><button class="btn alt" onclick="go('bonus')">게임 선택</button></div><p>게임을 끝까지 완료할 때마다 카드 한 장을 받습니다. 같은 사건도 노말·레어·유니크·전설·신화로 수집할 수 있습니다.</p>${RARITIES.map(r=>`<section><h3>${r.name}</h3><div class="collectiongrid">${CH.map(e=>{let n=c[e.id+'-'+r.id]||0;return n?collectCard(e,r,n):`<article class="collectcard ${r.id} lockedcard"><span class="rarity">${r.name}</span><img src="${IMAGES[e.img-1]}"><h3>???</h3><p>미획득</p></article>`}).join('')}</div></section>`).join('')}</section>`}
function resultsV28(){let d=loadBonusData(),b=d.best||{},core=['beginner','intermediate','advanced'].map(m=>{let s=P[m],quizMode=m!=='advanced',status=s.status==='completed'?'완료':s.status==='active'?'진행 중':'시작 전';return `<article class="result ${s.status==='completed'?'done':''}"><p class="eyebrow">${names[m]}</p><h3>${status}</h3><p>${s.status==='not_started'?'아직 시작하지 않았습니다.':'풀이시간 '+time(s.elapsed)}</p>${quizMode?`<p>합격 <b>${passedCount(s)}/${quizItems(m).length}</b></p>`:`<p>정답 확인 <b>${s.history.length}회</b></p>`}</article>`}).join(''),keys=[['speedrun','스피드런'],['baitrun','미끼런'],['faceoff','페이스오프'],['matching','짝맞추기']],ready=keys.every(([k])=>b[k]),sum=ready?keys.reduce((a,[k])=>a+Number(b[k]),0):0;return `<section class="shell"><p class="eyebrow">${profile.schoolYear}학년도 · ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</p><h2>학습 및 공식 기록</h2><div class="results">${core}</div><h2 style="margin-top:28px">보너스 게임 최고기록</h2><table class="summarytable"><tbody>${keys.map(([k,n])=>`<tr><th>${n}</th><td>${b[k]?precise(b[k]):'기록 없음'}</td></tr>`).join('')}<tr><th>종합 기록</th><td>${ready?precise(sum):'네 게임을 모두 완료하면 등록'}</td></tr></tbody></table><div class="bonus-actions"><button class="btn" onclick="go('bonus')">보너스 게임</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div><div class="teacher"><h3>🔒 교사용 메뉴</h3><div class="bonus-actions">${teacherUnlocked?`<button class="btn" onclick="window.open(location.pathname+'?ranking=class','_blank')">🏆 전광판 열기</button><button class="btn alt" onclick="teacherOff()">교사용 기능 종료</button>`:`<button class="btn alt" onclick="teacherMenu()">마스터 코드 입력</button>`}</div></div></section>`}
function speedPageV28(){let page=speedPage();return page}
function renderV28(){if(RANKING)return rankingScreenV26();if(!profile)return profileScreen();let bonusViews=['bonus','collection','practice','speedrun','baitrun','faceoff','matching'];if(bonusViews.includes(view)&&!coreComplete()&&!teacherUnlocked)view='results';if(['beginner','intermediate','advanced'].includes(view)&&!unlockedV28(view))view='beginner';let body=view==='beginner'||view==='intermediate'?quiz(view):view==='advanced'?order(view):view==='bonus'?bonusHub():view==='collection'?collectionPage():view==='practice'?practicePageV28():view==='speedrun'?speedPageV28():view==='baitrun'?baitPage():view==='faceoff'?facePage():view==='matching'?matchingPage():resultsV28();app.innerHTML=shell(body);setTimeout(()=>document.querySelector('#ans')?.focus(),0);showSync()}
function practicePageV28(){if(!practice.mode)return `<section class="shell quiz center"><p class="eyebrow">연습 모드</p><h2>연습할 급수를 선택하세요</h2><p>연습 결과는 기록과 카드 보상에 반영되지 않습니다.</p><div class="modepick">${[['beginner','설명을 읽고 단답식으로 답하기'],['intermediate','그림을 보고 단답식으로 답하기'],['advanced','설명 있는 12개 사건 순서 맞추기']].map(([m,d])=>`<button onclick="startPractice('${m}')"><strong>${names[m]}</strong><small>${d}</small></button>`).join('')}</div><button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;return practice.mode==='beginner'||practice.mode==='intermediate'?practiceQuiz():practiceOrder()}
const originalJudgeSpeed=judgeSpeed;judgeSpeed=function(){let before=speed?.status;originalJudgeSpeed();if(before==='active'&&speed?.status==='completed'){let official=speed.officialEligible&&speed.errorChecks===0;if(official){let d=loadBonusData();d.best.speedrun=!d.best.speedrun||speed.finishedMs<d.best.speedrun?speed.finishedMs:d.best.speedrun;saveBonusData(d)}grantCard('스피드런');renderV28()}};
const DECOY_SHEET='assets/legacy/0dd929947d133345.webp';
/* ===== v2.9 interface and local prototype layer ===== */
let packReward=null,dailyChecked=false,adminView='attendance';
const DEFAULT_V29_SETTINGS={odds:{normal:60,rare:25,unique:10,legend:4,myth:1},weekdays:[1,2,3,4,5],dailyCards:3,cycleDays:20,excludedDates:''};
delete rankLabels.faceoff;
const settingsV29Key='fr-v29-teacher-settings';
function loadV29Settings(){try{return{...DEFAULT_V29_SETTINGS,...JSON.parse(PreviewStore41.getItem(settingsV29Key)||'{}')}}catch{return{...DEFAULT_V29_SETTINGS}}}
function saveV29Settings(x){PreviewStore41.setItem(settingsV29Key,JSON.stringify(x))}
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v2.9</span></h1><p>학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function shell(body){let open=coreComplete()||teacherUnlocked,tabs=['beginner','intermediate','advanced','bonus','collection','results',...(teacherUnlocked?['admin']:[])];return `<header class="header"><div class="headerin"><div><p class="eyebrow">1789 — 1799</p><h1>프랑스 혁명 학습 게임 <span class="version">v2.9</span></h1></div><div class="student"><span>👤 ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</span><button class="btn alt" onclick="profileScreen()">학생 정보 변경</button></div></div></header><main class="wrap"><nav class="tabs">${tabs.map(x=>{let regular=['intermediate','advanced'].includes(x),lock=regular&&!unlockedV28(x)||(['bonus','collection'].includes(x)&&!open),label=x==='results'?'결과':x==='bonus'?'보너스 게임':x==='collection'?'카드 도감':x==='admin'?'교사 관리':names[x];return `<button class="tab ${view===x?'active':''} ${lock?'locked':''}" onclick="go('${x}')">${label}${P[x]?.status==='completed'?' ✓':lock?' 🔒':''}</button>`}).join('')}</nav>${body}</main><div class="sync ${getOutbox().length?'wait':''}" onclick="manualSync()">${syncLabel()}</div>${rewardModal()}`}
function go(v){let open=coreComplete()||teacherUnlocked;if(['bonus','collection'].includes(v)&&!open){alert('보너스 게임과 카드 도감은 초급·중급·고급을 모두 완료하면 해금됩니다.');return}if(v==='admin'&&!teacherUnlocked)return teacherMenu();if(['beginner','intermediate','advanced'].includes(v)&&!unlockedV28(v)){alert('앞 급수를 먼저 완료해야 합니다.');return}view=v;renderV29();clock();bonusClock()}
function bonusHub(){let best=loadBonusData().best||{},daily=loadDailyState();return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>공식 규칙으로 완주하면 개인 최고기록에 반영되고 카드팩을 받습니다.</p><div class="dailybox"><h3>🎁 오늘의 카드팩</h3><p>${daily.lastDate===localDateKey(new Date())?'오늘의 카드 3장을 받았습니다.':'하루 한 번 카드 3장을 받을 수 있습니다.'}</p><div class="streakline"><span class="${daily.streak>=5?'done':''}">5일 레어+</span><span class="${daily.streak>=10?'done':''}">10일 유니크+</span><span class="${daily.streak>=15?'done':''}">15일 전설+</span><span class="${daily.streak>=20?'done':''}">20일 신화</span></div><small>현재 v2.9는 기기 날짜로 시험 작동합니다. Code.gs 연결 후 서버 시간으로 교체됩니다.</small></div><div class="bonusmenu">
 <button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>무오답 순서 배열 · 완료 카드 1장<br>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button>
 <button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>영국·미국 사건을 피해 배열<br>미끼 4/6/8장 → 카드 1/2/3장</small></button>
 <button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>기본 카드 2장 · 고급 카드 4장<br>고급형만 공식 기록</small></button>
 </div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}
function rarityById(id){return RARITIES.find(x=>x.id===id)||RARITIES[0]}
function drawRarity(minIndex=0){let s=loadV29Settings(),odds=RARITIES.map(r=>Number(s.odds?.[r.id])||0),roll=Math.random()*odds.reduce((a,b)=>a+b,0),sum=0,index=0;for(let i=0;i<odds.length;i++){sum+=odds[i];if(roll<sum){index=i;break}}index=Math.max(index,minIndex);return RARITIES[index]}
function grantCards(count,source,minIndex=0){let c=loadCollection(),cards=[];for(let i=0;i<count;i++){let event=CH[Math.floor(Math.random()*CH.length)],rar=drawRarity(i===0?minIndex:0),key=event.id+'-'+rar.id;c[key]=(c[key]||0)+1;cards.push({event,rar,count:c[key]})}saveCollection(c);reward=null;packReward={source,cards,revealed:0};renderV29()}
function grantCard(source){grantCards(1,source)}
function rewardModal(){if(!packReward)return'';let all=packReward.revealed>=packReward.cards.length;return `<div class="rewardmodal"><div class="packbox"><p class="eyebrow">${esc(packReward.source)} 보상</p><h2 class="packtitle">${all?'카드팩 개봉 완료!':'카드팩을 열어보세요!'}</h2><p class="packhint">${all?'획득한 카드가 도감에 보관되었습니다.':'뒷면 카드를 한 장씩 눌러주세요.'}</p><div class="packcards">${packReward.cards.map((x,i)=>`<div class="packwrap ${i>=packReward.revealed?'covered':''}" onclick="revealPack(${i})">${collectCard(x.event,x.rar,x.count)}</div>`).join('')}</div>${all?'<button class="btn" onclick="packReward=null;renderV29()">확인</button>':'<button class="btn alt" onclick="revealAllPack()">모두 열기</button>'}</div></div>`}
function revealPack(i){if(!packReward||i!==packReward.revealed)return;packReward.revealed++;renderV29()}function revealAllPack(){if(packReward){packReward.revealed=packReward.cards.length;renderV29()}}
function localDateKey(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dailyKey(){return profile?`fr-v29-daily:${profile.schoolYear}-${profile.grade}-${profile.classNo}-${profile.number}`:'fr-v29-daily'}
function loadDailyState(){try{return JSON.parse(PreviewStore41.getItem(dailyKey()))||{lastDate:'',streak:0}}catch{return{lastDate:'',streak:0}}}
function isEligibleLocal(d){let s=loadV29Settings(),k=localDateKey(d),excluded=String(s.excludedDates||'').split(/[\s,]+/).filter(Boolean);return(s.weekdays||[1,2,3,4,5]).includes(d.getDay())&&!excluded.includes(k)}
function previousEligible(d){let x=new Date(d);do{x.setDate(x.getDate()-1)}while(!isEligibleLocal(x));return localDateKey(x)}
function maybeDailyPack(){if(dailyChecked||!profile)return;dailyChecked=true;let now=new Date();if(!isEligibleLocal(now))return;let k=localDateKey(now),d=loadDailyState();if(d.lastDate===k)return;d.streak=d.lastDate===previousEligible(now)?d.streak+1:1;if(d.streak>20)d.streak=1;d.lastDate=k;PreviewStore41.setItem(dailyKey(),JSON.stringify(d));let min=d.streak===20?4:d.streak===15?3:d.streak===10?2:d.streak===5?1:0;grantCards(Number(loadV29Settings().dailyCards)||3,`${d.streak}일 연속 출석 카드팩`,min)}
function matchingPage(){if(!matchGame)return `<section class="shell quiz center"><p class="eyebrow">🃏 짝맞추기</p><h2>게임 방식을 고르세요</h2><div class="modepick"><button onclick="startMatching('basic')"><strong>기본 카드 맞추기</strong><small>그림·제목·설명이 있는 같은 카드끼리 맞추기<br>완료 보상 카드 2장</small></button><button onclick="startMatching('advanced')"><strong>고급 카드 맞추기</strong><small>그림+제목과 그것에 대한 설명을 서로 맞추기<br>공식 기록 · 완료 보상 카드 4장</small></button></div><p class="best">고급형 최고 기록: <b>${bestFor('matching')?precise(bestFor('matching')):'기록 없음'}</b></p><button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;if(matchGame.status==='completed')return finishBonusPage('짝맞추기',matchGame,'matching',matchGame.official,`${matchGame.moves}번 뒤집기 · ${matchGame.official?'고급형 공식 기록입니다.':'기본형 연습 기록입니다.'}`);return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">짝맞추기 · ${matchGame.variant==='advanced'?'<span class="officialtag">고급 공식형</span>':'<span class="casualtag">기본형</span>'}</p><h2>같은 사건의 두 카드를 찾으세요</h2></div><div class="speedstats"><span class="speedstat">뒤집기<b>${matchGame.moves}회</b></span><span class="speedstat">현재 시간<b id="bonusclock">${precise(bonusNow(matchGame))}</b></span><button class="btn alt" onclick="matchGame=null;go('bonus')">중단</button></div></div><div class="matchgrid">${matchGame.cards.map((c,i)=>matchCard(c,i)).join('')}</div></section>`}
function startMatching(variant){let cards=[];Q.forEach(q=>{cards.push({pair:q.id,side:0,q});cards.push({pair:q.id,side:1,q})});matchGame={status:'active',variant,cards:shuffle(cards),open:[],done:[],moves:0,lock:false,startedAt:performance.now(),finishedMs:0,official:variant==='advanced'};renderV29();bonusClock()}
function matchCard(c,i){let open=matchGame.open.includes(i)||matchGame.done.includes(i),done=matchGame.done.includes(i),content='';if(open){if(matchGame.variant==='basic'||c.side===0)content=`<img src="${IMAGES[c.q.img-1]}"><span class="title">${c.q.title}</span>`;else content=`<span class="title" style="display:grid;place-items:center;height:100%;padding:10px;font-size:12px;line-height:1.45">${DESC[c.q.id]||c.q.prompt}</span>`}else content='<span class="matchback">?</span>';return `<button class="matchcard ${open?'open':''} ${done?'done':''}" onclick="flipMatch(${i})">${content}</button>`}
function finishMatching(){matchGame.status='completed';matchGame.finishedMs=performance.now()-matchGame.startedAt;if(matchGame.official)saveOfficial('짝맞추기','matching',matchGame.finishedMs,{attempts:matchGame.moves});grantCards(matchGame.variant==='advanced'?4:2,matchGame.variant==='advanced'?'고급 짝맞추기':'기본 짝맞추기')}
function checkBait(){let ok=bait.slots.every((id,i)=>id==='f'+(i+1));if(!ok){bait.checked=true;bait.errorChecks++;bait.official=false;renderV29();return}bait.status='completed';bait.finishedMs=performance.now()-bait.startedAt;let official=bait.decoyCount===8&&bait.errorChecks===0;bait.official=official;if(official)saveOfficial('미끼런','baitrun',bait.finishedMs);grantCards(bait.decoyCount===8?3:bait.decoyCount===6?2:1,`미끼런 ${bait.decoyCount}장`)}
function decoyPosition(id){let all=[...DECOYS.england,...DECOYS.america],i=all.findIndex(x=>x.id===id),col=i%4,row=Math.floor(i/4);return`${col*100/3}% ${row*100/3}%`}
function baitCard(id){let x=baitInfo(id);return `<button class="baitcard ${x.french?'':'decoy'} ${bait.selected===id?'sel':''}" onclick="baitSelect('${id}')" ondblclick="baitAuto(event,'${id}')" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${id}')">${x.french?`<img class="cardimg" src="${IMAGES[x.img-1]}">`:`<span class="decoyscene" style="background-image:url('${DECOY_SHEET}');background-position:${decoyPosition(id)}"></span>`}<span class="title">${x.title}</span></button>`}
function baitSlot(id,i){let x=id?baitInfo(id):null,cl=id?'filled':'';if(bait.checked&&id)cl+=id==='f'+(i+1)?' ok':' bad';return `<div class="slot ${cl}" onclick="baitPlace(${i})" ondblclick="baitRemove(event,${i})" ondragover="event.preventDefault()" ondrop="baitDrop(event,${i})"><span class="num">${i+1}</span>${id?`${x.french?`<img class="cardimg" src="${IMAGES[x.img-1]}">`:`<span class="decoyscene" style="background-image:url('${DECOY_SHEET}');background-position:${decoyPosition(id)}"></span>`}<span class="title">${x.title}</span>`:'+'}</div>`}
function collectionPage(){let c=loadCollection(),owned=Object.keys(c).filter(k=>c[k]>0).length;return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">프랑스 혁명 사건 카드</p><h2>📚 카드 도감 ${owned}/70</h2></div><button class="btn alt" onclick="go('bonus')">게임 선택</button></div><p>미획득 카드도 흐릿하게 미리 보이며, 획득하면 원래 색상과 등급 효과가 나타납니다.</p>${RARITIES.map(r=>`<section><h3>${r.name}</h3><div class="collectiongrid">${CH.map(e=>{let n=c[e.id+'-'+r.id]||0;return n?collectCard(e,r,n):`<article class="collectcard ${r.id} lockedcard"><span class="rarity">${r.name}</span><img src="${IMAGES[e.img-1]}"><h3>${e.title}</h3><p>미획득</p></article>`}).join('')}</div></section>`).join('')}</section>`}
function adminPage(){let s=loadV29Settings(),nav=[['attendance','출석 설정'],['gift','카드 지급'],['odds','카드 확률'],['students','학생 카드 현황'],['history','기록·보상 내역']];return `<section class="shell"><p class="eyebrow">교사용 로컬 시제품</p><h2>⚙️ 교사 관리</h2><div class="serverpending">현재는 화면과 이 기기의 설정만 작동합니다. 전체 학생 지급·서버 시간·학생 현황은 Code.gs 연결 후 활성화됩니다.</div><div class="adminnav">${nav.map(([k,n])=>`<button class="${adminView===k?'on':''}" onclick="adminView='${k}';renderV29()">${n}</button>`).join('')}</div>${adminView==='attendance'?attendanceAdmin(s):adminView==='gift'?giftAdmin():adminView==='odds'?oddsAdmin(s):`<div class="adminpanel"><h3>${adminView==='students'?'학생 카드 현황':'기록·보상 내역'}</h3><p>Code.gs와 구글 시트를 연결하면 학년·반·학생별 자료가 이곳에 표시됩니다.</p></div>`}</section>`}
function attendanceAdmin(s){return `<div class="adminpanel"><h3>출석 설정</h3><div class="adminform"><label>일일 지급 카드<input id="dailyCards" type="number" min="0" max="20" value="${s.dailyCards}"></label><label>출석 주기<input id="cycleDays" type="number" min="5" max="100" value="${s.cycleDays}"></label><label>인정 요일<select id="weekdayPreset"><option value="weekdays">월~금</option><option value="all">매일</option></select></label><label style="grid-column:1/-1">출석 제외일<textarea id="excludedDates" placeholder="2026-10-05, 2026-12-28">${s.excludedDates||''}</textarea></label></div><h4>연속 출석 보장</h4><p>5일 레어 이상 · 10일 유니크 이상 · 15일 전설 이상 · 20일 신화</p><button class="btn" onclick="saveAttendanceAdmin()">이 기기에 설정 저장</button></div>`}
function saveAttendanceAdmin(){let s=loadV29Settings();s.dailyCards=Math.max(0,Number(dailyCards.value)||3);s.cycleDays=Math.max(5,Number(cycleDays.value)||20);s.weekdays=weekdayPreset.value==='all'?[0,1,2,3,4,5,6]:[1,2,3,4,5];s.excludedDates=excludedDates.value.trim();saveV29Settings(s);alert('출석 화면 설정을 저장했습니다. 서버 연결 후 전체 학생에게 적용됩니다.')}
function giftAdmin(){return `<div class="adminpanel"><h3>카드 지급</h3><div class="adminform"><label>지급 대상<select id="giftTarget"><option>전체 학생</option><option>학년 전체</option><option>학년·반 전체</option><option>특정 학생</option><option>현재 시험 학생</option></select></label><label>지급 방식<select id="giftType"><option value="random">무작위 카드</option><option value="specific">특정 카드</option></select></label><label>수량<input id="giftCount" type="number" min="1" max="50" value="1"></label><label>사건<select id="giftEvent">${CH.map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}</select></label><label>등급<select id="giftRarity">${RARITIES.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label></div><div class="bonus-actions"><button class="btn" onclick="testGiftCurrent()">현재 학생에게 시험 지급</button><button class="btn alt" onclick="alert('전체 학생 지급은 Code.gs 연결 후 사용할 수 있습니다.')">선택 대상에게 지급</button></div></div>`}
function testGiftCurrent(){let n=Math.max(1,Number(giftCount.value)||1);if(giftType.value==='random')return grantCards(n,'교사 시험 선물');let e=CH.find(x=>x.id===Number(giftEvent.value)),r=rarityById(giftRarity.value),c=loadCollection(),cards=[];for(let i=0;i<n;i++){let k=e.id+'-'+r.id;c[k]=(c[k]||0)+1;cards.push({event:e,rar:r,count:c[k]})}saveCollection(c);packReward={source:'교사 지정 선물',cards,revealed:0};renderV29()}
function oddsAdmin(s){return `<div class="adminpanel"><h3>카드 등급 확률</h3>${RARITIES.map(r=>`<label class="oddsrow"><span>${r.name}</span><input id="odd_${r.id}" type="number" min="0" max="100" step="0.1" value="${s.odds[r.id]}"></label>`).join('')}<p>합계는 반드시 100%여야 합니다.</p><button class="btn" onclick="saveOddsAdmin()">확률 저장</button></div>`}
function saveOddsAdmin(){let vals={},sum=0;RARITIES.forEach(r=>{vals[r.id]=Math.max(0,Number(document.querySelector('#odd_'+r.id).value)||0);sum+=vals[r.id]});if(Math.abs(sum-100)>.001)return alert('확률 합계를 100%로 맞춰주세요. 현재 '+sum+'%입니다.');let s=loadV29Settings();s.odds=vals;saveV29Settings(s);alert('이 기기의 카드 확률을 저장했습니다.')}
function resultsV29(){let d=loadBonusData(),b=d.best||{},core=['beginner','intermediate','advanced'].map(m=>{let s=P[m],quizMode=m!=='advanced',status=s.status==='completed'?'완료':s.status==='active'?'진행 중':'시작 전';return `<article class="result ${s.status==='completed'?'done':''}"><p class="eyebrow">${names[m]}</p><h3>${status}</h3><p>${s.status==='not_started'?'아직 시작하지 않았습니다.':'풀이시간 '+time(s.elapsed)}</p>${quizMode?`<p>합격 <b>${passedCount(s)}/${quizItems(m).length}</b></p>`:`<p>정답 확인 <b>${s.history.length}회</b></p>`}</article>`}).join(''),keys=[['speedrun','스피드런'],['baitrun','미끼런'],['matching','짝맞추기 고급']],ready=keys.every(([k])=>b[k]),sum=ready?keys.reduce((a,[k])=>a+Number(b[k]),0):0;return `<section class="shell"><p class="eyebrow">${profile.schoolYear}학년도 · ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</p><h2>학습 및 공식 기록</h2><div class="results">${core}</div><h2 style="margin-top:28px">보너스 게임 최고기록</h2><table class="summarytable"><tbody>${keys.map(([k,n])=>`<tr><th>${n}</th><td>${b[k]?precise(b[k]):'기록 없음'}</td></tr>`).join('')}<tr><th>종합 기록</th><td>${ready?precise(sum):'세 게임을 모두 완료하면 등록'}</td></tr></tbody></table><div class="bonus-actions"><button class="btn" onclick="go('bonus')">보너스 게임</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div><div class="teacher"><h3>🔒 교사용 메뉴</h3><p>마스터 코드를 입력하면 전체 해금, 전광판, 교사 관리 화면을 사용할 수 있습니다.</p><div class="bonus-actions">${teacherUnlocked?`<button class="btn" onclick="window.open(location.pathname+'?ranking=class','_blank')">🏆 전광판 열기</button><button class="btn alt" onclick="go('admin')">교사 관리</button><button class="btn alt" onclick="teacherOff()">교사용 기능 종료</button>`:`<button class="btn alt" onclick="teacherMenu()">마스터 코드 입력</button>`}</div></div></section>`}
function renderV29(){if(RANKING)return rankingScreenV26();if(!profile)return profileScreen();let open=coreComplete()||teacherUnlocked;if(['bonus','collection','practice','speedrun','baitrun','matching'].includes(view)&&!open)view='results';if(['beginner','intermediate','advanced'].includes(view)&&!unlockedV28(view))view='beginner';let body=view==='beginner'||view==='intermediate'?quiz(view):view==='advanced'?order(view):view==='bonus'?bonusHub():view==='collection'?collectionPage():view==='practice'?practicePageV28():view==='speedrun'?speedPageV28():view==='baitrun'?baitPage():view==='matching'?matchingPage():view==='admin'?adminPage():resultsV29();app.innerHTML=shell(body);setTimeout(()=>document.querySelector('#ans')?.focus(),0);showSync();if(!dailyChecked&&profile)setTimeout(maybeDailyPack,0)}
/* ===== v3.0 card system ===== */
const DEFAULT_V30_SETTINGS={odds:{normal:60,rare:25,unique:10,legend:4,myth:1},weekdays:[1,2,3,4,5],dailyCards:3,cycleDays:20,excludedDates:'',pity:{uniqueAfter:20,legendAfter:60,mythAfter:150,newAfter:25},milestone:{rareEvery:10,legendEvery:50,mythEvery:200}};
const CARD_YEARS={1:'1789',2:'1789',3:'1789',4:'1789',5:'1789',6:'1789',7:'1791',8:'1791',9:'1792',10:'1793',11:'1793–1794',12:'1794',13:'1795',14:'1799'};
const CARD_TEXT={1:'재정난을 해결하려고 세 신분의 대표를 불러 모은 프랑스 혁명의 출발점.',2:'제3신분 대표들이 자신들을 국민의 대표라고 선언하며 결성한 의회.',3:'헌법을 제정할 때까지 해산하지 않겠다고 국민의회가 맹세한 사건.',4:'파리 시민들이 절대왕정의 상징이던 감옥을 습격해 혁명의 시작을 알린 사건.',5:'국민의회가 신분제와 봉건적 의무를 폐지하여 구체제의 기반을 무너뜨린 결정.',6:'자유·평등·국민주권과 인간의 기본권을 선포한 프랑스 혁명의 핵심 문서.',7:'루이 16세가 국외로 탈출하려다 바렌에서 붙잡혀 왕에 대한 신뢰가 무너진 사건.',8:'1791년 헌법에 따라 왕의 권한을 제한하고 의회가 통치에 참여한 체제.',9:'국민공회가 왕정을 폐지하고 프랑스에 공화정을 수립한 사건.',10:'국민공회의 재판을 받은 루이 16세가 단두대에서 처형된 사건.',11:'로베스피에르와 자코뱅파가 반혁명 세력을 강하게 처벌하며 펼친 정치.',12:'테르미도르의 반동으로 로베스피에르가 체포되고 처형되어 공포 정치가 끝난 사건.',13:'공포 정치 이후 다섯 명의 총재가 행정부를 맡아 통치한 정부.',14:'나폴레옹이 쿠데타로 총재정부를 무너뜨리고 권력을 장악한 사건.'};
let packDrag=null,packRevealTimer=null;
function loadV29Settings(){try{let x=JSON.parse(PreviewStore41.getItem(settingsV29Key)||'{}');return{...DEFAULT_V30_SETTINGS,...x,odds:{...DEFAULT_V30_SETTINGS.odds,...(x.odds||{})},pity:{...DEFAULT_V30_SETTINGS.pity,...(x.pity||{})},milestone:{...DEFAULT_V30_SETTINGS.milestone,...(x.milestone||{})}}}catch{return JSON.parse(JSON.stringify(DEFAULT_V30_SETTINGS))}}
function pityKeyV30(){return profile?`fr-v30-pity:${profile.schoolYear}-${profile.grade}-${profile.classNo}-${profile.number}`:'fr-v30-pity'}
function loadPityV30(){try{return{total:0,sinceUnique:0,sinceLegend:0,sinceMyth:0,sinceNew:0,...JSON.parse(PreviewStore41.getItem(pityKeyV30())||'{}')}}catch{return{total:0,sinceUnique:0,sinceLegend:0,sinceMyth:0,sinceNew:0}}}
function savePityV30(x){PreviewStore41.setItem(pityKeyV30(),JSON.stringify(x))}
function rarityIndexV30(r){return Math.max(0,RARITIES.findIndex(x=>x.id===r.id))}
function drawCardV30(collection,stats,sourceMin=0){let s=loadV29Settings(),drawNo=stats.total+1,min=sourceMin,p=s.pity,m=s.milestone;if(p.uniqueAfter>0&&stats.sinceUnique+1>=p.uniqueAfter)min=Math.max(min,2);if(p.legendAfter>0&&stats.sinceLegend+1>=p.legendAfter)min=Math.max(min,3);if(p.mythAfter>0&&stats.sinceMyth+1>=p.mythAfter)min=4;if(m.rareEvery>0&&drawNo%m.rareEvery===0)min=Math.max(min,1);if(m.legendEvery>0&&drawNo%m.legendEvery===0)min=Math.max(min,3);if(m.mythEvery>0&&drawNo%m.mythEvery===0)min=4;let rar=drawRarity(min),idx=rarityIndexV30(rar),event=null;if(p.newAfter>0&&stats.sinceNew+1>=p.newAfter){let missing=CH.filter(e=>!(collection[e.id+'-'+rar.id]>0));if(missing.length)event=missing[Math.floor(Math.random()*missing.length)]}if(!event)event=CH[Math.floor(Math.random()*CH.length)];let key=event.id+'-'+rar.id,isNew=!(collection[key]>0);collection[key]=(collection[key]||0)+1;stats.total=drawNo;stats.sinceUnique=idx>=2?0:stats.sinceUnique+1;stats.sinceLegend=idx>=3?0:stats.sinceLegend+1;stats.sinceMyth=idx>=4?0:stats.sinceMyth+1;stats.sinceNew=isNew?0:stats.sinceNew+1;return{event,rar,count:collection[key],isNew}}
function grantCards(count,source,minIndex=0){let c=loadCollection(),stats=loadPityV30(),cards=[];for(let i=0;i<count;i++)cards.push(drawCardV30(c,stats,i===0?minIndex:0));saveCollection(c);savePityV30(stats);reward=null;packReward={source,cards,revealed:0,lastReveal:-1};renderV30()}
function collectCard(event,rar,count,locked=false){let q=CH.find(x=>x.id===event.id)||event,desc=CARD_TEXT[q.id]||'',year=CARD_YEARS[q.id]||'1789';return `<article class="collectcard premium ${rar.id} ${locked?'lockedcard':''}"><div class="cardname">${locked?'???':q.title}</div><div class="cardart"><img src="${IMAGES[q.img-1]}" alt=""></div><div class="cardyear">${locked?'????':year}</div><div class="carddesc">${locked?'아직 발견하지 못한 프랑스 혁명 사건 카드입니다.':desc}</div><div class="cardfoot"><span class="cardrarity">${rar.name}</span><span>${locked?'미획득':'보유 '+(count||0)+'장'}</span></div></article>`}
function collectionPage(){let c=loadCollection(),owned=Object.keys(c).filter(k=>c[k]>0).length,stats=loadPityV30();return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">프랑스 혁명 사건 카드</p><h2>📚 카드 도감 ${owned}/70</h2></div><span class="pill">무작위 추첨 ${stats.total}장</span></div><p>카드 도감은 처음부터 이용할 수 있습니다. 같은 사건도 노말·레어·유니크·전설·신화 등급으로 수집할 수 있습니다.</p>${RARITIES.map(r=>`<section><h3>${r.name}</h3><div class="collectiongrid">${CH.map(e=>{let n=c[e.id+'-'+r.id]||0;return collectCard(e,r,n,!n)}).join('')}</div></section>`).join('')}</section>`}
function rewardModal(){if(!packReward)return'';let all=packReward.revealed>=packReward.cards.length,current=packReward.revealed;return `<div class="rewardmodal"><div class="packbox"><p class="eyebrow">${esc(packReward.source)} 보상</p><h2 class="packtitle">${all?'카드팩 개봉 완료!':'봉인을 아래로 끌어내리세요'}</h2><p class="packhint">${all?'획득한 카드가 도감에 보관되었습니다.':'짧게 누르면 자동 개봉되고, 아래로 밀면 카드의 끄트머리부터 확인할 수 있습니다.'}</p><div class="packcards">${packReward.cards.map((x,i)=>{let shown=i<current,recent=i===packReward.lastReveal,idx=rarityIndexV30(x.rar),state=shown?'unveiled':i===current?'covered':'covered queued';return `<div class="packwrap ${state} ${recent?'recent rarity-'+x.rar.id:''}">${collectCard(x.event,x.rar,x.count)}${!shown?`<div class="packcover" data-pack="${i}" style="--peel:0px" onpointerdown="packDragStart(event,${i})" onpointermove="packDragMove(event)" onpointerup="packDragEnd(event)" onpointercancel="packDragCancel(event)"></div>`:''}${shown&&recent&&idx>=2?`<div class="rarity-banner ${x.rar.id}">${x.rar.name} 등장!</div>`:''}</div>`}).join('')}</div>${all?'<button class="btn" onclick="packReward=null;renderV30()">도감에 보관</button>':'<button class="btn alt" onclick="revealAllPack()">연속 자동 개봉</button>'}</div></div>`}
function packDragStart(e,i){if(!packReward||i!==packReward.revealed)return;e.preventDefault();packDrag={i,startY:e.clientY,lastY:e.clientY,moved:false,el:e.currentTarget};e.currentTarget.setPointerCapture?.(e.pointerId)}
function packDragMove(e){if(!packDrag)return;let d=Math.max(0,Math.min(210,e.clientY-packDrag.startY));packDrag.lastY=e.clientY;if(d>8)packDrag.moved=true;packDrag.el.style.setProperty('--peel',d+'px');packDrag.el.style.opacity=String(1-d/260)}
function packDragEnd(e){if(!packDrag)return;let d=Math.max(0,packDrag.lastY-packDrag.startY),tap=!packDrag.moved,i=packDrag.i,el=packDrag.el;packDrag=null;if(d>=105){el.style.setProperty('--peel','260px');el.style.opacity='0';setTimeout(()=>revealPack(i),230)}else if(tap)cinematicReveal(i,el);else{el.style.setProperty('--peel','0px');el.style.opacity='1'}}
function packDragCancel(){if(packDrag){packDrag.el.style.setProperty('--peel','0px');packDrag.el.style.opacity='1';packDrag=null}}
function cinematicReveal(i,el){if(!packReward||i!==packReward.revealed)return;el.style.transition='transform .65s cubic-bezier(.2,.8,.2,1),opacity .5s';el.style.setProperty('--peel','260px');el.style.opacity='0';setTimeout(()=>revealPack(i),520)}
function revealPack(i){if(!packReward||i!==packReward.revealed)return;packReward.revealed++;packReward.lastReveal=i;renderV30()}
function revealAllPack(){if(!packReward||packReward.revealed>=packReward.cards.length)return;let i=packReward.revealed,el=document.querySelector(`.packcover[data-pack="${i}"]`);if(el)cinematicReveal(i,el);packRevealTimer=setTimeout(()=>revealAllPack(),1150)}
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v3.0</span></h1><p>학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function shell(body){let open=coreComplete()||teacherUnlocked,tabs=['beginner','intermediate','advanced','bonus','collection','results',...(teacherUnlocked?['admin']:[])];return `<header class="header"><div class="headerin"><div><p class="eyebrow">1789 — 1799</p><h1>프랑스 혁명 학습 게임 <span class="version">v3.0</span></h1></div><div class="student"><span>👤 ${profile.grade}학년 ${profile.classNo}반 ${profile.number}번 ${esc(profile.name)}</span><button class="btn alt" onclick="profileScreen()">학생 정보 변경</button></div></div></header><main class="wrap"><nav class="tabs">${tabs.map(x=>{let lock=['intermediate','advanced'].includes(x)&&!unlockedV28(x)||(x==='bonus'&&!open),label=x==='results'?'결과':x==='bonus'?'보너스 게임':x==='collection'?'카드 도감':x==='admin'?'교사 관리':names[x];return `<button class="tab ${view===x?'active':''} ${lock?'locked':''}" onclick="go('${x}')">${label}${P[x]?.status==='completed'?' ✓':lock?' 🔒':''}</button>`}).join('')}</nav>${body}</main><div class="sync ${getOutbox().length?'wait':''}" onclick="manualSync()">${syncLabel()}</div>${rewardModal()}`}
function go(v){let open=coreComplete()||teacherUnlocked;if(v==='bonus'&&!open){alert('보너스 게임은 초급·중급·고급을 모두 완료하면 해금됩니다. 카드 도감은 지금부터 이용할 수 있습니다.');return}if(v==='admin'&&!teacherUnlocked)return teacherMenu();if(['beginner','intermediate','advanced'].includes(v)&&!unlockedV28(v)){alert('앞 급수를 먼저 완료해야 합니다.');return}view=v;renderV30();clock();bonusClock()}
function completionButton(m){let next={beginner:'intermediate',intermediate:'advanced'}[m];if(next)return `<button class="btn" onclick="go('${next}')">다음 ${names[next]}으로</button>`;if(m==='advanced')return `<button class="btn" onclick="go('bonus')">보너스 게임으로</button>`;return''}
const finishQuizV29=finishQuiz;finishQuiz=function(m,s){finishQuizV29(m,s);grantCards(m==='beginner'?1:2,`${names[m]} 최초 완료`)};
const checkV29=check;check=function(m){let before=P[m]?.status;checkV29(m);if(m==='advanced'&&before!=='completed'&&P[m]?.status==='completed')grantCards(3,'고급 최초 완료')};
function giftAdmin(){return `<div class="adminpanel"><h3>카드 지급</h3><div class="adminform"><label>지급 대상<select id="giftTarget"><option>전체 학생</option><option>학년 전체</option><option>학년·반 전체</option><option>특정 학생</option><option>현재 시험 학생</option></select></label><label>지급 방식<select id="giftType" onchange="syncGiftControls()"><option value="random">무작위 카드</option><option value="specific">특정 카드</option></select></label><label>수량<input id="giftCount" type="number" min="1" max="50" value="1"></label><label id="giftEventLabel" class="gift-dependent disabled">사건<select id="giftEvent" disabled>${CH.map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}</select></label><label id="giftRarityLabel" class="gift-dependent disabled">등급<select id="giftRarity" disabled>${RARITIES.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label></div><p id="giftHelp">무작위 지급에서는 사건과 등급도 설정된 확률에 따라 무작위로 정해집니다.</p><div class="bonus-actions"><button class="btn" onclick="testGiftCurrent()">현재 학생에게 시험 지급</button><button class="btn alt" onclick="alert('전체 학생 지급은 Code.gs 연결 후 사용할 수 있습니다.')">선택 대상에게 지급</button></div></div>`}
function syncGiftControls(){let specific=document.querySelector('#giftType')?.value==='specific';['giftEvent','giftRarity'].forEach(id=>{let x=document.querySelector('#'+id);if(x)x.disabled=!specific});['giftEventLabel','giftRarityLabel'].forEach(id=>document.querySelector('#'+id)?.classList.toggle('disabled',!specific));let h=document.querySelector('#giftHelp');if(h)h.textContent=specific?'선택한 사건과 등급의 카드를 정확히 지급합니다.':'무작위 지급에서는 사건과 등급도 설정된 확률에 따라 무작위로 정해집니다.'}
function pityAdmin(s){let p=s.pity,m=s.milestone,st=loadPityV30();return `<div class="adminpanel"><h3>천장·기념 보상 설정</h3><p>0으로 설정하면 해당 규칙을 사용하지 않습니다. 중복 카드 획득 여부와 등급 천장은 서로 독립적으로 계산됩니다.</p><div class="pitystatus"><span>총 획득<b>${st.total}장</b></span><span>유니크+ 미등장<b>${st.sinceUnique}장</b></span><span>전설+ 미등장<b>${st.sinceLegend}장</b></span><span>신화 미등장<b>${st.sinceMyth}장</b></span></div><div class="pitygrid"><div class="pitycard"><h4>연속 미등장 천장</h4><label>유니크 이상 확정<input id="pityUnique" type="number" min="0" value="${p.uniqueAfter}"></label><label>전설 이상 확정<input id="pityLegend" type="number" min="0" value="${p.legendAfter}"></label><label>신화 확정<input id="pityMyth" type="number" min="0" value="${p.mythAfter}"></label><label>새 카드 보호<input id="pityNew" type="number" min="0" value="${p.newAfter}"></label></div><div class="pitycard"><h4>총 획득 장수 분기점</h4><label>매 O장 레어 이상<input id="mileRare" type="number" min="0" value="${m.rareEvery}"></label><label>매 O장 전설 이상<input id="mileLegend" type="number" min="0" value="${m.legendEvery}"></label><label>매 O장 신화 확정<input id="mileMyth" type="number" min="0" value="${m.mythEvery}"></label></div></div><div class="rules"><b>추천 기본값</b><br>10장마다 레어 이상 · 20장 연속 유니크 미등장 시 유니크 이상 · 50장마다 전설 이상 · 60장 연속 전설 미등장 시 전설 이상 · 150장 연속 신화 미등장 시 신화 · 200장마다 신화</div><button class="btn" onclick="savePityAdmin()">천장 설정 저장</button></div>`}
function savePityAdmin(){let s=loadV29Settings(),num=id=>Math.max(0,Number(document.querySelector('#'+id).value)||0);s.pity={uniqueAfter:num('pityUnique'),legendAfter:num('pityLegend'),mythAfter:num('pityMyth'),newAfter:num('pityNew')};s.milestone={rareEvery:num('mileRare'),legendEvery:num('mileLegend'),mythEvery:num('mileMyth')};saveV29Settings(s);alert('이 기기의 천장과 기념 보상 설정을 저장했습니다.')}
function adminPage(){let s=loadV29Settings(),nav=[['attendance','출석 설정'],['gift','카드 지급'],['odds','카드 확률'],['pity','천장 설정'],['students','학생 카드 현황'],['history','기록·보상 내역']];return `<section class="shell"><p class="eyebrow">교사용 로컬 시제품</p><h2>⚙️ 교사 관리</h2><div class="serverpending">현재는 화면과 이 기기의 설정만 작동합니다. 전체 학생 지급·서버 시간·학생 현황은 Code.gs 연결 후 활성화됩니다.</div><div class="adminnav">${nav.map(([k,n])=>`<button class="${adminView===k?'on':''}" onclick="adminView='${k}';renderV30()">${n}</button>`).join('')}</div>${adminView==='attendance'?attendanceAdmin(s):adminView==='gift'?giftAdmin():adminView==='odds'?oddsAdmin(s):adminView==='pity'?pityAdmin(s):`<div class="adminpanel"><h3>${adminView==='students'?'학생 카드 현황':'기록·보상 내역'}</h3><p>Code.gs와 구글 시트를 연결하면 학년·반·학생별 자료가 이곳에 표시됩니다.</p></div>`}</section>`}
function bonusHub(){let best=loadBonusData().best||{},daily=loadDailyState();return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>공식 규칙으로 완주하면 개인 최고기록에 반영되고 카드팩을 받습니다.</p><div class="dailybox"><h3>🎁 오늘의 카드팩</h3><p>${daily.lastDate===localDateKey(new Date())?'오늘의 카드 3장을 받았습니다.':'하루 한 번 카드 3장을 받을 수 있습니다.'}</p><div class="streakline"><span class="${daily.streak>=5?'done':''}">5일 레어+</span><span class="${daily.streak>=10?'done':''}">10일 유니크+</span><span class="${daily.streak>=15?'done':''}">15일 전설+</span><span class="${daily.streak>=20?'done':''}">20일 신화</span></div><small>현재 v3.0은 기기 날짜로 시험 작동합니다. Code.gs 연결 후 서버 시간으로 교체됩니다.</small></div><div class="bonusmenu"><button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>무오답 순서 배열 · 완료 카드 1장<br>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button><button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>영국·미국 사건을 피해 배열<br>미끼 4/6/8장 → 카드 1/2/3장</small></button><button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>기본 카드 2장 · 고급 카드 4장<br>고급형만 공식 기록</small></button></div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}
function rankingScreenV30(){rankingScreenV26();app.innerHTML=app.innerHTML.replace('프랑스 혁명 학습 게임 · v2.9','프랑스 혁명 학습 게임 · v3.0')}
function renderV30(){if(RANKING)return rankingScreenV30();if(!profile)return profileScreen();let open=coreComplete()||teacherUnlocked;if(['bonus','practice','speedrun','baitrun','matching'].includes(view)&&!open)view='results';if(['beginner','intermediate','advanced'].includes(view)&&!unlockedV28(view))view='beginner';let body=view==='beginner'||view==='intermediate'?quiz(view):view==='advanced'?order(view):view==='bonus'?bonusHub():view==='collection'?collectionPage():view==='practice'?practicePageV28():view==='speedrun'?speedPageV28():view==='baitrun'?baitPage():view==='matching'?matchingPage():view==='admin'?adminPage():resultsV29();app.innerHTML=shell(body);setTimeout(()=>{document.querySelector('#ans')?.focus();if(view==='admin'&&adminView==='gift')syncGiftControls()},0);showSync();if(!dailyChecked&&profile)setTimeout(maybeDailyPack,0)}
/* ===== v3.1 interaction refinements ===== */
let cardInspect=null;
function collectCard(event,rar,count,locked=false,interactive=true){let q=CH.find(x=>x.id===event.id)||event,desc=CARD_TEXT[q.id]||'',year=CARD_YEARS[q.id]||'1789',open=!locked&&interactive?`onclick="inspectCard(event,${q.id},'${rar.id}',${count||0})" role="button" tabindex="0" onkeydown="if(event.key==='Enter')inspectCard(event,${q.id},'${rar.id}',${count||0})"`:'';return `<article class="collectcard premium ${rar.id} ${locked?'lockedcard':''}" ${open}><div class="cardname">${locked?'???':q.title}</div><div class="cardart"><img src="${IMAGES[q.img-1]}" alt="${locked?'미획득 카드':q.title}"></div><div class="cardyear">${locked?'????':year}</div><div class="carddesc">${locked?'아직 발견하지 못한 프랑스 혁명 사건 카드입니다.':desc}</div><div class="cardfoot"><span class="cardrarity">${rar.name}</span><span>${locked?'미획득':'보유 '+(count||0)+'장'}</span></div></article>`}
function inspectCard(e,eventId,rarityId,count){e?.stopPropagation?.();cardInspect={event:CH.find(x=>x.id===eventId),rar:rarityById(rarityId),count};renderV31()}
function cardInspectModal(){if(!cardInspect)return'';return `<div class="cardinspect" onclick="cardInspect=null;renderV31()"><div class="inspectpanel" onclick="event.stopPropagation()"><button class="inspectclose" onclick="cardInspect=null;renderV31()" aria-label="닫기">×</button>${collectCard(cardInspect.event,cardInspect.rar,cardInspect.count,false,false)}<p class="inspecttip">카드 바깥을 누르면 닫힙니다.</p></div></div>`}
const shellV30=shell;shell=function(body){return shellV30(body).replace('v3.0','v3.1')+cardInspectModal()};
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v3.1</span></h1><p>학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function rewardModal(){if(!packReward)return'';let all=packReward.revealed>=packReward.cards.length,current=packReward.revealed;return `<div class="rewardmodal"><div class="packbox"><h2 class="packtitle">${all?'카드팩 개봉 완료!':'카드팩을 개봉하세요'}</h2><p class="packhint">${all?'획득한 카드는 카드 도감에서 크게 볼 수 있습니다.':'짧게 누르면 개봉되고, 아래로 드래그하면 위쪽부터 천천히 확인할 수 있습니다.'}</p><div class="packcards">${packReward.cards.map((x,i)=>{let shown=i<current,recent=i===packReward.lastReveal,idx=rarityIndexV30(x.rar),omen=!shown&&i===current&&idx>=2?' omen-'+x.rar.id:'',state=shown?'unveiled':i===current?'covered':'covered queued';return `<div class="packwrap ${state}${omen} ${recent?'recent rarity-'+x.rar.id:''}">${collectCard(x.event,x.rar,x.count,false,shown)}${!shown?`<div class="packcover" data-pack="${i}" style="--peel:0px" onpointerdown="packDragStart(event,${i})" onpointermove="packDragMove(event)" onpointerup="packDragEnd(event)" onpointercancel="packDragCancel(event)"><span class="packomen"></span></div>`:''}${shown&&recent&&idx>=2?`<div class="rarity-banner ${x.rar.id}">${x.rar.name} 등장!</div>`:''}</div>`}).join('')}</div>${all?'<button class="btn" onclick="packReward=null;renderV31()">도감에 보관</button>':'<button class="btn alt" onclick="revealAllPack()">연속 자동 개봉</button>'}</div></div>`}
function bonusHub(){let best=loadBonusData().best||{},daily=loadDailyState(),streak=Number(daily.streak)||0;return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>게임을 완료하면 개인 최고기록에 도전하고 사건 카드도 받을 수 있습니다.</p><div class="dailybox"><h3>🎁 오늘의 카드팩</h3><p>${daily.lastDate===localDateKey(new Date())?'오늘의 접속 보상 카드 3장을 받았습니다.':'오늘 접속하면 카드 3장을 받을 수 있습니다.'}</p><div class="streaknow">🔥 현재 ${streak}일 연속 접속 중입니다.</div><div class="streakline detail"><span class="${streak>=5?'done':''}"><b>5일 연속 접속</b><br>레어 이상 1장 보장</span><span class="${streak>=10?'done':''}"><b>10일 연속 접속</b><br>유니크 이상 1장 보장</span><span class="${streak>=15?'done':''}"><b>15일 연속 접속</b><br>전설 이상 1장 보장</span><span class="${streak>=20?'done':''}"><b>20일 연속 접속</b><br>신화 1장 보장</span></div><small>현재 v3.1은 기기 날짜로 시험 작동합니다. Code.gs 연결 후 서버 시간으로 교체됩니다.</small></div><div class="bonusmenu"><button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>무오답 순서 배열<span class="rewardline">완료 시 카드 1장 지급</span>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button><button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>영국·미국 사건을 피해 배열<span class="rewardline">미끼 4/6/8장 완료 시 카드 1/2/3장 지급</span></small></button><button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>기본형·고급형 카드 맞추기<span class="rewardline">기본 완료 2장 · 고급 완료 4장 지급</span>고급형만 공식 기록</small></button></div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}
function giftAdmin(){return `<div class="adminpanel"><h3>카드 지급</h3><div class="adminform"><label>지급 대상<select id="giftTarget"><option>전체 학생</option><option>학년 전체</option><option>학년·반 전체</option><option>특정 학생</option><option>현재 시험 학생</option></select></label><label>수량<input id="giftCount" type="number" min="1" max="50" value="1"></label><label>사건<select id="giftEvent"><option value="random">무작위 사건</option>${CH.map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}</select></label><label>등급<select id="giftRarity"><option value="random">무작위 등급</option>${RARITIES.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label></div><div class="giftcombo"><b>자유 조합 지급</b><br>예: 무작위 사건+신화, 삼부회 소집+무작위 등급, 또는 사건과 등급 모두 지정할 수 있습니다.</div><div class="bonus-actions"><button class="btn" onclick="testGiftCurrent()">현재 학생에게 시험 지급</button><button class="btn alt" onclick="alert('전체 학생 지급은 Code.gs 연결 후 사용할 수 있습니다.')">선택 대상에게 지급</button></div></div>`}
function syncGiftControls(){}
function testGiftCurrent(){let n=Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),ev=document.querySelector('#giftEvent')?.value||'random',rv=document.querySelector('#giftRarity')?.value||'random',c=loadCollection(),cards=[];for(let i=0;i<n;i++){let e=ev==='random'?CH[Math.floor(Math.random()*CH.length)]:CH.find(x=>x.id===Number(ev)),r=rv==='random'?drawRarity(0):rarityById(rv),k=e.id+'-'+r.id;c[k]=(c[k]||0)+1;cards.push({event:e,rar:r,count:c[k]})}saveCollection(c);packReward={source:'',cards,revealed:0,lastReveal:-1};renderV31()}
function renderV31(){renderV30();if(app?.innerHTML)app.innerHTML=app.innerHTML.replaceAll('v3.0','v3.1')}
/* ===== v3.2 attendance, targeting, card back and drag fixes ===== */
const DEFAULT_ATTENDANCE_V32={rareDay:5,uniqueDay:10,legendDay:15,mythDay:20};
const loadSettingsV31=loadV29Settings;loadV29Settings=function(){let s=loadSettingsV31();return{...s,attendance:{...DEFAULT_ATTENDANCE_V32,...(s.attendance||{})}}};
function inspectCard(e,eventId,rarityId,count){e?.stopPropagation?.();cardInspect={event:CH.find(x=>x.id===eventId),rar:rarityById(rarityId),count,flipped:false};renderV32()}
function flipInspect(e){e?.stopPropagation?.();if(!cardInspect)return;cardInspect.flipped=!cardInspect.flipped;renderV32()}
function cardInspectModal(){if(!cardInspect)return'';let q=cardInspect.event,i=CH.findIndex(x=>x.id===q.id),prev=CH[i-1],next=CH[i+1],rar=cardInspect.rar;return `<div class="cardinspect" onclick="cardInspect=null;renderV32()"><div class="inspectpanel" onclick="event.stopPropagation()"><button class="inspectclose" onclick="cardInspect=null;renderV32()" aria-label="닫기">×</button><div class="flipscene"><div class="flipinner ${cardInspect.flipped?'flipped':''}"><div class="flipface" onclick="flipInspect(event)">${collectCard(q,rar,cardInspect.count,false,false)}</div><div class="flipface flipback ${rar.id}" style="--metal:${rar.id==='legend'?'#ffd45b':rar.id==='unique'?'#bf7aff':rar.id==='rare'?'#87b9f4':rar.id==='myth'?'#9ffeff':'#9a7b52'}" onclick="flipInspect(event)"><div class="backcontent"><div class="backbadge"><span>${i+1}</span></div><p class="eyebrow">프랑스 혁명의 흐름 · ${i+1}/14</p><h2>${q.title}</h2><div class="backmeaning">${CARD_TEXT[q.id]}</div><div class="flowrow"><div class="flowitem"><small>이전 사건</small><br>${prev?prev.title:'혁명의 배경'}</div><b>→</b><div class="flowitem"><small>다음 사건</small><br>${next?next.title:'나폴레옹 시대'}</div></div><p class="backhint">카드를 누르면 앞면으로 돌아갑니다.</p></div></div></div></div><p class="inspecttip">카드를 누르면 앞·뒷면이 전환됩니다. 바깥을 누르면 닫힙니다.</p></div></div>`}
function packDragStart(e,i){if(!packReward||i!==packReward.revealed)return;e.preventDefault();let el=e.currentTarget;packDrag={i,startY:e.clientY,lastY:e.clientY,moved:false,el};el.classList.add('dragging');el.setPointerCapture?.(e.pointerId)}
function packDragMove(e){if(!packDrag)return;e.preventDefault();let d=Math.max(0,Math.min(280,e.clientY-packDrag.startY));packDrag.lastY=e.clientY;if(d>6)packDrag.moved=true;packDrag.el.style.setProperty('--peel',d+'px');packDrag.el.style.opacity=String(Math.max(.08,1-d/330))}
function packDragEnd(e){if(!packDrag)return;let d=Math.max(0,packDrag.lastY-packDrag.startY),tap=!packDrag.moved,i=packDrag.i,el=packDrag.el;el.classList.remove('dragging');packDrag=null;if(d>=110){el.style.setProperty('--peel','340px');el.style.opacity='0';setTimeout(()=>revealPack(i),230)}else if(tap)cinematicReveal(i,el);else{el.style.setProperty('--peel','0px');el.style.opacity='1'}}
function packDragCancel(){if(packDrag){packDrag.el.classList.remove('dragging');packDrag.el.style.setProperty('--peel','0px');packDrag.el.style.opacity='1';packDrag=null}}
function maybeDailyPack(){if(dailyChecked||!profile)return;dailyChecked=true;let now=new Date();if(!isEligibleLocal(now))return;let k=localDateKey(now),d=loadDailyState();if(d.lastDate===k)return;d.streak=d.lastDate===previousEligible(now)?d.streak+1:1;d.lastDate=k;PreviewStore41.setItem(dailyKey(),JSON.stringify(d));let s=loadV29Settings(),a=s.attendance||DEFAULT_ATTENDANCE_V32,min=d.streak===Number(a.mythDay)&&a.mythDay>0?4:d.streak===Number(a.legendDay)&&a.legendDay>0?3:d.streak===Number(a.uniqueDay)&&a.uniqueDay>0?2:d.streak===Number(a.rareDay)&&a.rareDay>0?1:0,count=Number(s.dailyCards);if(!Number.isFinite(count))count=3;if(count>0)grantCards(count,`${d.streak}일 연속 출석 카드팩`,min)}
function attendanceAdmin(s){let a=s.attendance||DEFAULT_ATTENDANCE_V32;return `<div class="adminpanel"><h3>출석 설정</h3><div class="adminform"><label>접속 시 지급 카드 수<input id="dailyCards" type="number" min="0" max="20" value="${s.dailyCards}"></label><label>인정 요일<select id="weekdayPreset"><option value="weekdays" ${(s.weekdays||[]).length===5?'selected':''}>월~금</option><option value="all" ${(s.weekdays||[]).length===7?'selected':''}>매일</option></select></label><label style="grid-column:1/-1">출석 제외일<textarea id="excludedDates" placeholder="2026-10-05, 2026-12-28">${s.excludedDates||''}</textarea></label></div><h4>연속 접속 보장일 설정</h4><div class="attendancegrid"><label>레어 이상 1장 보장<input id="attendanceRare" type="number" min="0" value="${a.rareDay}">일째</label><label>유니크 이상 1장 보장<input id="attendanceUnique" type="number" min="0" value="${a.uniqueDay}">일째</label><label>전설 이상 1장 보장<input id="attendanceLegend" type="number" min="0" value="${a.legendDay}">일째</label><label>신화 1장 보장<input id="attendanceMyth" type="number" min="0" value="${a.mythDay}">일째</label></div><div class="rules"><b>보상 적용 방식</b><br>하루에 카드 3장을 지급하더라도 보장 등급은 그중 첫 번째 카드 1장에만 적용됩니다. 나머지 카드는 평소 확률로 뽑힙니다. 연속 일수는 20일마다 초기화되지 않고 계속 누적됩니다. 0일로 설정하면 해당 보장을 사용하지 않습니다.</div><button class="btn" onclick="saveAttendanceAdmin()">이 기기에 설정 저장</button></div>`}
function saveAttendanceAdmin(){let s=loadV29Settings(),num=id=>Math.max(0,Number(document.querySelector('#'+id)?.value)||0),daily=Number(document.querySelector('#dailyCards')?.value);s.dailyCards=Math.max(0,Number.isFinite(daily)?daily:3);s.weekdays=document.querySelector('#weekdayPreset')?.value==='all'?[0,1,2,3,4,5,6]:[1,2,3,4,5];s.excludedDates=document.querySelector('#excludedDates')?.value.trim()||'';s.attendance={rareDay:num('attendanceRare'),uniqueDay:num('attendanceUnique'),legendDay:num('attendanceLegend'),mythDay:num('attendanceMyth')};saveV29Settings(s);alert('출석 보상 설정을 저장했습니다. 서버 연결 후 전체 학생에게 같은 기준을 적용할 수 있습니다.')}
function bonusHub(){let best=loadBonusData().best||{},daily=loadDailyState(),streak=Number(daily.streak)||0,a=loadV29Settings().attendance||DEFAULT_ATTENDANCE_V32,milestones=[[a.rareDay,'레어 이상'],[a.uniqueDay,'유니크 이상'],[a.legendDay,'전설 이상'],[a.mythDay,'신화']];return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>게임을 완료하면 개인 최고기록에 도전하고 사건 카드도 받을 수 있습니다.</p><div class="dailybox"><h3>🎁 오늘의 카드팩</h3><p>${daily.lastDate===localDateKey(new Date())?'오늘의 접속 보상 카드 3장을 받았습니다.':'오늘 접속하면 카드 3장을 받을 수 있습니다.'}</p><div class="streaknow">🔥 현재 ${streak}일 연속 접속 중입니다.</div><div class="streakline detail">${milestones.map(([day,label])=>`<span class="${day>0&&streak>=day?'done':''}"><b>${day>0?day+'일 연속 접속':'사용 안 함'}</b><br>${day>0?label+' 카드 1장 보장':label+' 보장 꺼짐'}</span>`).join('')}</div><small>보장 등급은 접속 보상 3장 중 첫 번째 카드 1장에만 적용됩니다. 현재 v3.2는 기기 날짜로 시험 작동합니다.</small></div><div class="bonusmenu"><button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>무오답 순서 배열<span class="rewardline">완료 시 카드 1장 지급</span>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button><button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>영국·미국 사건을 피해 배열<span class="rewardline">미끼 4/6/8장 완료 시 카드 1/2/3장 지급</span></small></button><button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>기본형·고급형 카드 맞추기<span class="rewardline">기본 완료 2장 · 고급 완료 4장 지급</span>고급형만 공식 기록</small></button></div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}
function pityAdmin(s){let p=s.pity,m=s.milestone,st=loadPityV30();return `<div class="adminpanel"><h3>천장·기념 보상 설정</h3><p>0으로 설정하면 해당 규칙을 사용하지 않습니다. 중복 횟수 자체가 높은 등급 확률을 올리지는 않습니다.</p><div class="pitystatus"><span>무작위 추첨<b>${st.total}장</b></span><span>유니크+ 미등장<b>${st.sinceUnique}장</b></span><span>전설+ 미등장<b>${st.sinceLegend}장</b></span><span>신화 미등장<b>${st.sinceMyth}장</b></span></div><div class="pitygrid"><div class="pitycard"><h4>연속 미등장 천장</h4><label>유니크 이상 확정<input id="pityUnique" type="number" min="0" value="${p.uniqueAfter}"></label><label>전설 이상 확정<input id="pityLegend" type="number" min="0" value="${p.legendAfter}"></label><label>신화 확정<input id="pityMyth" type="number" min="0" value="${p.mythAfter}"></label><label>미획득 카드 보장<input id="pityNew" type="number" min="0" value="${p.newAfter}"></label></div><div class="pitycard"><h4>총 무작위 추첨 분기점</h4><label>매 O장 레어 이상<input id="mileRare" type="number" min="0" value="${m.rareEvery}"></label><label>매 O장 전설 이상<input id="mileLegend" type="number" min="0" value="${m.legendEvery}"></label><label>매 O장 신화 확정<input id="mileMyth" type="number" min="0" value="${m.mythEvery}"></label></div></div><div class="rules"><b>미획득 카드 보장이란?</b><br>설정한 장수만큼 무작위 추첨에서 새 카드가 나오지 않고 중복만 나오면, 다음 추첨에서 가능할 경우 그 등급의 아직 갖지 않은 사건 카드를 지급합니다. 등급을 높이는 기능은 아니며 0으로 설정하면 사용하지 않습니다.</div><button class="btn" onclick="savePityAdmin()">천장 설정 저장</button></div>`}
function giftAdmin(){let y=profile?.schoolYear||new Date().getFullYear();return `<div class="adminpanel"><h3>카드 지급</h3><div class="adminform"><label>지급 대상<select id="giftTarget" onchange="syncGiftTarget()"><option value="school">학년도 전체 학생</option><option value="grade">학년 전체</option><option value="class">학년·반 전체</option><option value="student">특정 학생</option><option value="current">현재 시험 학생</option></select></label><label>수량<input id="giftCount" type="number" min="1" max="50" value="1"></label><label>사건<select id="giftEvent"><option value="random">무작위 사건</option>${CH.map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}</select></label><label>등급<select id="giftRarity"><option value="random">무작위 등급</option>${RARITIES.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label></div><div class="targetfields"><label id="targetYearWrap">학년도<input id="targetYear" type="number" value="${y}"></label><label id="targetGradeWrap" class="hiddenfield">학년<input id="targetGrade" type="number" value="${profile?.grade||2}"></label><label id="targetClassWrap" class="hiddenfield">반<input id="targetClass" type="number" value="${profile?.classNo||1}"></label><label id="targetNumberWrap" class="hiddenfield">번호<input id="targetNumber" type="number" value="${profile?.number||1}"></label><label id="targetNameWrap" class="hiddenfield">이름<input id="targetName" value="${esc(profile?.name||'')}"></label></div><div class="giftcombo"><b>학년도별 대상 구분</b><br><span id="giftTargetHelp">${y}학년도에 등록된 전체 학생에게 지급합니다.</span><br>2027학년도 2학년을 선택하면 2026학년도 2학년 학생과 구분됩니다.</div><div class="bonus-actions"><button class="btn" onclick="testGiftCurrent()">현재 학생에게 시험 지급</button><button class="btn alt" onclick="previewBulkGift()">선택 대상 지급 확인</button></div></div>`}
function syncGiftTarget(){let v=document.querySelector('#giftTarget')?.value||'school',show=(id,on)=>{let x=document.querySelector('#'+id);if(x)x.style.display=on?'':'none'},year=v!=='current',grade=['grade','class','student'].includes(v),cls=['class','student'].includes(v),student=v==='student';show('targetYearWrap',year);show('targetGradeWrap',grade);show('targetClassWrap',cls);show('targetNumberWrap',student);show('targetNameWrap',student);let y=document.querySelector('#targetYear')?.value||profile?.schoolYear,g=document.querySelector('#targetGrade')?.value||profile?.grade,c=document.querySelector('#targetClass')?.value||profile?.classNo,n=document.querySelector('#targetNumber')?.value||profile?.number,name=document.querySelector('#targetName')?.value||profile?.name,text=v==='school'?`${y}학년도에 등록된 전체 학생`:v==='grade'?`${y}학년도 ${g}학년 전체 학생`:v==='class'?`${y}학년도 ${g}학년 ${c}반 전체 학생`:v==='student'?`${y}학년도 ${g}학년 ${c}반 ${n}번 ${name}`:`현재 접속 학생 ${profile?.name}`;let h=document.querySelector('#giftTargetHelp');if(h)h.textContent=text+'에게 지급합니다.'}
function syncGiftControls(){syncGiftTarget()}
function previewBulkGift(){syncGiftTarget();let text=document.querySelector('#giftTargetHelp')?.textContent||'선택 대상';alert(text+'\n\n실제 일괄 지급은 Code.gs 카드 서버를 연결한 뒤 활성화됩니다. 학년도·학년·반·번호를 함께 저장하므로 다른 학년도 학생과 섞이지 않습니다.')}
const bonusHubV32=bonusHub;bonusHub=function(){let n=Number(loadV29Settings().dailyCards);if(!Number.isFinite(n))n=3;return bonusHubV32().replaceAll('카드 3장을','카드 '+n+'장을').replaceAll('접속 보상 3장 중','접속 보상 '+n+'장 중')}
const shellV31=shell;shell=function(body){return shellV31(body).replaceAll('v3.1','v3.2')};
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v3.2</span></h1><p>학년도·학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function renderV32(){renderV31();if(app?.innerHTML)app.innerHTML=app.innerHTML.replaceAll('v3.1','v3.2');setTimeout(()=>{if(view==='admin'&&adminView==='gift')syncGiftTarget()},0)}

/* ===== v3.3 learning cards, cyclic attendance, matching levels and premium reveals ===== */
Object.assign(CARD_TEXT,{
1:'국가 재정이 파탄에 이르자 루이 16세가 세 신분의 대표를 소집한 회의입니다. 세금 부담이 컸던 제3신분이 신분별 표결에 반발하면서, 재정 문제는 국민이 정치의 주체가 누구인지 묻는 혁명 문제로 바뀌었습니다.',
2:'제3신분 대표들이 일부 성직자·귀족과 함께 자신들을 국민의 진정한 대표라고 선언해 만든 의회입니다. 국왕이 부여한 신분별 권리보다 국민의 의사를 앞세웠다는 점에서 국민주권과 근대 의회 정치로 나아가는 중요한 전환점이었습니다.',
3:'회의장이 폐쇄되자 국민의회 대표들이 테니스 코트에 모여 헌법을 만들 때까지 해산하지 않겠다고 맹세한 사건입니다. 대표들이 국왕의 명령보다 국민에게서 받은 권한을 앞세워 혁명을 계속하겠다는 집단적 의지를 보여 주었습니다.',
4:'파리 시민들이 무기와 화약을 확보하고 왕의 군사적 탄압에 맞서기 위해 절대왕정의 상징인 바스티유 감옥을 습격한 사건입니다. 민중이 직접 혁명에 참여하면서 혁명이 의회 안의 논쟁을 넘어 전국적인 행동으로 확산되었습니다.',
5:'국민의회가 영주의 특권, 농민의 봉건적 부담, 신분에 따른 여러 특혜를 폐지하기로 결정한 조치입니다. 법적으로 신분제가 무너지고 모든 사람이 같은 시민이라는 새로운 사회 질서의 토대가 마련되었습니다.',
6:'자유와 평등, 국민주권, 법 앞의 평등, 재산권 등 시민의 기본 원칙을 선언한 문서입니다. 프랑스의 구체제를 비판했을 뿐 아니라 이후 세계 여러 나라의 헌법과 인권 사상에도 큰 영향을 주었습니다.',
7:'루이 16세가 혁명을 피해 국외로 탈출하려다 바렌에서 붙잡혀 파리로 돌아온 사건입니다. 국왕이 혁명을 받아들이지 않았다는 사실이 드러나 왕에 대한 신뢰가 무너졌고, 공화정을 요구하는 목소리가 커졌습니다.',
8:'1791년 헌법에 따라 국왕의 권한을 법으로 제한하고 입법권을 의회에 둔 정치 체제입니다. 절대왕정은 끝났지만 재산에 따른 제한선거와 국왕의 거부권이 남아 있어 혁명 세력의 불만도 계속되었습니다.',
9:'새로 구성된 국민공회가 왕정을 폐지하고 프랑스를 공화국으로 선포한 사건입니다. 주권이 세습 군주가 아니라 국민에게 있다는 원칙을 국가 체제로 확정했으며 혁명은 더욱 급진적인 단계로 들어갔습니다.',
10:'국민공회가 루이 16세를 반역죄로 재판해 단두대에서 처형한 사건입니다. 왕정으로 돌아갈 가능성을 끊는 상징적 조치였지만, 유럽 군주국들의 반발과 국내 반혁명 세력의 저항도 더욱 거세졌습니다.',
11:'대외 전쟁과 국내 반란이라는 위기 속에서 자코뱅파와 로베스피에르가 혁명정부를 이끌며 반혁명 혐의자를 강하게 처벌한 정치입니다. 공화국을 지키려 했지만 많은 희생과 억압을 낳아 혁명의 이상과 폭력의 관계를 생각하게 합니다.',
12:'공포 정치에 대한 두려움과 반발이 커지면서 국민공회가 로베스피에르를 체포해 처형한 사건입니다. 이를 테르미도르의 반동이라 하며, 급진적인 공포 정치가 끝나고 온건한 세력이 주도권을 잡는 계기가 되었습니다.',
13:'공포 정치 이후 다섯 명의 총재가 행정부를 맡도록 만든 정부입니다. 급진혁명과 왕정복고를 모두 막으려 했지만 정치적 혼란·부패·경제난이 이어져 군사적 영웅 나폴레옹의 영향력이 커졌습니다.',
14:'나폴레옹이 브뤼메르 18일 쿠데타로 총재정부를 무너뜨리고 통령정부를 세워 권력을 장악한 사건입니다. 프랑스 혁명의 정치적 혼란은 일단 정리되었고, 혁명의 여러 성과는 나폴레옹 시대의 제도와 전쟁을 통해 유럽에 확산되었습니다.'
});

const ACQUIRED_KEY_V33=()=>profile?`fr-v33-acquired:${profile.schoolYear}-${profile.grade}-${profile.classNo}-${profile.number}`:'fr-v33-acquired';
function loadAcquiredV33(){try{return JSON.parse(PreviewStore41.getItem(ACQUIRED_KEY_V33())||'{}')}catch{return{}}}
function saveAcquiredV33(x){PreviewStore41.setItem(ACQUIRED_KEY_V33(),JSON.stringify(x))}
function acquiredLabelV33(eventId,rarityId,locked){if(locked)return'최초 획득일 —';let x=loadAcquiredV33()[eventId+'-'+rarityId];return x?`최초 획득 ${x}`:'이전 버전에서 획득'}
function markAcquiredV33(cards,before){let a=loadAcquiredV33(),today=localDateKey(new Date());cards.forEach(x=>{let k=x.event.id+'-'+x.rar.id;if(!(before[k]>0)&&!a[k])a[k]=today});saveAcquiredV33(a)}

function collectCard(event,rar,count,locked=false,interactive=true){let q=CH.find(x=>x.id===event.id)||event,desc=CARD_TEXT[q.id]||'',year=CARD_YEARS[q.id]||'1789',open=!locked&&interactive?`onclick="inspectCard(event,${q.id},'${rar.id}',${count||0})" role="button" tabindex="0" onkeydown="if(event.key==='Enter')inspectCard(event,${q.id},'${rar.id}',${count||0})"`:'';return `<article class="collectcard premium ${rar.id} ${locked?'lockedcard':''}" ${open}><div class="cardname">${locked?'???':q.title}</div><div class="cardart"><img src="${IMAGES[q.img-1]}" alt="${locked?'미획득 카드':q.title}"></div><div class="cardyear">${locked?'????':year}</div><div class="carddesc">${locked?'아직 발견하지 못한 프랑스 혁명 사건 카드입니다.':desc}</div><div class="cardfoot"><span class="cardrarity">${rar.name}</span><span class="acquired">${acquiredLabelV33(q.id,rar.id,locked)}</span><span>${locked?'미획득':'보유 '+(count||0)+'장'}</span></div></article>`}

function grantCards(count,source,minIndex=0){let before=loadCollection(),c={...before},stats=loadPityV30(),cards=[];for(let i=0;i<count;i++)cards.push(drawCardV30(c,stats,i===0?minIndex:0));markAcquiredV33(cards,before);saveCollection(c);savePityV30(stats);reward=null;packReward={source,cards,revealed:0,lastReveal:-1};renderV33()}
function testGiftCurrent(){let n=Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),ev=document.querySelector('#giftEvent')?.value||'random',rv=document.querySelector('#giftRarity')?.value||'random',before=loadCollection(),c={...before},cards=[];for(let i=0;i<n;i++){let e=ev==='random'?CH[Math.floor(Math.random()*CH.length)]:CH.find(x=>x.id===Number(ev)),r=rv==='random'?drawRarity(0):rarityById(rv),k=e.id+'-'+r.id;c[k]=(c[k]||0)+1;cards.push({event:e,rar:r,count:c[k]})}markAcquiredV33(cards,before);saveCollection(c);packReward={source:'교사 지급',cards,revealed:0,lastReveal:-1};renderV33()}

function cardInspectModal(){if(!cardInspect)return'';let q=cardInspect.event,i=CH.findIndex(x=>x.id===q.id),prev=CH[i-1],next=CH[i+1],rar=cardInspect.rar;return `<div class="cardinspect" onclick="cardInspect=null;renderV33()"><div class="inspectpanel" onclick="event.stopPropagation()"><button class="inspectclose" onclick="cardInspect=null;renderV33()" aria-label="닫기">×</button><div class="flipscene"><div class="flipinner ${cardInspect.flipped?'flipped':''}"><div class="flipface" onclick="flipInspect(event)">${collectCard(q,rar,cardInspect.count,false,false)}</div><div class="flipface flipback ${rar.id}" style="--metal:${rar.id==='legend'?'#ffd45b':rar.id==='unique'?'#bf7aff':rar.id==='rare'?'#87b9f4':rar.id==='myth'?'#9ffeff':'#9a7b52'}" onclick="flipInspect(event)"><div class="backcontent"><div class="backbadge"><span>${i+1}</span></div><p class="eyebrow">프랑스 혁명의 흐름 · ${i+1}/14</p><h2>${q.title}</h2><div class="backmeaning">${CARD_TEXT[q.id]}</div><div class="flowrow"><div class="flowitem"><small>이전 사건</small><br>${prev?prev.title:'혁명의 배경'}</div><b>→</b><div class="flowitem"><small>다음 사건</small><br>${next?next.title:'나폴레옹 시대'}</div></div><p class="backhint">카드를 누르면 앞면으로 돌아갑니다.</p></div></div></div></div><p class="inspecttip">카드를 누르면 앞·뒷면이 전환됩니다. 바깥을 누르면 닫힙니다.</p></div></div>`}

const DEFAULT_ATTENDANCE_V33={cycleDays:15,rareDay:5,uniqueDay:10,legendDay:15,mythDay:0};
const loadSettingsV32=loadV29Settings;loadV29Settings=function(){let s=loadSettingsV32(),a={...DEFAULT_ATTENDANCE_V33,...(s.attendance||{})};a.cycleDays=Math.max(1,Number(a.cycleDays)||20);return{...s,cycleDays:a.cycleDays,attendance:a}};
function maybeDailyPack(){if(dailyChecked||!profile)return;dailyChecked=true;let now=new Date();if(!isEligibleLocal(now))return;let k=localDateKey(now),d=loadDailyState();if(d.lastDate===k)return;let continued=d.lastDate===previousEligible(now),oldCycle=Math.max(0,Number(d.streak)||0),oldTotal=Math.max(oldCycle,Number(d.totalStreak)||oldCycle),s=loadV29Settings(),a=s.attendance||DEFAULT_ATTENDANCE_V33,cycle=Math.max(1,Number(a.cycleDays)||20);d.totalStreak=continued?oldTotal+1:1;d.streak=continued?(oldCycle>=cycle?1:oldCycle+1):1;d.lastDate=k;PreviewStore41.setItem(dailyKey(),JSON.stringify(d));let day=d.streak,min=day===Number(a.mythDay)&&a.mythDay>0?4:day===Number(a.legendDay)&&a.legendDay>0?3:day===Number(a.uniqueDay)&&a.uniqueDay>0?2:day===Number(a.rareDay)&&a.rareDay>0?1:0,count=Number(s.dailyCards);if(!Number.isFinite(count))count=3;if(count>0)grantCards(count,`${day}/${cycle}일 출석 카드팩`,min)}
function attendanceAdmin(s){let a=s.attendance||DEFAULT_ATTENDANCE_V33;return `<div class="adminpanel"><h3>출석 설정</h3><div class="adminform"><label>접속 시 지급 카드 수<input id="dailyCards" type="number" min="0" max="20" value="${s.dailyCards}"></label><label>출석 보상 주기<input id="attendanceCycle" type="number" min="1" max="365" value="${a.cycleDays}">일</label><label>인정 요일<select id="weekdayPreset"><option value="weekdays" ${(s.weekdays||[]).length===5?'selected':''}>월~금</option><option value="all" ${(s.weekdays||[]).length===7?'selected':''}>매일</option></select></label><label style="grid-column:1/-1">출석 제외일<textarea id="excludedDates" placeholder="2026-10-05, 2026-12-28">${s.excludedDates||''}</textarea></label></div><h4>한 주기 안의 등급 보장일</h4><div class="attendancegrid"><label>레어 이상 1장 보장<input id="attendanceRare" type="number" min="0" value="${a.rareDay}">일째</label><label>유니크 이상 1장 보장<input id="attendanceUnique" type="number" min="0" value="${a.uniqueDay}">일째</label><label>전설 이상 1장 보장<input id="attendanceLegend" type="number" min="0" value="${a.legendDay}">일째</label><label>신화 1장 보장<input id="attendanceMyth" type="number" min="0" value="${a.mythDay}">일째</label></div><div class="rules"><b>20일 주기 예시</b><br>5일째 레어 이상, 10일째 유니크 이상, 15일째 전설 이상, 20일째 신화가 각각 한 번 적용됩니다. 10일째에 5일 보상이 다시 겹치지 않습니다. 20일 보상을 받은 다음 인정 출석일은 새 주기의 1일째가 됩니다. 하루 카드팩 중 보장 등급은 첫 카드 1장에만 적용됩니다.</div><button class="btn" onclick="saveAttendanceAdmin()">이 기기에 설정 저장</button></div>`}
function saveAttendanceAdmin(){let s=loadV29Settings(),num=id=>Math.max(0,Number(document.querySelector('#'+id)?.value)||0),daily=Number(document.querySelector('#dailyCards')?.value),cycle=Math.max(1,num('attendanceCycle')||20);s.dailyCards=Math.max(0,Number.isFinite(daily)?daily:3);s.weekdays=document.querySelector('#weekdayPreset')?.value==='all'?[0,1,2,3,4,5,6]:[1,2,3,4,5];s.excludedDates=document.querySelector('#excludedDates')?.value.trim()||'';s.cycleDays=cycle;s.attendance={cycleDays:cycle,rareDay:num('attendanceRare'),uniqueDay:num('attendanceUnique'),legendDay:num('attendanceLegend'),mythDay:num('attendanceMyth')};saveV29Settings(s);alert('출석 보상 주기와 등급 보장일을 저장했습니다. 서버 연결 후 전체 학생에게 같은 기준을 적용할 수 있습니다.')}

function matchingPage(){if(!matchGame)return `<section class="shell quiz center"><p class="eyebrow">🃏 짝맞추기</p><h2>게임 방식과 세트 수를 고르세요</h2><p>처음에는 6세트로 익히고, 익숙해지면 8·10·12세트에 도전하세요.</p>${['basic','advanced'].map(v=>`<div class="matchpick"><h3>${v==='basic'?'기본 카드 맞추기':'고급 카드 맞추기'}</h3><p>${v==='basic'?'그림·제목·설명이 같은 카드끼리 맞추기':'그림+제목 카드와 그 사건 설명 카드 맞추기'}</p><div class="settingrow">${[6,8,10,12].map(n=>`<button onclick="startMatching('${v}',${n})"><b>${n}세트</b><small>카드 ${v==='advanced'?[2,3,4,5][[6,8,10,12].indexOf(n)]:[1,2,3,4][[6,8,10,12].indexOf(n)]}장 지급${v==='advanced'&&n>=10?'<br>레어 이상 1장 보장':''}</small></button>`).join('')}</div></div>`).join('')}<p class="best">공식 기록은 고급 12세트만 등록 · 최고 <b>${bestFor('matching')?precise(bestFor('matching')):'기록 없음'}</b></p><button class="btn alt" onclick="go('bonus')">돌아가기</button></section>`;if(matchGame.status==='completed')return finishBonusPage('짝맞추기',matchGame,'matching',matchGame.official,`${matchGame.setCount}세트 · ${matchGame.moves}번 뒤집기 · ${matchGame.official?'고급 12세트 공식 기록입니다.':'연습 기록입니다.'}`);return `<section class="shell"><div class="practicebar"><div><p class="eyebrow">짝맞추기 · ${matchGame.variant==='advanced'?'<span class="officialtag">고급형</span>':'<span class="casualtag">기본형</span>'}</p><h2>${matchGame.setCount}세트의 짝을 찾으세요</h2></div><div class="speedstats"><span class="speedstat">완성<b>${matchGame.done.length/2}/${matchGame.setCount}</b></span><span class="speedstat">뒤집기<b>${matchGame.moves}회</b></span><span class="speedstat">현재 시간<b id="bonusclock">${precise(bonusNow(matchGame))}</b></span><button class="btn alt" onclick="matchGame=null;go('bonus')">중단</button></div></div><div class="matchgrid match-${matchGame.setCount}">${matchGame.cards.map((c,i)=>matchCard(c,i)).join('')}</div></section>`}
function startMatching(variant,setCount=6){setCount=[6,8,10,12].includes(Number(setCount))?Number(setCount):6;let chosen=shuffle(Q).slice(0,setCount),cards=[];chosen.forEach(q=>{cards.push({pair:q.id,side:0,q});cards.push({pair:q.id,side:1,q})});matchGame={status:'active',variant,setCount,cards:shuffle(cards),open:[],done:[],moves:0,lock:false,startedAt:performance.now(),finishedMs:0,official:variant==='advanced'&&setCount===12};renderV33();bonusClock()}
function finishMatching(){matchGame.status='completed';matchGame.finishedMs=performance.now()-matchGame.startedAt;if(matchGame.official)saveOfficial('짝맞추기','matching',matchGame.finishedMs,{attempts:matchGame.moves});let ix=[6,8,10,12].indexOf(matchGame.setCount),advanced=matchGame.variant==='advanced',count=(advanced?[2,3,4,5]:[1,2,3,4])[Math.max(0,ix)],min=advanced&&matchGame.setCount>=10?1:0;grantCards(count,`${advanced?'고급':'기본'} 짝맞추기 ${matchGame.setCount}세트`,min)}

function bonusHub(){let best=loadBonusData().best||{},daily=loadDailyState(),streak=Number(daily.streak)||0,total=Number(daily.totalStreak)||streak,a=loadV29Settings().attendance||DEFAULT_ATTENDANCE_V33,cycle=Math.max(1,Number(a.cycleDays)||20),milestones=[[a.rareDay,'레어 이상'],[a.uniqueDay,'유니크 이상'],[a.legendDay,'전설 이상'],[a.mythDay,'신화']];return `<section class="shell"><p class="eyebrow">고급 완료 보너스</p><h2>원하는 게임에 도전하세요</h2><p>게임을 완료하면 개인 최고기록에 도전하고 사건 카드도 받을 수 있습니다.</p><div class="dailybox"><h3>🎁 오늘의 카드팩</h3><p>${daily.lastDate===localDateKey(new Date())?'오늘의 접속 보상 카드 3장을 받았습니다.':'오늘 접속하면 카드 3장을 받을 수 있습니다.'}</p><div class="streaknow">🔥 현재 ${total}일 연속 접속 · 이번 보상 주기 ${streak}/${cycle}일</div><div class="streakline detail">${milestones.map(([day,label])=>`<span class="${day>0&&streak>=day?'done':''}"><b>${day>0?day+'일째':'사용 안 함'}</b><br>${day>0?label+' 카드 1장 보장':label+' 보장 꺼짐'}</span>`).join('')}</div><small>각 보상은 한 주기에 한 번씩만 적용되며, 보장 등급은 접속 보상 중 첫 카드 1장에만 적용됩니다. 현재는 기기 날짜로 시험 작동합니다.</small></div><div class="bonusmenu"><button onclick="go('speedrun')"><span class="bonusicon">⚡</span><strong>스피드런</strong><small>무오답 순서 배열<span class="rewardline">완료 시 카드 1장 지급</span>최고 ${best.speedrun?precise(best.speedrun):'기록 없음'}</small></button><button onclick="go('baitrun')"><span class="bonusicon">🎭</span><strong>미끼런</strong><small>영국·미국 사건을 피해 배열<span class="rewardline">미끼 4/6/8장 완료 시 카드 1/2/3장 지급</span></small></button><button onclick="go('matching')"><span class="bonusicon">🃏</span><strong>짝맞추기</strong><small>기본·고급 6/8/10/12세트<span class="rewardline">고급은 카드 2/3/4/5장 지급</span>고급 12세트만 공식 기록</small></button></div><div class="bonus-actions"><button class="btn alt" onclick="go('practice')">전체 연습 모드</button><button class="btn alt" onclick="go('collection')">📚 카드 도감</button></div></section>`}

function rewardModal(){if(!packReward)return'';let all=packReward.revealed>=packReward.cards.length,current=packReward.revealed;return `<div class="rewardmodal"><div class="packbox"><h2 class="packtitle">${all?'카드팩 개봉 완료!':'카드팩을 개봉하세요'}</h2><p class="packhint">${all?'획득한 카드는 카드 도감에서 크게 볼 수 있습니다.':'짧게 누르면 개봉되고, 덮개를 아래로 드래그하면 위쪽부터 천천히 확인할 수 있습니다.'}</p><div class="packcards">${packReward.cards.map((x,i)=>{let shown=i<current,recent=i===packReward.lastReveal,idx=rarityIndexV30(x.rar),omen=!shown&&i===current&&idx>=2?' omen-'+x.rar.id:'',state=shown?'unveiled':i===current?'covered':'covered queued';return `<div class="packwrap ${state}${omen} ${recent?'recent rarity-'+x.rar.id:''}">${collectCard(x.event,x.rar,x.count,false,shown)}${!shown?`<div class="packcover" data-pack="${i}" style="--peel:0px" onpointerdown="packDragStart(event,${i})" onpointermove="packDragMove(event)" onpointerup="packDragEnd(event)" onpointercancel="packDragCancel(event)"><span class="packomen"></span></div>`:''}${shown&&recent?`<div class="rarity-banner ${x.rar.id}">${x.rar.name} 등장!</div>`:''}</div>`}).join('')}</div>${all?'<button class="btn" onclick="packReward=null;renderV33()">도감에 보관</button>':'<button class="btn alt" onclick="revealAllPack()">연속 자동 개봉</button>'}</div></div>`}
function cinematicReveal(i,el){if(!packReward||i!==packReward.revealed)return;el.classList.add('seal-release');el.style.setProperty('--peel','330px');el.style.opacity='0';setTimeout(()=>revealPack(i),460)}
function revealPack(i){if(!packReward||i!==packReward.revealed)return;packReward.revealed++;packReward.lastReveal=i;renderV33()}

function previewBulkGift(){syncGiftTarget();let help=document.querySelector('#giftTargetHelp')?.textContent||'선택 대상',target=document.querySelector('#giftTarget')?.value||'school',reservation={id:'gift-'+Date.now(),createdAt:new Date().toISOString(),target,schoolYear:Number(document.querySelector('#targetYear')?.value)||profile?.schoolYear,grade:document.querySelector('#targetGrade')?.value||'',classNo:document.querySelector('#targetClass')?.value||'',number:document.querySelector('#targetNumber')?.value||'',name:document.querySelector('#targetName')?.value||'',count:Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),event:document.querySelector('#giftEvent')?.value||'random',rarity:document.querySelector('#giftRarity')?.value||'random'};let q=JSON.parse(PreviewStore41.getItem('fr-v33-gift-reservation-draft')||'[]');q.push(reservation);PreviewStore41.setItem('fr-v33-gift-reservation-draft',JSON.stringify(q));alert(help+'\n\n지급 예약안을 이 기기에 저장했습니다. Code.gs 연결 후에는 현재 등록 학생은 다음 동기화 때, 아직 접속하지 않은 학생은 최초 등록 때 대상 조건을 확인해 한 번만 받도록 전송됩니다.')}

const shellV33Base=shell;shell=function(body){return shellV33Base(body).replaceAll('v3.2','v3.3')};
function profileScreen(){app.innerHTML=`<main class="profile"><form class="shell"><p class="eyebrow">학습 기록 설정</p><h1>학생 정보를 입력하세요 <span class="version">v3.3</span></h1><p>학년도·학년·반·번호와 이름으로 학습 기록을 구분합니다.</p><div class="fields"><label>학년<input id="g" inputmode="numeric" required></label><label>반<input id="c" inputmode="numeric" required></label><label>번호<input id="n" inputmode="numeric" required></label><label>이름<input id="nm" autocomplete="name" maxlength="20" required></label></div><button class="btn">학습 시작</button></form></main>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();setProfile({grade:g.value.trim(),classNo:c.value.trim(),number:n.value.trim(),name:nm.value.trim()})}}
function renderV33(){renderV32();document.title='프랑스 혁명 학습 게임 v3.3';if(app?.innerHTML)app.innerHTML=app.innerHTML.replaceAll('v3.2','v3.3');setTimeout(()=>{if(view==='admin'&&adminView==='gift')syncGiftTarget()},0)}
/* ===== v3.4 collection fusion ===== */
const FUSION_POINTS_V34={normal:1,rare:2,unique:4,legend:8,myth:16};
let collectionModeV34='book',fusionSlotsV34=[];
function loadFusionSettingsV34(){try{return{mode:'fast',...JSON.parse(PreviewStore41.getItem('fr-v34-fusion-settings')||'{}')}}catch{return{mode:'fast'}}}
function saveFusionSettingsV34(){let mode=document.querySelector('#fusionRuleV34')?.value||'fast';PreviewStore41.setItem('fr-v34-fusion-settings',JSON.stringify({mode}));alert((mode==='fast'?'빠른 성장':'도전 성장')+' 합성 규칙으로 저장했습니다.');renderV34()}
function rarityIxV34(id){return Math.max(0,RARITIES.findIndex(x=>x.id===id))}
function selectedCountV34(k){return fusionSlotsV34.filter(x=>x.key===k).length}
function addFusionCardV34(eventId,rarityId){if(fusionSlotsV34.length>=5)return;let c=loadCollection(),k=eventId+'-'+rarityId;if((c[k]||0)-1-selectedCountV34(k)<1){alert('도감에 남겨 둘 마지막 1장은 합성할 수 없습니다.');return}fusionSlotsV34.push({eventId,rarityId,key:k});renderV34()}
function removeFusionCardV34(i){fusionSlotsV34.splice(i,1);renderV34()}
function clearFusionV34(){fusionSlotsV34=[];renderV34()}
function fusionAnalysisV34(){let mode=loadFusionSettingsV34().mode,score=fusionSlotsV34.reduce((s,x)=>s+FUSION_POINTS_V34[x.rarityId],0),ready=fusionSlotsV34.length===5,ids=fusionSlotsV34.map(x=>x.rarityId),same=ready&&ids.every(x=>x===ids[0]),probs=[0,0,0,0,0],floor=0,progress=0,missingChance=0,note='카드 5장을 선택하세요.';if(!ready)return{mode,score,ready,probs,floor,progress,missingChance,note};if(mode==='fast'&&same){let i=rarityIxV34(ids[0]);if(i===0)probs=[0,84,15,1,0];else if(i===1)probs=[0,0,84,15,1];else if(i===2)probs=[0,0,0,85,15];else probs=[0,0,0,0,100];floor=Math.min(4,i+1);missingChance=i===4?100:0;note=i===4?'신화 5장: 미보유 신화 확정':'동일 등급 5장: 최소 한 단계 상승 100% 보장';return{mode,score,ready,probs,floor,progress,missingChance,note,same:true}}let cuts=mode==='fast'?[5,10,20,40]:[7,14,28,56],idx=-1;cuts.forEach((v,i)=>{if(score>=v)idx=i});floor=idx<0?0:idx+1;let low=idx<0?5:cuts[idx],high=idx+1<cuts.length?cuts[idx+1]:80;progress=Math.max(0,Math.min(1,(score-low)/Math.max(1,high-low)));if(floor===4)probs[4]=100;else{let jackpot=floor<=2?Math.round(progress*5):0,base=Math.round(80-progress*55);probs[floor]=base;probs[floor+1]=100-base-jackpot;if(jackpot)probs[floor+2]=jackpot}if(progress>=.9)missingChance=100;else if(progress>=.6)missingChance=70;note=(mode==='fast'?'빠른 성장':'도전 성장')+' · 최소 '+RARITIES[floor].name+' 이상 보장';return{mode,score,ready,probs,floor,progress,missingChance,note,same:false}}
function fusionOddsV34(a){return `<div class="fusionresult"><div class="fusionheadline"><span>총점 <b>${a.score}점</b></span><span>선택 <b>${fusionSlotsV34.length}/5장</b></span></div><h3>${a.ready?a.note:'카드 5장을 올려 주세요'}</h3>${a.ready?`<div class="fusionodds">${RARITIES.map((r,i)=>`<span class="${a.probs[i]?'live':''}">${r.name}<b>${a.probs[i]||0}%</b></span>`).join('')}</div><div class="fusionpromise"><b>최소 보장</b> ${RARITIES[a.floor].name} 이상 100%${a.missingChance?`<br><b>미보유 보정</b> ${RARITIES[a.floor].name} 당첨 시 미보유 카드 ${a.missingChance}%`:''}</div>`:`<p>카드를 넣고 뺄 때마다 등급별 확률과 최소 보장이 즉시 계산됩니다.</p>`}</div>`}
function fusionPickerV34(){let c=loadCollection();return `<div class="fusionpicker">${RARITIES.map(r=>`<section><h3>${r.name} · 1장당 ${FUSION_POINTS_V34[r.id]}점</h3><div class="fusioncards">${CH.map(e=>{let k=e.id+'-'+r.id,n=c[k]||0,left=Math.max(0,n-1-selectedCountV34(k));return n>1?`<button class="fusionpick" onclick="addFusionCardV34(${e.id},'${r.id}')" ${left?'':'disabled'}><img src="${IMAGES[e.img-1]}" alt=""><span>${e.title}</span><small>보유 ${n} · 사용 가능 ${left}</small></button>`:''}).join('')||'<p class="muted">합성 가능한 중복 카드가 없습니다.</p>'}</div></section>`).join('')}</div>`}
function fusionPageV34(){let a=fusionAnalysisV34(),rule=a.mode==='fast'?'빠른 성장':'도전 성장';return `<div class="fusionintro"><b>현재 규칙: ${rule}</b><span>${a.mode==='fast'?'같은 등급 5장은 최소 한 단계 상승이 100% 보장됩니다.':'총점 7·14·28·56점에서 레어·유니크·전설·신화가 보장됩니다.'}</span></div><div class="fusionworkspace"><div><h3>합성 슬롯</h3><div class="fusionslots">${[0,1,2,3,4].map(i=>{let x=fusionSlotsV34[i];if(!x)return'<div class="fusionslot empty">＋</div>';let e=CH.find(q=>q.id===x.eventId),r=rarityById(x.rarityId);return `<button class="fusionslot ${r.id}" onclick="removeFusionCardV34(${i})"><img src="${IMAGES[e.img-1]}" alt=""><span>${e.title}</span><small>${r.name} · ${FUSION_POINTS_V34[r.id]}점</small></button>`}).join('')}</div><div class="bonus-actions"><button class="btn alt" onclick="clearFusionV34()">선택 초기화</button><button class="btn" onclick="performFusionV34()" ${a.ready?'':'disabled'}>5장 합성하기</button></div><p class="fusionguard">각 사건·등급의 마지막 1장은 도감 보호를 위해 사용할 수 없습니다.</p></div>${fusionOddsV34(a)}</div>${fusionPickerV34()}`}
function collectionBookV34(){let c=loadCollection(),owned=Object.keys(c).filter(k=>c[k]>0).length,stats=loadPityV30();return `<div class="practicebar"><div><p class="eyebrow">프랑스 혁명 사건 카드</p><h2>📚 카드 도감 ${owned}/70</h2></div><span class="pill">무작위 추첨 ${stats.total}장</span></div><p>카드를 누르면 크게 보고 뒷면의 상세 설명을 확인할 수 있습니다.</p>${RARITIES.map(r=>`<section><h3>${r.name}</h3><div class="collectiongrid">${CH.map(e=>{let n=c[e.id+'-'+r.id]||0;return collectCard(e,r,n,!n)}).join('')}</div></section>`).join('')}`}
function collectionPage(){return `<section class="shell"><div class="collectionsubnav"><button class="${collectionModeV34==='book'?'on':''}" onclick="collectionModeV34='book';renderV34()">📚 카드 도감</button><button class="${collectionModeV34==='fusion'?'on':''}" onclick="collectionModeV34='fusion';renderV34()">⚗️ 카드 합성</button></div>${collectionModeV34==='book'?collectionBookV34():fusionPageV34()}</section>`}
function performFusionV34(){let a=fusionAnalysisV34();if(!a.ready)return;let c=loadCollection(),need={};fusionSlotsV34.forEach(x=>need[x.key]=(need[x.key]||0)+1);for(let k in need)if((c[k]||0)-need[k]<1){alert('카드 수량이 달라졌습니다. 다시 선택해 주세요.');clearFusionV34();return}if(!confirm(`선택한 카드 5장을 사용합니다.\n총 ${a.score}점 · ${a.note}\n사용한 카드는 되돌릴 수 없습니다.`))return;let before={...c};fusionSlotsV34.forEach(x=>c[x.key]--);let roll=Math.random()*100,sum=0,ri=0;for(let i=0;i<a.probs.length;i++){sum+=a.probs[i];if(roll<sum){ri=i;break}}let rar=RARITIES[ri],missing=CH.filter(e=>!(c[e.id+'-'+rar.id]>0)),useMissing=missing.length&&a.missingChance>0&&Math.random()*100<a.missingChance,event=useMissing?missing[Math.floor(Math.random()*missing.length)]:CH[Math.floor(Math.random()*CH.length)],k=event.id+'-'+rar.id;c[k]=(c[k]||0)+1;saveCollection(c);let card={event,rar,count:c[k]};markAcquiredV33([card],before);fusionSlotsV34=[];packReward={source:'카드 합성',cards:[card],revealed:0,lastReveal:-1};renderV34()}
const attendanceAdminV34Base=attendanceAdmin;attendanceAdmin=function(s){return attendanceAdminV34Base(s).replace('<b>20일 주기 예시</b><br>5일째 레어 이상, 10일째 유니크 이상, 15일째 전설 이상, 20일째 신화가 각각 한 번 적용됩니다. 10일째에 5일 보상이 다시 겹치지 않습니다. 20일 보상을 받은 다음 인정 출석일은 새 주기의 1일째가 됩니다. 하루 카드팩 중 보장 등급은 첫 카드 1장에만 적용됩니다.','<b>15일 주기 기본값</b><br>5일째 레어 이상, 10일째 유니크 이상, 15일째 전설 이상이 각각 한 번 적용됩니다. 출석으로 신화 카드는 지급하지 않으며, 15일 보상 다음 인정 출석일은 새 주기의 1일째가 됩니다. 보장 등급은 카드팩의 첫 카드 1장에만 적용됩니다.')}
function migrateAttendanceV34(){if(PreviewStore41.getItem('fr-v34-attendance-migrated'))return;let s=loadV29Settings(),a=s.attendance||{};if(Number(a.cycleDays)===20&&Number(a.rareDay)===5&&Number(a.uniqueDay)===10&&Number(a.legendDay)===15&&Number(a.mythDay)===20){s.cycleDays=15;s.attendance={...a,cycleDays:15,mythDay:0};saveV29Settings(s)}PreviewStore41.setItem('fr-v34-attendance-migrated','1')}
function fusionAdminV34(){let m=loadFusionSettingsV34().mode;return `<div class="adminpanel"><h3>카드 합성 설정</h3><label class="oddsrow"><span>합성 규칙</span><select id="fusionRuleV34"><option value="fast" ${m==='fast'?'selected':''}>1안 · 빠른 성장</option><option value="challenge" ${m==='challenge'?'selected':''}>2안 · 도전 성장</option></select></label><div class="rules"><b>빠른 성장</b><br>같은 등급 5장은 최소 한 단계 상승 100% 보장.<br><br><b>도전 성장</b><br>7점 레어, 14점 유니크, 28점 전설, 56점 신화 최소 보장.</div><button class="btn" onclick="saveFusionSettingsV34()">합성 규칙 저장</button><p class="serverpending">현재는 이 기기에 저장됩니다. Code.gs 연결 후 모든 학생에게 동일하게 적용됩니다.</p></div>`}
