function testGiftCurrent(){let n=Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),ev=document.querySelector('#giftEvent')?.value||'random',rv=document.querySelector('#giftRarity')?.value||'random',unowned=document.querySelector('#giftOwnership')?.value==='unowned',before=loadCollection(),c={...before},cards=[];for(let i=0;i<n;i++){let pick=giftCandidateV35(c,ev,rv,unowned);if(!pick)break;c[pick.key]=(c[pick.key]||0)+1;cards.push({event:pick.event,rar:pick.rar,count:c[pick.key]})}if(!cards.length){alert('선택한 조건에 해당하는 미보유 카드가 없습니다. 지급 조건을 변경해 주세요.');return}markAcquiredV33(cards,before);saveCollection(c);if(cards.length<n)alert(`조건에 맞는 미보유 카드가 ${cards.length}장뿐이어서 ${cards.length}장만 지급합니다.`);packReward={source:'교사 지급',cards,revealed:0,lastReveal:-1};renderV35()}
function previewBulkGift(){syncGiftTarget();let help=document.querySelector('#giftTargetHelp')?.textContent||'선택 대상',target=document.querySelector('#giftTarget')?.value||'school',reservation={id:'gift-'+Date.now(),createdAt:new Date().toISOString(),target,schoolYear:Number(document.querySelector('#targetYear')?.value)||profile?.schoolYear,grade:document.querySelector('#targetGrade')?.value||'',classNo:document.querySelector('#targetClass')?.value||'',number:document.querySelector('#targetNumber')?.value||'',name:document.querySelector('#targetName')?.value||'',count:Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),ownership:document.querySelector('#giftOwnership')?.value||'any',event:document.querySelector('#giftEvent')?.value||'random',rarity:document.querySelector('#giftRarity')?.value||'random'};let q=JSON.parse(PreviewStore41.getItem('fr-v35-gift-reservation-draft')||'[]');q.push(reservation);PreviewStore41.setItem('fr-v35-gift-reservation-draft',JSON.stringify(q));alert(help+'\n\n지급 예약안을 저장했습니다. Code.gs 연결 후 학생별 보유 현황을 확인해 미보유 조건까지 적용합니다.')}
