function missionSlotV36(state,m){let k=periodKeyV36(m.period),x=state[m.id];if(!x||x.periodKey!==k)x=state[m.id]={periodKey:k,progress:0,claimed:false};return x}
function missionConditionV36(m,meta={}){if(m.metric==='sets')return Number(meta.setCount)>=Number(m.conditionValue||0);if(m.metric==='time')return Number(meta.elapsedSeconds)>0&&Number(meta.elapsedSeconds)<=Number(m.conditionValue||0);return true}
function missionConditionTextV36(m){if(m.metric==='sets')return `${m.conditionValue||0}세트 이상`;if(m.metric==='time')return `${m.conditionValue||0}초 이내`;return'완주'}
function recordMissionV36(game,amount=1,meta={}){if(!profile)return;let s=loadSettingsV36(),state=loadMissionStateV36();s.missions.filter(m=>m.active&&(m.game==='any'||m.game===game)&&missionConditionV36(m,meta)).forEach(m=>{let x=missionSlotV36(state,m);if(!x.claimed)x.progress=Math.min(Number(m.target)||1,x.progress+amount)});saveMissionStateV36(state)}
function claimMissionV36(id){let s=loadSettingsV36(),m=s.missions.find(x=>x.id===id);if(!m)return;let state=loadMissionStateV36(),x=missionSlotV36(state,m);if(x.claimed||x.progress<(Number(m.target)||1))return;x.claimed=true;saveMissionStateV36(state);grantPackV36(m.reward,Number(m.rewardCount)||1,`${m.period==='daily'?'일일':m.period==='weekly'?'주간':'월간'} 미션 · ${m.title}`)}
function periodNameV36(x){return x==='daily'?'일일':x==='weekly'?'주간':'월간'}
function missionBoardV36(){let s=loadSettingsV36(),state=loadMissionStateV36(),list=s.missions.filter(x=>x.active);return `<section class="missionboard"><h3>📜 오늘과 이번 기간의 미션</h3><div class="missiongrid">${list.map(m=>{let x=missionSlotV36(state,m),target=Math.max(1,Number(m.target)||1),done=x.progress>=target,p=packByIdV36(m.reward);return `<article class="missioncard ${done?'done':''}"><small>${periodNameV36(m.period)} 미션</small><h4>${m.title}</h4><p>${GAME_OPTIONS_V36.find(g=>g[0]===m.game)?.[1]||'게임'} · ${missionConditionTextV36(m)} · ${target}회</p><div class="missionprogress"><i style="width:${Math.min(100,x.progress/target*100)}%"></i></div><div class="missionreward"><span>${x.progress}/${target} · ${p.name} ${m.rewardCount}장</span><button onclick="claimMissionV36('${m.id}')" ${done&&!x.claimed?'':'disabled'}>${x.claimed?'수령 완료':done?'보상 받기':'진행 중'}</button></div></article>`}).join('')}</div><small>현재는 이 기기의 완료 기록으로 시험 작동합니다. 서버 연결 후 날짜 변경과 중복 수령을 서버에서 차단합니다.</small></section>`}
function missionAdminV36(){let s=loadSettingsV36();return `<div class="adminpanel"><h3>일일·주간·월간 미션 설정</h3><p>완주 횟수, 최소 세트 수, 제한시간과 지급 카드팩을 직접 변경할 수 있습니다.</p>${s.missions.map((m,i)=>`<div class="missionadminrow"><label>사용<input id="ms_active_${i}" type="checkbox" ${m.active?'checked':''}></label><label>기간<select id="ms_period_${i}">${['daily','weekly','monthly'].map(x=>`<option value="${x}" ${m.period===x?'selected':''}>${periodNameV36(x)}</option>`).join('')}</select></label><label>필요 횟수<input id="ms_target_${i}" type="number" min="1" max="100" value="${m.target}"></label><label>대상 게임<select id="ms_game_${i}">${GAME_OPTIONS_V36.map(([k,n])=>`<option value="${k}" ${m.game===k?'selected':''}>${n}</option>`).join('')}</select></label><label>조건<select id="ms_metric_${i}"><option value="complete" ${m.metric==='complete'?'selected':''}>완주</option><option value="sets" ${m.metric==='sets'?'selected':''}>지정 세트 이상</option><option value="time" ${m.metric==='time'?'selected':''}>지정 시간 이내</option></select></label><label>조건값<input id="ms_condition_${i}" type="number" min="0" max="999" value="${m.conditionValue||0}" placeholder="세트 또는 초"></label><label>카드팩<select id="ms_reward_${i}">${PACKS_V36.map(p=>`<option value="${p.id}" ${m.reward===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label><label>팩 수<input id="ms_count_${i}" type="number" min="1" max="20" value="${m.rewardCount}"></label><label class="wide" style="grid-column:1/-1">표시 이름<input id="ms_title_${i}" value="${esc(m.title)}"></label></div>`).join('')}<div class="rules">조건값은 ‘지정 세트 이상’일 때 세트 수, ‘지정 시간 이내’일 때 초 단위입니다. 단순 완주는 조건값을 사용하지 않습니다.</div><div class="bonus-actions"><button class="btn" onclick="saveMissionAdminV36()">미션 설정 저장</button><button class="btn alt" onclick="resetMissionAdminV36()">추천 미션으로 초기화</button></div><p class="serverpending">Code.gs 연결 전에는 현재 기기에만 적용됩니다.</p></div>`}
function saveMissionAdminV36(){let s=loadSettingsV36();s.missions=s.missions.map((m,i)=>({...m,active:document.querySelector(`#ms_active_${i}`)?.checked,period:document.querySelector(`#ms_period_${i}`)?.value||'daily',target:Math.max(1,Number(document.querySelector(`#ms_target_${i}`)?.value)||1),game:document.querySelector(`#ms_game_${i}`)?.value||'any',metric:document.querySelector(`#ms_metric_${i}`)?.value||'complete',conditionValue:Math.max(0,Number(document.querySelector(`#ms_condition_${i}`)?.value)||0),reward:document.querySelector(`#ms_reward_${i}`)?.value||'basic',rewardCount:Math.max(1,Number(document.querySelector(`#ms_count_${i}`)?.value)||1),title:document.querySelector(`#ms_title_${i}`)?.value.trim()||m.title}));saveSettingsV36(s);alert('미션 조건과 보상을 저장했습니다.')}
function resetMissionAdminV36(){if(!confirm('미션을 추천 기본값으로 되돌릴까요?'))return;let s=loadSettingsV36();s.missions=cloneV36(DEFAULT_MISSIONS_V36);saveSettingsV36(s);renderV36()}
function periodLabelsV36(){let now=new Date(),mon=mondayV36(now),fri=new Date(mon);fri.setDate(mon.getDate()+4);let last=new Date(now.getFullYear(),now.getMonth()+1,0);return{week:`${dateKeyV36(mon)} ~ ${dateKeyV36(fri)}`,month:`${now.getFullYear()}년 ${now.getMonth()+1}월 1일 ~ ${last.getDate()}일`}}
function rankingAdminV36(){let s=loadSettingsV36(),p=periodLabelsV36(),r=s.ranking;return `<div class="adminpanel"><h3>주간·월간 랭킹 자동 집계</h3><div class="rankperiods"><div class="rankperiod"><b>주간 랭킹</b><span>${p.week}</span><p>매주 월요일 00:00부터 금요일 23:59까지 자동 집계</p><label>랭커 보상<select id="rankWeeklyReward">${PACKS_V36.map(x=>`<option value="${x.id}" ${r.weeklyReward===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>수량<input id="rankWeeklyCount" type="number" min="0" max="20" value="${r.weeklyCount}"></label></div><div class="rankperiod"><b>월간 랭킹</b><span>${p.month}</span><p>매월 1일부터 해당 월의 마지막 날까지 자동 집계</p><label>랭커 보상<select id="rankMonthlyReward">${PACKS_V36.map(x=>`<option value="${x.id}" ${r.monthlyReward===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>수량<input id="rankMonthlyCount" type="number" min="0" max="20" value="${r.monthlyCount}"></label></div></div><button class="btn" onclick="saveRankingAdminV36()">랭킹 보상 설정 저장</button><p class="serverpending">기간 계산은 자동입니다. 실제 전체 학생 순위 집계와 보상 지급은 Code.gs 서버 연결 후 작동합니다.</p></div>`}
function saveRankingAdminV36(){let s=loadSettingsV36();s.ranking.weeklyReward=document.querySelector('#rankWeeklyReward')?.value||'premium';s.ranking.weeklyCount=Math.max(0,Number(document.querySelector('#rankWeeklyCount')?.value)||0);s.ranking.monthlyReward=document.querySelector('#rankMonthlyReward')?.value||'elite';s.ranking.monthlyCount=Math.max(0,Number(document.querySelector('#rankMonthlyCount')?.value)||0);saveSettingsV36(s);alert('주간·월간 랭커 보상 설정을 저장했습니다.')}
function fusionMaterialsV36(rarityId=null){let c=loadCollection(),out=[];RARITIES.forEach(r=>{if(rarityId&&r.id!==rarityId)return;CH.forEach(e=>{let key=e.id+'-'+r.id,n=Math.max(0,(c[key]||0)-1);for(let i=0;i<n;i++)out.push({eventId:e.id,rarityId:r.id,key})})});return out}
function autoFusionV36(rarityId=null){let list=fusionMaterialsV36(rarityId);if(list.length<5)return alert(rarityId?`${rarityById(rarityId).name} 중복 카드가 5장보다 적습니다.`:'합성 가능한 중복 카드가 5장보다 적습니다.');fusionSlotsV34=list.slice(0,5);renderV36()}
const fusionPageV36Base=fusionPageV34;fusionPageV34=function(){let quick=`<div class="fusionquick"><b>한 번에 선택</b><button onclick="autoFusionV36()">낮은 등급부터 5장</button>${RARITIES.map(r=>`<button onclick="autoFusionV36('${r.id}')">${r.name} 5장</button>`).join('')}</div>`;return fusionPageV36Base().replace('<div class="fusionworkspace">',quick+'<div class="fusionworkspace">')}
