function rewardModal(){if(!packReward)return'';let all=packReward.revealed>=packReward.cards.length,current=packReward.revealed,p=packByIdV36(packReward.packType||'basic'),isPack=!!packReward.packType;return `<div class="rewardmodal"><div class="packbox"><h2 class="packtitle">${all?'카드팩 개봉 완료!':'카드팩을 개봉하세요'}</h2>${isPack?`<div class="packlabel">${p.name} · ${packReward.cards.length}장</div>`:''}<p class="packhint">${all?'획득한 카드는 카드 도감에서 크게 볼 수 있습니다.':'짧게 누르면 개봉되고, 덮개를 아래로 드래그하면 위쪽부터 천천히 확인할 수 있습니다.'}</p><div class="packcards">${packReward.cards.map((x,i)=>{let shown=i<current,recent=i===packReward.lastReveal,state=shown?'unveiled':i===current?'covered':'covered queued';return `<div class="packwrap ${state} ${recent?'recent rarity-'+x.rar.id:''}">${collectCard(x.event,x.rar,x.count,false,shown)}${!shown?`<div class="packcover pack-${p.id}" data-pack="${i}" style="--peel:0px" onpointerdown="packDragStart(event,${i})" onpointermove="packDragMove(event)" onpointerup="packDragEnd(event)" onpointercancel="packDragCancel(event)"><span class="packomen"></span></div>`:''}${shown&&recent?`<div class="rarity-banner ${x.rar.id}">${x.rar.name} 등장!</div>`:''}</div>`}).join('')}</div>${all?'<button class="btn" onclick="packReward=null;renderV36()">도감에 보관</button>':'<button class="btn alt" onclick="revealAllPack()">연속 자동 개봉</button>'}</div></div>`}
