/* ===== v3.7 server-ready preview, annual identity and teacher safeguards ===== */
const GAME_ID_V37='french-revolution';
const GAME_API_V37={
  endpoint:'',
  mode:'local-preview',
  async call(action,data={}){
    let requestId=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2));
    let envelope={apiVersion:'3.7',gameId:GAME_ID_V37,action,requestId,student:profile?{schoolYear:profile.schoolYear,grade:profile.grade,classNo:profile.classNo,number:profile.number,name:profile.name}:null,data};
    if(!this.endpoint)return{ok:true,preview:true,requestId,envelope};
    let res=await fetch(this.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(envelope)});
    if(!res.ok)throw new Error('서버 응답 오류 '+res.status);
    return res.json();
  },
  login:data=>GAME_API_V37.call('student.login',data),
  startAttempt:data=>GAME_API_V37.call('attempt.start',data),
  finishAttempt:data=>GAME_API_V37.call('attempt.finish',data),
  openCardPack:data=>GAME_API_V37.call('cards.openPack',data),
  synthesizeCards:data=>GAME_API_V37.call('cards.synthesize',data),
  claimMission:data=>GAME_API_V37.call('missions.claim',data),
  loadCollection:()=>GAME_API_V37.call('cards.collection'),
  teacherAction:(action,data)=>GAME_API_V37.call('teacher.'+action,data)
};
window.GameAPI=GAME_API_V37;
const setProfileV37Base=setProfile;
setProfile=function(p){
  p={...p,schoolYear:Number(p.schoolYear)||new Date().getFullYear()};
  if(location.protocol!=='file:')return setProfileV37Base(p);
  profile={...p,serverBest:0};
  PreviewStore41.setItem('fr-student-v2',JSON.stringify(profile));
  try{P=JSON.parse(PreviewStore41.getItem(key()))||fresh()}catch{P=fresh()}
  practice={mode:null,state:null};speed=null;view='beginner';render();clock()
};
