let packAutoV38=false,packAutoTimerV38=null;
function installV38Style(){if(document.querySelector('#v38-style'))return;let s=document.createElement('style');s.id='v38-style';s.textContent=`
.packvault38{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-top:18px}
.vaultitem38{position:relative;padding:16px;border:1px solid #d3bd91;border-radius:15px;background:#fffaf0;text-align:center}
.vaultitem38 .packitem{width:min(145px,100%);margin:auto}.vaultitem38 h3{margin:10px 0 3px}.vaultcount38{display:inline-grid;place-items:center;min-width:36px;height:36px;border-radius:50%;background:#6e201f;color:#fff;font-weight:900}
.vaultactions38{display:grid;grid-template-columns:minmax(64px,86px) 1fr;justify-content:center;gap:7px;margin-top:11px}.vaultactions38 input{width:100%;min-width:0;border:1px solid #aa8d5d;border-radius:8px;background:#fff;padding:8px;text-align:center;font-weight:800}.vaultactions38 button{border:1px solid #aa8d5d;border-radius:8px;background:#fff;padding:8px 10px;font-weight:800}.vaultactions38 button:disabled{opacity:.42}
.packstage38{position:relative;display:grid;place-items:center;min-height:610px;margin:8px auto;width:min(410px,82vw);perspective:1300px}
.packstage38 .packwrap{position:absolute;width:min(360px,76vw);margin:0}.packstage38 .packwrap.shown{cursor:pointer}.packstage38 .packwrap.exit-left{animation:packExitLeft38 .34s ease-in forwards}
.packprogress38{display:flex;justify-content:center;gap:10px;align-items:center;margin:5px 0 8px}.packprogress38 b{font-size:20px}
.packsummary38{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:25px auto;max-width:620px}.packsummary38 span{padding:10px 5px;border-radius:9px;background:#ffffff13}.packsummary38 b{display:block;font-size:22px}
.packbox.v38{overflow:hidden;max-height:96vh}.packbox.v38 .packhint{animation:none}.packbox.v38 .collectcard.premium .cardname{margin-top:24px;font-size:21px;color:#120905;-webkit-text-stroke:.35px currentColor}
.giftmode38{grid-column:1/-1}.giftcardfields38.hiddenfield,.giftpackfield38.hiddenfield{display:none!important}
.gameframe38{position:relative!important;display:block!important;aspect-ratio:5/6!important;min-height:0!important;overflow:visible!important;border:0!important;border-radius:0!important;background:transparent!important;isolation:isolate}
.gameframe38::after{content:"";position:absolute;z-index:2;inset:0;background:url(assets/legacy/dad2597c335cd220.webp) center/100% 100% no-repeat;pointer-events:none}
.gameframe38 .gameart38{position:absolute!important;z-index:0;left:9.2%!important;right:8.2%!important;top:21%!important;bottom:14.5%!important;width:auto!important;height:auto!important;min-height:0!important;object-fit:cover!important;background-color:#2c251f}
.gameframe38 .decoyscene.gameart38{background-size:400% 400%!important;background-repeat:no-repeat!important}
.gameframe38 .title{position:absolute!important;z-index:3;top:13.7%!important;left:12%!important;right:11%!important;width:auto!important;height:6.5%!important;min-height:0!important;padding:0 3px!important;display:grid!important;place-items:center!important;background:transparent!important;color:#100804!important;text-align:center;font:900 clamp(11px,1.25vw,17px)/1.12 Georgia,'Nanum Myeongjo',serif!important;-webkit-text-stroke:.25px currentColor;overflow:visible!important}
.gameframe38 .gameunit38{position:absolute;z-index:3;left:29%;right:27%;bottom:7.2%;height:7%;display:grid;place-items:center;color:#432a17;font:800 clamp(9px,1vw,13px) Georgia,serif;white-space:nowrap}
.slot.gameframe38 .num,.slot.gameframe38 .remove{z-index:5}.slot.gameframe38.ok{filter:drop-shadow(0 0 7px #16835c)}.slot.gameframe38.bad{filter:drop-shadow(0 0 7px #c2342d)}
@keyframes packExitLeft38{to{transform:translateX(-125%) rotate(-12deg);opacity:0}}
@media(max-width:850px){.packvault38{grid-template-columns:repeat(2,minmax(0,1fr))}.packstage38{min-height:540px}}
@media(max-width:480px){.packvault38{grid-template-columns:1fr 1fr;gap:9px}.vaultitem38{padding:10px 6px}.packstage38{min-height:500px}.packsummary38{grid-template-columns:repeat(3,1fr)}}
`;document.head.appendChild(s)}
function packInventoryKeyV38(){return profile?'fr-v38-pack-vault:'+profile.schoolYear+'-'+profile.grade+'-'+profile.classNo+'-'+profile.number:'fr-v38-pack-vault'}
function loadPackInventoryV38(){let x={counts:{},guarantees:{}};try{x={...x,...JSON.parse(PreviewStore41.getItem(packInventoryKeyV38())||'{}')}}catch{};PACKS_V36.forEach(p=>{x.counts[p.id]=Math.max(0,Number(x.counts[p.id])||0);if(!Array.isArray(x.guarantees[p.id]))x.guarantees[p.id]=[]});return x}
function savePackInventoryV38(x){PreviewStore41.setItem(packInventoryKeyV38(),JSON.stringify(x))}
function addPackInventoryV38(packId,count,source,minIndex=0){let p=packByIdV36(packId),n=Math.max(1,Number(count)||1),x=loadPackInventoryV38();x.counts[p.id]+=n;for(let i=0;i<n;i++)x.guarantees[p.id].push(i===0?Math.max(0,Number(minIndex)||0):0);x.lastSource=source||'보상';savePackInventoryV38(x);return n}
function grantPackV36(packId,count,source,minIndex=0){let n=addPackInventoryV38(packId,count,source,minIndex),p=packByIdV36(packId);packReward=null;alert(p.name+' '+n+'개가 미개봉 카드팩 보관함에 들어왔습니다.');renderV38()}
function grantCards(count,source,minIndex=0){grantPackV36('basic',count,source,minIndex)}
function openStoredPacksV38(packId,amount){let x=loadPackInventoryV38(),available=x.counts[packId]||0,n=amount==='all'?available:Math.min(available,Math.max(1,Number(amount)||1));if(n<1)return;let guarantees=x.guarantees[packId].splice(0,n);x.counts[packId]-=n;savePackInventoryV38(x);let before=loadCollection(),c={...before},cards=[];for(let i=0;i<n;i++)cards.push(drawPackCardV36(packId,c,Number(guarantees[i])||0));markAcquiredV33(cards,before);saveCollection(c);packAutoV38=false;clearTimeout(packAutoTimerV38);packReward={source:'보관함 개봉',cards,packType:packId,cursor:0,phase:'covered',revealed:0,lastReveal:-1};renderV38()}
function packVaultV38(){let x=loadPackInventoryV38(),total=PACKS_V36.reduce((a,p)=>a+x.counts[p.id],0);return '<div class="practicebar"><div><p class="eyebrow">학생별 미개봉 보상</p><h2>🎁 카드팩 보관함 '+total+'개</h2></div><span class="pill">원하는 수량만 개봉</span></div><p>8종 카드팩을 종류별로 보관합니다. 개봉할 수량을 직접 정할 수 있으며 남은 팩은 그대로 보관됩니다.</p><div class="packvault38">'+PACKS_V36.map(p=>{let n=x.counts[p.id];return '<article class="vaultitem38">'+packBackV36(p,true)+'<h3>'+p.name+'</h3><span class="vaultcount38">'+n+'</span><div class="vaultactions38"><input id="openQty38_'+p.id+'" type="number" min="1" max="'+Math.max(1,n)+'" value="1" aria-label="'+p.name+' 개봉 수량" '+(n?'':'disabled')+'><button onclick="openChosenPacksV38(\''+p.id+'\')" '+(n?'':'disabled')+'>선택 수량 개봉</button></div></article>'}).join('')+'</div>'}
function openChosenPacksV38(packId){let available=loadPackInventoryV38().counts[packId]||0,input=document.querySelector('#openQty38_'+packId),n=Math.max(1,Number(input?.value)||1);if(n>available){alert('보관 중인 수량은 '+available+'개입니다.');if(input)input.value=available;return}openStoredPacksV38(packId,n)}
function collectionPage(){let body=collectionModeV34==='book'?collectionBookV34():collectionModeV34==='fusion'?fusionPageV34():packVaultV38();return '<section class="shell"><div class="collectionsubnav"><button class="'+(collectionModeV34==='book'?'on':'')+'" onclick="collectionModeV34=\'book\';renderV38()">📚 카드 도감</button><button class="'+(collectionModeV34==='packs'?'on':'')+'" onclick="collectionModeV34=\'packs\';renderV38()">🎁 미개봉 카드팩</button><button class="'+(collectionModeV34==='fusion'?'on':'')+'" onclick="collectionModeV34=\'fusion\';renderV38()">⚗️ 카드 합성</button></div>'+body+'</section>'}
function gameFrameContentV38(it,artHtml){return artHtml+'<span class="title">'+it.title+'</span><span class="gameunit38">역사 사건</span>'}
function card(m,id,items){let it=items.find(x=>x.id===id);return '<button class="card gameframe38 '+(P[m].selected===id?'sel':'')+'" draggable="true" onclick="cardClick(\''+m+'\','+id+')" ondblclick="cardDouble(event,\''+m+'\','+id+')" ondragstart="dragStart(event,\''+m+'\','+id+')" ondragend="dragEnd()">'+gameFrameContentV38(it,'<img class="gameart38" src="'+IMAGES[it.img-1]+'" alt="">')+'</button>'}
function slot(m,id,i,items){let s=P[m],it=items.find(x=>x.id===id),cl=id?'filled gameframe38':'';if(s.checked&&id)cl+=id===i+1?' ok':' bad';return '<div class="slot '+cl+'" role="button" draggable="'+(id?'true':'false')+'" onclick="slotClick(\''+m+'\','+i+')" ondblclick="slotDouble(event,\''+m+'\','+i+')" ondragstart="dragStart(event,\''+m+'\','+(id||'null')+')" ondragend="dragEnd()" ondragover="event.preventDefault()" ondrop="dropSlot(event,\''+m+'\','+i+')"><span class="num">'+(i+1)+'</span>'+(id?'<button class="remove" aria-label="카드 되돌리기" onclick="event.stopPropagation();removeSlot(\''+m+'\','+i+')">×</button>'+gameFrameContentV38(it,'<img class="gameart38" src="'+IMAGES[it.img-1]+'" alt="">'):'+')+'</div>'}
function bonusCard(kind,id,items,described){let s=bonusState(kind),it=items.find(x=>x.id===id);return '<button class="card gameframe38 '+(s.selected===id?'sel':'')+'" draggable="true" onclick="bonusCardClick(\''+kind+'\','+id+')" ondblclick="bonusCardDouble(event,\''+kind+'\','+id+')" ondragstart="bonusDragStart(event,\''+kind+'\','+id+')" ondragend="dragEnd()">'+gameFrameContentV38(it,'<img class="gameart38" src="'+IMAGES[it.img-1]+'" alt="">')+'</button>'}
function bonusSlot(kind,id,i,items){let s=bonusState(kind),it=items.find(x=>x.id===id),cl=id?'filled gameframe38':'';if(s.checked&&id)cl+=id===i+1?' ok':' bad';return '<div class="slot '+cl+'" role="button" draggable="'+(id?'true':'false')+'" onclick="bonusSlotClick(\''+kind+'\','+i+')" ondblclick="bonusSlotDouble(event,\''+kind+'\','+i+')" ondragstart="bonusDragStart(event,\''+kind+'\','+(id||'null')+')" ondragend="dragEnd()" ondragover="event.preventDefault()" ondrop="bonusDrop(event,\''+kind+'\','+i+')"><span class="num">'+(i+1)+'</span>'+(id?'<button class="remove" aria-label="카드 되돌리기" onclick="event.stopPropagation();bonusRemove(\''+kind+'\','+i+')">×</button>'+gameFrameContentV38(it,'<img class="gameart38" src="'+IMAGES[it.img-1]+'" alt="">'):'+')+'</div>'}
function baitArtV38(x,id){return x.french?'<img class="gameart38" src="'+IMAGES[x.img-1]+'" alt="">':'<span class="decoyscene gameart38" style="background-image:url(\''+DECOY_SHEET+'\');background-position:'+decoyPosition(id)+'"></span>'}
function baitCard(id){let x=baitInfo(id);return '<button class="baitcard gameframe38 '+(bait.selected===id?'sel':'')+'" onclick="baitSelect(\''+id+'\')" ondblclick="baitAuto(event,\''+id+'\')" draggable="true" ondragstart="event.dataTransfer.setData(\'text/plain\',\''+id+'\')">'+gameFrameContentV38(x,baitArtV38(x,id))+'</button>'}
function baitSlot(id,i){let x=id?baitInfo(id):null,cl=id?'filled gameframe38':'';if(bait.checked&&id)cl+=id==='f'+(i+1)?' ok':' bad';return '<div class="slot '+cl+'" onclick="baitPlace('+i+')" ondblclick="baitRemove(event,'+i+')" ondragover="event.preventDefault()" ondrop="baitDrop(event,'+i+')"><span class="num">'+(i+1)+'</span>'+(id?gameFrameContentV38(x,baitArtV38(x,id)):'+')+'</div>'}
function normalizePackRewardV38(){if(!packReward)return;if(!Array.isArray(packReward.cards))packReward.cards=[];if(!Number.isInteger(packReward.cursor))packReward.cursor=Math.max(0,Number(packReward.revealed)||0);if(!packReward.phase)packReward.phase=packReward.cursor>=packReward.cards.length?'done':'covered';if(!packReward.packType)packReward.packType='basic'}
function revealPack(i){normalizePackRewardV38();if(!packReward||packReward.phase!=='covered'||i!==packReward.cursor)return;packReward.phase='shown';packReward.revealed=packReward.cursor+1;packReward.lastReveal=packReward.cursor;renderV38()}
function advancePackV38(){if(!packReward||packReward.phase!=='shown')return;let el=document.querySelector('.packstage38 .packwrap');if(el)el.classList.add('exit-left');setTimeout(()=>{if(!packReward)return;packReward.cursor++;packReward.phase=packReward.cursor>=packReward.cards.length?'done':'covered';renderV38()},330)}
function closePackV38(){clearTimeout(packAutoTimerV38);packAutoV38=false;packReward=null;renderV38()}
function toggleAutoPackV38(){packAutoV38=!packAutoV38;clearTimeout(packAutoTimerV38);renderV38()}
function revealAllPack(){packAutoV38=true;renderV38()}
function schedulePackAutoV38(){clearTimeout(packAutoTimerV38);if(!packAutoV38||!packReward||packReward.phase==='done')return;packAutoTimerV38=setTimeout(()=>{if(!packReward)return;if(packReward.phase==='covered')revealPack(packReward.cursor);else if(packReward.phase==='shown')advancePackV38()},packReward.phase==='covered'?520:1050)}
function rewardModal(){if(!packReward)return'';normalizePackRewardV38();let p=packByIdV36(packReward.packType||'basic'),i=Number(packReward.cursor)||0,total=packReward.cards.length,done=packReward.phase==='done'||i>=total;if(done){let sums={normal:0,rare:0,unique:0,legend:0,myth:0};packReward.cards.forEach(x=>sums[x.rar.id]++);return '<div class="rewardmodal"><div class="packbox v38"><h2 class="packtitle">카드팩 개봉 완료!</h2><p>획득한 카드 '+total+'장이 도감에 보관되었습니다.</p><div class="packsummary38">'+RARITIES.map(r=>'<span>'+r.name+'<b>'+sums[r.id]+'</b></span>').join('')+'</div><button class="btn" onclick="closePackV38()">확인</button></div></div>'}let x=packReward.cards[i],shown=packReward.phase==='shown',omen=!shown&&rarityIndexV30(x.rar)>=2?' omen-'+x.rar.id:'';return '<div class="rewardmodal"><div class="packbox v38"><h2 class="packtitle">'+p.name+'</h2><div class="packprogress38"><b>'+(i+1)+' / '+total+'</b><span>'+(shown?(i+1<total?'확인하면 다음 카드로 이동합니다.':'마지막 카드입니다.'):'가운데 카드를 눌러 개봉')+'</span></div><div class="packstage38"><div class="packwrap '+(shown?'shown recent rarity-'+x.rar.id:'covered'+omen)+'" '+(shown?'onclick="advancePackV38()" role="button"':'')+'>'+collectCard(x.event,x.rar,x.count,false,false)+(shown?'<div class="rarity-banner '+x.rar.id+'">'+x.rar.name+' 등장!</div>':'<div class="packcover pack-'+p.id+'" data-crest="'+p.crest+'" data-pack="'+i+'" style="--peel:0px" onpointerdown="packDragStart(event,'+i+')" onpointermove="packDragMove(event)" onpointerup="packDragEnd(event)" onpointercancel="packDragCancel(event)"><span class="packomen"></span></div>')+'</div></div><div class="bonus-actions" style="justify-content:center"><button class="btn alt" onclick="closePackV38()">닫기</button>'+(shown?'<button class="btn" onclick="advancePackV38()">'+(i+1<total?'확인 · 다음 카드':'확인')+'</button>':'')+'</div></div></div>'}
