function giftAdmin(){let y=profile?.schoolYear||new Date().getFullYear();return '<div class="adminpanel"><h3>카드·카드팩 지급</h3><div class="adminform"><label>지급 대상<select id="giftTarget" onchange="syncGiftTarget()"><option value="school">학년도 전체 학생</option><option value="grade">학년 전체</option><option value="class">학년·반 전체</option><option value="student">특정 학생</option><option value="current">현재 시험 학생</option></select></label><label>수량<input id="giftCount" type="number" min="1" max="50" value="1"></label><label class="giftmode38">지급 종류<select id="giftKind38" onchange="syncGiftModeV38()"><option value="pack">미개봉 카드팩</option><option value="card">특정 조건의 카드</option></select></label><label id="giftPackWrap38" class="giftpackfield38">카드팩 종류<select id="giftPack38">'+PACKS_V36.map(p=>'<option value="'+p.id+'">'+p.name+'</option>').join('')+'</select></label><div id="giftCardFields38" class="giftcardfields38 hiddenfield"><label>보유 조건<select id="giftOwnership"><option value="any">보유 여부 관계없이</option><option value="unowned">미보유 카드만</option></select></label><label>사건<select id="giftEvent"><option value="random">무작위 사건</option>'+CH.map(x=>'<option value="'+x.id+'">'+x.title+'</option>').join('')+'</select></label><label>등급<select id="giftRarity"><option value="random">무작위 등급</option>'+RARITIES.map(x=>'<option value="'+x.id+'">'+x.name+'</option>').join('')+'</select></label></div></div><div class="targetfields"><label id="targetYearWrap">학년도<input id="targetYear" type="number" value="'+y+'"></label><label id="targetGradeWrap" class="hiddenfield">학년<input id="targetGrade" type="number" value="'+(profile?.grade||2)+'"></label><label id="targetClassWrap" class="hiddenfield">반<input id="targetClass" type="number" value="'+(profile?.classNo||1)+'"></label><label id="targetNumberWrap" class="hiddenfield">번호<input id="targetNumber" type="number" value="'+(profile?.number||1)+'"></label><label id="targetNameWrap" class="hiddenfield">이름<input id="targetName" value="'+esc(profile?.name||'')+'"></label></div><div class="giftcombo"><b>미개봉 카드팩 지급</b><br><span id="giftTargetHelp">'+y+'학년도에 등록된 전체 학생에게 지급합니다.</span><br>지급된 팩은 학생 보관함에 종류별로 쌓입니다.</div><div class="bonus-actions"><button class="btn" onclick="testGiftCurrent()">현재 학생에게 시험 지급</button><button class="btn alt" onclick="previewBulkGift()">선택 대상 지급 확인</button></div></div>'}
function testGiftCurrent(){let n=Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),kind=document.querySelector('#giftKind38')?.value||'pack';if(kind==='pack'){let id=document.querySelector('#giftPack38')?.value||'basic';addPackInventoryV38(id,n,'교사 시험 지급');alert(packByIdV36(id).name+' '+n+'개를 현재 학생의 보관함에 넣었습니다.');collectionModeV34='packs';view='collection';renderV38();return}let ev=document.querySelector('#giftEvent')?.value||'random',rv=document.querySelector('#giftRarity')?.value||'random',unowned=document.querySelector('#giftOwnership')?.value==='unowned',before=loadCollection(),c={...before},cards=[];for(let i=0;i<n;i++){let pick=giftCandidateV35(c,ev,rv,unowned);if(!pick)break;c[pick.key]=(c[pick.key]||0)+1;cards.push({event:pick.event,rar:pick.rar,count:c[pick.key]})}if(!cards.length)return alert('선택 조건에 맞는 카드가 없습니다.');markAcquiredV33(cards,before);saveCollection(c);packAutoV38=false;packReward={source:'교사 직접 지급',cards,packType:'basic',cursor:0,phase:'covered',revealed:0,lastReveal:-1};renderV38()}
function previewBulkGift(){syncGiftTarget();let kind=document.querySelector('#giftKind38')?.value||'pack',reservation={id:'gift-'+Date.now(),createdAt:new Date().toISOString(),target:document.querySelector('#giftTarget')?.value||'school',schoolYear:Number(document.querySelector('#targetYear')?.value)||profile?.schoolYear,grade:document.querySelector('#targetGrade')?.value||'',classNo:document.querySelector('#targetClass')?.value||'',number:document.querySelector('#targetNumber')?.value||'',name:document.querySelector('#targetName')?.value||'',kind,packType:document.querySelector('#giftPack38')?.value||'basic',count:Math.max(1,Number(document.querySelector('#giftCount')?.value)||1),ownership:document.querySelector('#giftOwnership')?.value||'any',event:document.querySelector('#giftEvent')?.value||'random',rarity:document.querySelector('#giftRarity')?.value||'random'};let q=JSON.parse(PreviewStore41.getItem('fr-v38-gift-reservation-draft')||'[]');q.push(reservation);PreviewStore41.setItem('fr-v38-gift-reservation-draft',JSON.stringify(q));alert('지급 예약안을 저장했습니다. Code.gs 연결 후 선택한 학생들의 보관함에 전달됩니다.')}
