function cardInspectModal(){if(!cardInspect)return'';let q=cardInspect.event,i=CH.findIndex(x=>x.id===q.id),prev=CH[i-1],next=CH[i+1],rar=cardInspect.rar;return '<div class="cardinspect" onclick="cardInspect=null;renderV40()"><div class="inspectpanel" onclick="event.stopPropagation()"><button class="inspectclose" onclick="cardInspect=null;renderV40()" aria-label="닫기">×</button><div class="flipscene"><div class="flipinner '+(cardInspect.flipped?'flipped':'')+'"><div class="flipface" onclick="flipInspect(event)">'+collectCard(q,rar,cardInspect.count,false,false)+'</div><div class="flipface flipback '+rar.id+'" style="--metal:'+(rar.id==='legend'?'#ffd45b':rar.id==='unique'?'#bf7aff':rar.id==='rare'?'#87b9f4':rar.id==='myth'?'#9ffeff':'#9a7b52')+'" onclick="flipInspect(event)"><div class="backcontent"><div class="backbadge"><span>'+(i+1)+'</span></div><p class="eyebrow">프랑스 혁명의 흐름 · '+(i+1)+'/14</p><h2>'+q.title+'</h2><div class="backmeaning">'+CARD_DETAIL_V39[q.id]+'</div><div class="flowrow"><div class="flowitem"><small>이전 사건</small><br>'+(prev?prev.title:'혁명의 배경')+'</div><b>→</b><div class="flowitem"><small>다음 사건</small><br>'+(next?next.title:'나폴레옹 시대')+'</div></div><p class="backhint">카드를 누르면 앞면으로 돌아갑니다.</p></div></div></div></div><p class="inspecttip">카드를 누르면 부드럽게 뒤집힙니다. 바깥을 누르면 닫힙니다.</p></div></div>'}
function gameArtV39(it){let src=imageSrcV40(it.img-1),focus=CARD_FOCUS_V40[it.id]||'50% 40%';return '<span class="gameart38" style="--focus:'+focus+'"><img src="'+src+'" alt="" loading="lazy" decoding="async"></span>'}
function packResultCardV39(x){let q=CH.find(e=>e.id===x.event.id)||x.event;return '<article class="packresult39 '+x.rar.id+'"><img src="'+imageSrcV40(q.img-1)+'" alt="" loading="lazy" decoding="async"><strong>'+q.title+'</strong><small>'+x.rar.name+'</small></article>'}
const shellV40Base=shell;shell=function(body){return shellV40Base(body).replaceAll('v3.9','v4.0')}
function renderV40(){installV40Style();renderV39();document.title='프랑스 혁명 학습 게임 v4.0';if(app?.innerHTML)app.innerHTML=app.innerHTML.replaceAll('v3.9','v4.0')}
